window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0114", [{"word":"storm","ipa_uk":"/stɔːm/","ipa_us":"/stɔːrm/","definition_zh":"风暴；暴风雨；风暴般的情感或言论爆发；猛攻；怒气冲冲地走","definition_en":"a violent atmospheric disturbance with strong winds and usually rain or snow, or a sudden violent outburst of feeling or activity","core_image":"气压骤降的海面上，乌云压低到桅杆顶，整片天空像被掀翻过来","scene":"渔港的清晨，铅灰云墙从海面压过来，缆绳被风扯得呜呜作响。A storm closed the harbour before the boats could return.","sceneCN":"这里指「强风伴随降水的大气剧烈扰动」（第 1 个义项：风力达到风暴级别的天气系统）；句意为风暴在渔船返港之前封住了港口。图中可辨识物件：压低的云墙、绷紧的缆绳、翻白的浪、空荡的码头。","pos":[{"tag":"n.","zh":"风暴；暴风雨；爆发；风波"},{"tag":"v.","zh":"猛攻；怒气冲冲地走"}],"collocations":[{"phrase":"a storm of protest","zh":"抗议的风暴"},{"phrase":"storm warning","zh":"风暴警报"},{"phrase":"take by storm","zh":"一举征服；迅速拿下"},{"phrase":"weather the storm","zh":"渡过难关"},{"phrase":"storm surge","zh":"风暴潮"},{"phrase":"storm out","zh":"怒气冲冲地离开"}],"forms":[{"label":"复数","form":"storms"},{"label":"三单（第三人称单数）","form":"storms"},{"label":"过去式","form":"stormed"},{"label":"过去分词","form":"stormed"},{"label":"现在分词","form":"storming"},{"label":"形容词（有暴风雨的）","form":"stormy"}],"derivatives":[{"word":"stormy","pos":"adj.","zh":"有暴风雨的；争吵激烈的"},{"word":"storminess","pos":"n.","zh":"风暴频发的状态；激烈程度"},{"word":"sandstorm","pos":"n.","zh":"沙暴"},{"word":"storm surge","pos":"n.","zh":"风暴潮"},{"word":"stormbound","pos":"adj.","zh":"被风暴困住的"}],"senses":[{"no":"01","title":"Violent weather with strong wind","titleCN":"强风伴随降水的剧烈天气","definition":"a weather disturbance with very strong winds, usually with rain, snow or hail","definitionCN":"伴有极强风力、通常还带雨雪或冰雹的天气扰动","example":"A storm closed the harbour before the boats could return.","exampleCN":"风暴在渔船返港之前封住了港口。","why":"The word names the atmosphere in revolt: wind speed and low pressure matter more than how much rain falls.","whyCN":"这个词命名的是大气本身的失控：风速与低气压比降水量更关键。"},{"no":"02","title":"An organised low-pressure system","titleCN":"气象学意义上的低压风暴系统","definition":"a cyclonic low-pressure system with closed circulation, tracked on weather charts","definitionCN":"天气图上可追踪、具有闭合环流的低压气旋系统","example":"Forecasters tracked the storm across the Atlantic for four days.","exampleCN":"预报员连续四天追踪这个风暴横跨大西洋。","why":"Meteorology turned the everyday word into a technical label for an organised centre of low pressure.","whyCN":"气象学把日常词变成了对「有组织的低压中心」的技术标签。"},{"no":"03","title":"A violent outburst of feeling or protest","titleCN":"情感或抗议的猛烈爆发","definition":"a sudden, intense outburst of emotion, criticism or activity","definitionCN":"情感、批评或活动突然而猛烈的爆发","example":"A storm of protest followed the announcement.","exampleCN":"公告一出，抗议如暴风般涌来。","why":"Weather imagery moves easily to crowds: many voices at once sound like wind.","whyCN":"天气意象很容易转到人群：众声同时响起，听上去就像风。"},{"no":"04","title":"To attack and capture by sudden force","titleCN":"突袭并攻占","definition":"to attack a fortified place suddenly and forcefully in order to take it","definitionCN":"以突然而猛烈的力量攻击设防地点并占领","example":"The battalion stormed the hill before the defenders could regroup.","exampleCN":"守军还没来得及重整，该营已强攻上山。","why":"An assault breaks on a wall the way a squall breaks on a coast, so the noun became a verb of attack.","whyCN":"强攻撞上城墙，正像飑风撞上海岸，于是名词转为进攻动词。"},{"no":"05","title":"To leave in anger","titleCN":"怒气冲冲地走开","definition":"to move or leave somewhere quickly and angrily","definitionCN":"怒气冲冲地迅速离开某处","example":"She stormed out of the meeting without a word.","exampleCN":"她一言不发，怒气冲冲地离开了会场。","why":"Body language repeats the weather: a person's departure can be as abrupt as a squall.","whyCN":"身体动作复现了天气：一个人离场可以像飑风一样突然。"},{"no":"06","title":"A dense shower of flying objects","titleCN":"密集飞来的物体","definition":"a heavy, continuous fall of objects such as arrows, shells or stones","definitionCN":"箭、炮弹或石块等物体密集连续地飞来","example":"A storm of arrows fell on the wall.","exampleCN":"密集的箭雨落在城墙上。","why":"The sense extends the image from wind to whatever the wind is imagined to carry.","whyCN":"这一义项把意象从风扩展到想象中由风裹挟的一切。"},{"no":"07","title":"To conquer rapidly, as an audience","titleCN":"迅速彻底地征服观众或市场","definition":"to win over an audience or market very quickly and completely, chiefly in the phrase take by storm","definitionCN":"迅速而彻底地征服观众或市场，主要用于「一举拿下」这一短语","example":"The young band took the festival by storm.","exampleCN":"这支年轻乐队一举征服了音乐节。","why":"Take by storm keeps the military image but swaps a fortress for public attention.","whyCN":"「一举拿下」保留军事意象，只是把堡垒换成了公众注意力。"},{"no":"08","title":"A turbulent upheaval in affairs","titleCN":"人事中的剧烈动荡","definition":"a period of violent change or controversy in politics, business or private life","definitionCN":"政治、商业或私人生活中剧烈变动或争议的时期","example":"The reform provoked a storm inside the ministry.","exampleCN":"这项改革在部内掀起了一场风波。","why":"The abstract sense is the last step: the weather is now entirely metaphorical, a disturbance in human affairs.","whyCN":"抽象义是最后一步：天气完全成为隐喻，指人事中的扰动。"}],"etymology":{"intro":{"en":"Storm goes back to Old English storm, from Proto-Germanic *sturmaz 'storm, tumult'. German Sturm and Dutch storm are exact cognates. The deeper Indo-European link is a reconstruction, and no Latin word descends from the same stock.","cn":"storm 可追溯到古英语 storm，源自原始日耳曼 *sturmaz「风暴、骚动」。德语 Sturm 与荷兰语 storm 是精确同源词。更深的印欧关联属于重构，拉丁语中没有从同一词干派生的词。"},"items":[{"era":"OLD ENGLISH","en":"Storm is recorded in Old English as storm, already covering both bad weather and a tumult among people.","cn":"storm 在古英语中已写作 storm，既指恶劣天气，也指人群中的骚动。"},{"era":"PROTO-GERMANIC *STURMAZ","en":"The reconstructed Germanic base *sturmaz underlies German Sturm, Dutch storm and Old Norse stormr, all naming a violent weather disturbance.","cn":"重构的日耳曼词干 *sturmaz 是德语 Sturm、荷兰语 storm 与古诺斯语 stormr 的共同来源，都指剧烈的天气扰动。"},{"era":"PIE RECONSTRUCTION *(S)TUR-","en":"A commonly proposed deeper source is *(s)tur- 'to swirl, to be turbulent'. This is a reconstruction, not a demonstrated derivation, and several dictionaries decline to commit to it.","cn":"更深的来源常被拟为 *(s)tur-「旋转、翻腾」。这属于重构形式，并非已证实的派生，若干词典并不据此定论。"},{"era":"MILITARY VERB","en":"From the sixteenth century the noun turned into a verb meaning to attack a fortified place, because an assault was imagined as a weather front breaking on a wall.","cn":"从 16 世纪起，该名词转为动词，指攻击设防地点，因为强攻被想象成天气锋面撞上墙壁。"},{"era":"OUTBURST SENSE","en":"The figurative sense of a storm of applause or protest appears by the seventeenth century, when weather imagery was applied to crowds and feelings.","cn":"到 17 世纪，已出现「掌声或抗议的风暴」这类比喻义，天气意象被用于人群与情绪。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Germanic history of the word is unsettled, and every Indo-European form offered for it is a reconstruction rather than a recorded ancestor.","cn":"来源不确定（更深词源）：该词在日耳曼语之前的历史无定论，凡为其给出的印欧形式均属重构，而非有记录的祖形。"}]},"similar":{"note":{"en":"Group one holds forms built on the same word or on the same compound pattern and easily confused with it; group two holds near neighbours from the same weather field.","cn":"第一组是同词或同复合模式构成、极易混淆的形式；第二组是同一天气语义场里的近邻词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stormy","ipa":"/ˈstɔːmi/","tag":"same root, adjective","definition":"Storm plus -y: full of storm, and by extension angry or heated, as a stormy debate.","definitionCN":"由 storm 加 -y 构成：充满风暴的，引申指激烈的，如激烈的辩论。"},{"word":"sandstorm","ipa":"/ˈsændstɔːm/","tag":"compound, not a Latin cousin","definition":"Sand plus storm: a desert wind that lifts sand into a wall; the second element is the same word, the first is native English.","definitionCN":"由 sand 加 storm 构成：沙漠风把沙粒卷成沙墙；后半是同一个词，前半为英语本族成分。"},{"word":"stormbound","ipa":"/ˈstɔːmbaʊnd/","tag":"compound adjective","definition":"Storm plus bound: unable to leave because of the weather, said of ships, villages and travellers.","definitionCN":"由 storm 加 bound 构成：因天气被困而无法离开，用于船只、村庄与旅人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gale","ipa":"/ɡeɪl/","tag":"wind strength only","definition":"A wind of force eight or above; it names the wind itself, not the whole weather system.","definitionCN":"八级以上的强风；只指风本身，不指整个天气系统。"},{"word":"tempest","ipa":"/ˈtempɪst/","tag":"literary register","definition":"A literary word for a violent storm, often carrying a sense of chaos rather than weather data.","definitionCN":"猛烈的风暴的文学用词，常偏指混乱而非气象数据。"},{"word":"squall","ipa":"/skwɔːl/","tag":"short and sharp","definition":"A sudden, brief burst of strong wind, often with rain or snow; duration, not size, sets it apart.","definitionCN":"突然而短暂的强风，常伴雨雪；区别在持续时间而非规模。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real cognates, real collocations and real word-family links, not invented rhymes.","cn":"正常联想：真实的同源词、真实搭配与真实词族关系，而非编造的顺口溜。"},"normal":[{"en":"The same noun serves weather and feeling: a storm of protest.","cn":"同一个名词既指天气也指情绪：抗议的风暴。"},{"en":"The cognates are exact: German Sturm, Dutch storm, Old Norse stormr.","cn":"同源关系精确：德语 Sturm、荷兰语 storm、古诺斯语 stormr。"},{"en":"Fixed phrases separate the senses: storm warning, storm surge, weather the storm.","cn":"固定搭配区分义项：风暴警报、风暴潮、渡过难关。"},{"en":"The verb has two lives: troops stormed the gate, and she stormed out.","cn":"动词有两种用法：部队强攻城门，以及她怒气冲冲地离开。"},{"en":"Take by storm is the idiom for winning an audience overnight.","cn":"「一举拿下」是形容一夜之间征服观众的固定说法。"}],"abstract":[{"en":"Picture a sea that refuses to hold its shape for even one minute.","cn":"想象一片连一分钟都不肯保持形状的海。"},{"en":"Picture a room where everyone speaks at once and the sound becomes wind.","cn":"想象一屋子人同时开口，声音汇成了风。"},{"en":"Picture a wall that looks solid until the whole sky leans against it.","cn":"想象一堵看似坚固的墙，直到整片天空朝它压过来。"}]},"examples":[{"en":"The fishing fleet stayed in port while the storm passed.","cn":"风暴过境期间，渔船队留在港内。"},{"en":"A storm of complaints followed the new timetable.","cn":"新时刻表一出，投诉如暴风般涌来。"},{"en":"The battalion stormed the hill before the defenders could regroup.","cn":"守军还没来得及重整，该营已强攻上山。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「撕脱木」——狂风把木头整片撕脱下来 → 风暴、猛攻","word":"storm"},"root":"古英语 storm「暴风雨」，源自原始日耳曼 *sturmaz；与德语 Sturm、荷兰语 storm、古诺斯语 stormr 同源。更深来源一般认为是印欧 *(s)tur-「旋转」，属重构形式；无可靠拉丁同族，latinEntries 留空。","sensesIntro":{"en":"Eight senses follow one movement: the air loses its calm, and that loss is then repeated in crowds, in assaults and in a single angry exit.","cn":"八个义项沿同一个动作展开：空气失去平静，这一失控再依次复现在人群、强攻与一次愤怒的离场中。"},"semanticMap":{"core":{"en":"CORE IMAGE: a low sky pressing down on a sea that will not stay still.","cn":"核心意象：低垂的天空压在一片不肯平静的海上。"},"chain":["WIND RISES","PRESSURE FALLS","CLOUD WALL","OUTBURST","ASSAULT","UPHEAVAL"],"branches":[{"senses":"01 · 02","en":"WEATHER SYSTEM: from a loose everyday storm to a charted low-pressure centre, the same disturbance is seen at two levels of precision.","cn":"天气系统：从日常所说的风暴到天气图上的低压中心，是同一种扰动在两种精度下的呈现。"},{"senses":"03","en":"HUMAN OUTBURST: many voices at once reproduce the sound of wind.","cn":"人的爆发：众声同时响起，复现了风的声音。"},{"senses":"04 · 05","en":"SUDDEN FORCE: an assault and an angry exit both borrow the squall's abruptness.","cn":"突然的力量：强攻与愤然离场都借用了飑风的突然性。"},{"senses":"06","en":"CARRIED OBJECTS: the wind image is transferred to whatever it is imagined to carry.","cn":"被裹挟之物：风的意象被转到想象中由它携带的一切。"},{"senses":"07 · 08","en":"METAPHOR COMPLETE: a fortress and a ministry are both taken as weather.","cn":"隐喻完成：堡垒与部委都被当作天气来处理。"}]},"affixes":{"intro":{"en":"Storm is a native Germanic root, so its word-building uses English suffixes and combining forms rather than Latin elements.","cn":"storm 是日耳曼语本族词根，因此它的构词使用英语后缀与复合成分，而非拉丁语素。"},"latinIntro":{"en":"No Latin word shares this root; the productive material here is Germanic and English.","cn":"没有拉丁词与这个词根同源；这里的构词材料来自日耳曼语与英语。"},"items":[{"word":"storm","structure":"storm (Old English noun and verb)","meaning":"violent weather; to attack","meaningCN":"剧烈天气；猛攻","example":"The base carries both the weather and the assault.","exampleCN":"这个词根同时承载天气与强攻两层意思。"},{"word":"-y","structure":"-y (adjective suffix, 'having the quality of')","meaning":"full of; characterized by","meaningCN":"充满；具有……特征","example":"Stormy weather lasted three days.","exampleCN":"暴风雨天气持续了三天。"},{"word":"-iness","structure":"-iness (noun suffix from -y adjectives)","meaning":"the state of being","meaningCN":"……的状态","example":"The storminess of the coast keeps boats in port.","exampleCN":"海岸的风暴频发使船只滞港。"},{"word":"sand-","structure":"sand (combining noun)","meaning":"sand carried by wind","meaningCN":"被风携带的沙","example":"A sandstorm buried the road.","exampleCN":"沙暴把道路掩埋了。"},{"word":"-bound","structure":"-bound (combining adjective, 'confined')","meaning":"unable to move","meaningCN":"无法移动；被困","example":"The village was stormbound for a week.","exampleCN":"村子被风暴困了一个星期。"},{"word":"storm surge","structure":"storm + surge (compound noun)","meaning":"sea level pushed up by a storm","meaningCN":"风暴把海面推高形成的增水","example":"The storm surge flooded the lower streets.","exampleCN":"风暴潮淹没了低处的街道。"},{"word":"storm warning","structure":"storm + warning (compound noun)","meaning":"an official alert for violent weather","meaningCN":"针对剧烈天气的官方警报","example":"A storm warning closed the ferry route.","exampleCN":"风暴警报使渡轮航线停运。"},{"word":"-chaser","structure":"-chaser (agent compound from chase)","meaning":"one who pursues","meaningCN":"追逐者","example":"Storm chasers drove toward the wall cloud.","exampleCN":"追风者朝云墙方向开去。"},{"word":"storm door","structure":"storm + door (compound noun)","meaning":"an extra outer door for bad weather","meaningCN":"为恶劣天气加装的门外门","example":"He fitted a storm door before winter.","exampleCN":"入冬前他装了一道防风外门。"}],"latinEntries":[]}},{"word":"thunderstorm","ipa_uk":"/ˈθʌndəstɔːm/","ipa_us":"/ˈθʌndərstɔːrm/","definition_zh":"雷暴；产生雷电的对流天气；强雷暴；比喻喧闹的风波","definition_en":"a convective storm that produces thunder and lightning, usually with heavy rain and sometimes hail or strong wind","core_image":"平原上竖起一座高耸的云塔，云底翻卷发黑，云中不断亮起又熄灭的电光","scene":"平原的闷热午后，云底开始旋转下压，远处传来第一声闷响。A thunderstorm built a dark, rotating base above the fields.","sceneCN":"这里指「产生雷电的对流性天气系统」（第 1 个义项：云中电荷分离并放电的雷暴）；句意为雷暴在田野上方筑起旋转的暗色云底。图中可辨识物件：高耸的云塔、翻卷的云底、云中的电光、被压暗的田地。","pos":[{"tag":"n.","zh":"雷暴；雷暴雨；喧闹的风波"}],"collocations":[{"phrase":"severe thunderstorm","zh":"强雷暴"},{"phrase":"thunderstorm warning","zh":"雷暴警报"},{"phrase":"thunderstorm cell","zh":"雷暴单体"},{"phrase":"thunderstorm day","zh":"雷暴日"},{"phrase":"afternoon thunderstorm","zh":"午后雷暴"},{"phrase":"a thunderstorm of criticism","zh":"批评的狂风暴雨"}],"forms":[{"label":"复数","form":"thunderstorms"},{"label":"强雷暴（术语）","form":"severe thunderstorm"},{"label":"雷暴单体（术语）","form":"thunderstorm cell"},{"label":"雷暴日（气候统计）","form":"thunderstorm day"},{"label":"形容词（有雷的）","form":"thundery"}],"derivatives":[{"word":"thundery","pos":"adj.","zh":"有雷的；闷雷似的"},{"word":"thunderous","pos":"adj.","zh":"雷鸣般的；轰隆作响的"},{"word":"thundercloud","pos":"n.","zh":"雷云"},{"word":"thunderhead","pos":"n.","zh":"雷暴云砧顶"},{"word":"thunderbolt","pos":"n.","zh":"霹雳；雷电"}],"senses":[{"no":"01","title":"A storm that produces thunder and lightning","titleCN":"产生雷电的对流性风暴","definition":"a convective storm that produces thunder and lightning, usually with heavy rain","definitionCN":"产生雷电、通常伴有强降水的对流性风暴","example":"A thunderstorm built a dark, rotating base above the fields.","exampleCN":"雷暴在田野上方筑起旋转的暗色云底。","why":"Thunder plus storm: the compound names a storm defined by the sound and light it makes, not by rainfall alone.","whyCN":"由雷与风暴复合而成：这个词以声音和电光来定义风暴，而不只看降水量。"},{"no":"02","title":"A convective cell in meteorology","titleCN":"气象学上的对流单体","definition":"an organised updraft cell in which warm moist air rises, cools and releases latent heat","definitionCN":"暖湿空气上升、冷却并释放潜热的有组织上升气流单体","example":"Doppler radar showed a single thunderstorm cell growing over the ridge.","exampleCN":"多普勒雷达显示有一个雷暴单体在山脊上发展。","why":"Forecasters use the word for the unit of convection itself, because that unit is what a radar can follow.","whyCN":"预报员用这个词指对流的基本单元，因为雷达追踪的正是这个单元。"},{"no":"03","title":"A short-lived single-cell storm","titleCN":"生命史短暂的单单体雷暴","definition":"a brief single-cell storm whose updraft and downdraft share one column and die within an hour","definitionCN":"上升与下沉气流共用同一气柱、通常一小时内消散的短时单单体风暴","example":"The afternoon thunderstorm lasted barely forty minutes.","exampleCN":"这场午后雷暴只持续了不到四十分钟。","why":"The single-cell type is the simplest case: one column rises, rains itself out and collapses.","whyCN":"单单体是最简单的情形：一根气柱上升、把自己下成雨，然后坍塌。"},{"no":"04","title":"A multicell or supercell system","titleCN":"多单体或超级单体雷暴系统","definition":"a larger storm in which several cells line up, or one rotating updraft persists for hours","definitionCN":"多个单体排列成线、或单一旋转上升气流持续数小时的更大风暴","example":"A supercell thunderstorm kept its rotating updraft for three hours.","exampleCN":"一个超级单体雷暴维持旋转上升气流达三小时。","why":"Once cells share a common inflow, the storm stops behaving like a single brief column.","whyCN":"当多个单体共享同一入流，风暴就不再像一根短暂的气柱了。"},{"no":"05","title":"A severe thunderstorm","titleCN":"达到强雷暴标准的雷暴","definition":"a thunderstorm that meets severity criteria such as large hail, damaging wind or a tornado","definitionCN":"达到大冰雹、破坏性大风或龙卷等强度标准的雷暴","example":"The warning was issued because the thunderstorm carried hail the size of golf balls.","exampleCN":"之所以发布警报，是因为这场雷暴带着高尔夫球大小的冰雹。","why":"Severity is a legal and operational threshold, not a poetic judgement, so the word gains a fixed technical edge.","whyCN":"「强」是业务与法规上的阈值，而非文学判断，因此这个词获得了固定的技术边界。"},{"no":"06","title":"A dry thunderstorm","titleCN":"降水稀少的干雷暴","definition":"a thunderstorm whose rain evaporates before reaching the ground, leaving only lightning and wind","definitionCN":"雨水在落地前蒸发、只留下闪电与强风的雷暴","example":"A dry thunderstorm started three fires on the ridge.","exampleCN":"一场干雷暴在山脊上引发了三次火情。","why":"When the rain never arrives, lightning becomes the whole story, which is why fire services watch this type closely.","whyCN":"当雨始终落不下来，闪电就成了全部内容，因此消防部门格外关注这一类。"},{"no":"07","title":"A thunderstorm day in climate records","titleCN":"气候统计中的雷暴日","definition":"a day on which thunder is heard at a station, counted as a climate statistic","definitionCN":"观测站听到雷声的一天，作为气候统计计入","example":"The station averages thirty thunderstorm days a year.","exampleCN":"该站平均每年有三十个雷暴日。","why":"Climatology needs a countable unit, so it counts days with thunder rather than individual cells.","whyCN":"气候学需要一个可计数的单位，于是统计听到雷声的日子，而非单个单体。"},{"no":"08","title":"A noisy uproar, metaphorically","titleCN":"比喻喧闹的激烈风波","definition":"a loud, chaotic outburst of criticism or conflict likened to a storm","definitionCN":"被比作雷暴的、喧闹混乱的批评或冲突爆发","example":"The proposal set off a thunderstorm of criticism in the press.","exampleCN":"该提案在媒体上引发了一场批评的雷暴。","why":"The compound gives metaphor a louder and more sudden image than plain storm, which is why it suits public uproar.","whyCN":"比起单说风暴，这个复合词提供更响、更突然的意象，因此适合形容公共喧闹。"}],"etymology":{"intro":{"en":"Thunderstorm is an English compound of two native words, thunder and storm. It is recorded from the seventeenth century, once the compound was needed to name a storm defined by thunder and lightning. No Latin element enters the word.","cn":"thunderstorm 是由两个本族词雷与风暴构成的英语复合词，17 世纪起有记录，当时需要用这个复合词来指以雷电为特征的storm。该词不含拉丁语素。"},"items":[{"era":"OLD ENGLISH PARTS","en":"Thunder goes back to Old English thunor and storm to Old English storm; both elements are Germanic and were already common weather words.","cn":"thunder 可溯至古英语 thunor，storm 可溯至古英语 storm；两个成分都属日耳曼语，且早已是常用天气词。"},{"era":"SEVENTEENTH-CENTURY COMPOUND","en":"The joined form thunderstorm appears in English writing in the seventeenth century as a plain descriptive compound.","cn":"合并形式 thunderstorm 在 17 世纪出现在英语书面语中，是一个直白的描述性复合词。"},{"era":"METEOROLOGICAL TECHNICAL SENSE","en":"Nineteenth- and twentieth-century meteorology narrowed the word to a convective cell with lightning, and later to classified types.","cn":"19 至 20 世纪的气象学把该词收窄为带闪电的对流单体，随后又分出类型。"},{"era":"CELL CLASSIFICATION","en":"Modern forecasting separates single-cell, multicell and supercell thunderstorms according to how their updrafts are organised.","cn":"现代预报按上升气流的组织方式，把雷暴分为单单体、多单体与超级单体。"},{"era":"SEVERITY CRITERIA","en":"A severe thunderstorm is defined by hail, damaging wind or a tornado rather than by rainfall, a twentieth-century operational standard.","cn":"强雷暴以冰雹、破坏性大风或龙卷来界定，而不以降水量界定，这是 20 世纪的业务标准。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): dictionary dates for the first use of the compound differ by several decades, and no single citation is treated as authoritative; the word's formation itself is not in doubt.","cn":"来源不确定（仅首见年代）：各词典给出的复合词首见年代相差数十年，没有单一书证被视为权威；但该词的构成方式本身并无疑义。"}]},"similar":{"note":{"en":"Group one holds the two source words and the cloud-part term most often mistaken for the whole storm; group two holds neighbouring convective terms.","cn":"第一组是两个来源词，以及最容易被误当作整个雷暴的云体部位名；第二组是相近的对流术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"storm","ipa":"/stɔːm/","tag":"base word, wider","definition":"The second element alone: any violent wind storm, with or without lightning.","definitionCN":"复合词的后半单独使用：任何剧烈风暴，有雷电与否均可。"},{"word":"thunder","ipa":"/ˈθʌndə/","tag":"sound only","definition":"The first element alone: the sound of the discharge, with no rain and no storm implied.","definitionCN":"复合词的前半单独使用：只指放电发出的声音，不含降雨或风暴。"},{"word":"thunderhead","ipa":"/ˈθʌndəhed/","tag":"part of a cloud","definition":"The towering upper part of a cumulonimbus, not the storm as a whole.","definitionCN":"积雨云高耸的上部，而不是整个雷暴。"}]},{"heading":"NEAR MEANING","entries":[{"word":"squall line","ipa":"/skwɔːl laɪn/","tag":"a line of storms","definition":"A long line of convective cells that moves as one front; it may contain many thunderstorms.","definitionCN":"作为一条锋面整体移动的长条对流单体带，其中可含多个雷暴。"},{"word":"supercell","ipa":"/ˈsuːpəsel/","tag":"one type of it","definition":"A rotating thunderstorm with a persistent mesocyclone; the name is a subtype, not a synonym.","definitionCN":"具有持续中气旋的旋转雷暴；该名称是下位类型，并非同义词。"},{"word":"hailstorm","ipa":"/ˈheɪlstɔːm/","tag":"named by its precipitation","definition":"A storm named for the hail it drops, which may or may not be a thunderstorm.","definitionCN":"以落下的冰雹命名的风暴，它未必是雷暴。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real source words, the real classification and the real operational threshold.","cn":"正常联想：两个真实的来源词、真实的分型与真实的业务标准。"},"normal":[{"en":"Thunder plus storm: the storm is named by the sound it makes.","cn":"雷加风暴：这场风暴以它发出的声音命名。"},{"en":"Three types by updraft: single cell, multicell, supercell.","cn":"按上升气流分三类：单单体、多单体、超级单体。"},{"en":"Severe means hail, damaging wind or a tornado, not heavy rain.","cn":"「强」指冰雹、破坏性大风或龙卷，而不是大雨。"},{"en":"Climate counts thunderstorm days, not individual cells.","cn":"气候统计计雷暴日，而不计单个单体。"},{"en":"A dry thunderstorm drops lightning without rain reaching the ground.","cn":"干雷暴只落下闪电，雨水到不了地面。"}],"abstract":[{"en":"Picture a chimney that builds itself, rains inside itself and then collapses.","cn":"想象一根自己长出来、在自己内部下雨、随后坍塌的烟囱。"},{"en":"Picture a crowd whose shouting is so loud that it sounds like weather.","cn":"想象一群人的喊声大到听起来像天气。"},{"en":"Picture a fire started by a storm that brought no water.","cn":"想象一场没带水来的风暴点着了火。"}]},"examples":[{"en":"The pilot diverted around a line of thunderstorms over the plains.","cn":"飞行员绕开了平原上空的一列雷暴。"},{"en":"Severe thunderstorm warnings are issued when hail or damaging wind is expected.","cn":"预计出现冰雹或破坏性大风时，会发布强雷暴警报。"},{"en":"The station logs a thunderstorm day whenever thunder is heard.","cn":"只要听到雷声，该站就记一个雷暴日。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「thunder（雷）+ storm（风暴）」——打雷下雨的风暴 → 雷暴","word":"thunderstorm"},"root":"英语本族复合词：thunder（古英语 thunor，原始日耳曼 *thunraz）+ storm（古英语 storm，原始日耳曼 *sturmaz）。不含拉丁语素，latinEntries 留空。","sensesIntro":{"en":"Eight senses run from the plain weather event to its technical cell, its classified types, its severity threshold, its climate count and finally its use as a metaphor for uproar.","cn":"八个义项从日常天气现象，依次走到技术上的对流单体、分类类型、强度阈值、气候计数，最后用作喧闹风波之喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tower of cloud that carries its own engine, its own light and its own collapse.","cn":"核心意象：一座自带发动机、自带电光、也自带坍塌的云塔。"},"chain":["WARM AIR RISES","CLOUD TOWER","CHARGE SEPARATES","LIGHTNING","DOWNBURST","COLLAPSE"],"branches":[{"senses":"01 · 02","en":"THE EVENT AND ITS UNIT: the everyday storm and the radar cell are the same object at two scales.","cn":"事件与其单元：日常所说的雷暴与雷达追踪的单体，是同一对象在两种尺度上。"},{"senses":"03 · 04","en":"ORGANISATION: one column dies fast; many cells or one rotating updraft last for hours.","cn":"组织方式：单根气柱很快消散；多单体或单一旋转上升气流能维持数小时。"},{"senses":"05","en":"THRESHOLD: severity is fixed by hail, wind or tornado, not by rain.","cn":"阈值：强度由冰雹、大风或龙卷界定，而不是由雨界定。"},{"senses":"06","en":"NO RAIN: when precipitation evaporates aloft, lightning stands alone.","cn":"无雨：当降水在高空蒸发，闪电便独自登场。"},{"senses":"07 · 08","en":"COUNT AND METAPHOR: climate turns it into days, rhetoric turns it into noise.","cn":"计数与比喻：气候学把它变成天数，修辞把它变成喧闹。"}]},"affixes":{"intro":{"en":"Thunderstorm is a transparent English compound, so its parts and its combining patterns can be read directly.","cn":"thunderstorm 是一个透明的英语复合词，其成分与复合模式可以直接读出。"},"latinIntro":{"en":"Both elements are Germanic weather words; no Latin prefix or root takes part in the compound.","cn":"两个成分都是日耳曼语天气词，复合过程中没有拉丁前缀或词根参与。"},"items":[{"word":"thunder-","structure":"thunder (Old English thunor, first element)","meaning":"the sound of atmospheric discharge","meaningCN":"大气放电发出的声音","example":"Thunder rolled over the valley.","exampleCN":"雷声滚过山谷。"},{"word":"-storm","structure":"storm (Old English storm, second element)","meaning":"violent weather","meaningCN":"剧烈天气","example":"The storm tore the sails.","exampleCN":"风暴撕破了船帆。"},{"word":"thundery","structure":"thunder + -y (adjective)","meaning":"accompanied by thunder","meaningCN":"伴有雷声的","example":"A thundery afternoon kept the climbers low.","exampleCN":"一个有雷的午后让登山者留在低处。"},{"word":"thunderous","structure":"thunder + -ous (adjective)","meaning":"like thunder; very loud","meaningCN":"雷鸣般的；极响的","example":"The hall broke into thunderous applause.","exampleCN":"大厅里爆发出雷鸣般的掌声。"},{"word":"thundercloud","structure":"thunder + cloud (compound noun)","meaning":"a cloud that produces thunder","meaningCN":"产生雷声的云","example":"A thundercloud darkened the pass.","exampleCN":"雷云把山口压暗了。"},{"word":"thunderhead","structure":"thunder + head (compound noun)","meaning":"the anvil top of a cumulonimbus","meaningCN":"积雨云的砧状顶","example":"The thunderhead spread across the horizon.","exampleCN":"雷暴云砧在地平线上铺开。"},{"word":"thunderstorm cell","structure":"thunderstorm + cell (technical compound)","meaning":"one convective unit of a storm","meaningCN":"雷暴的一个对流单元","example":"Radar followed the cell for an hour.","exampleCN":"雷达追踪该单体达一小时。"},{"word":"thunderstorm warning","structure":"thunderstorm + warning (compound noun)","meaning":"an official alert for severe storms","meaningCN":"针对强雷暴的官方警报","example":"The warning covered three counties.","exampleCN":"警报覆盖了三个县。"},{"word":"thunderstorm day","structure":"thunderstorm + day (climatological compound)","meaning":"a day on which thunder is heard","meaningCN":"听到雷声的一天","example":"The map plots thunderstorm days per year.","exampleCN":"该图绘出每年的雷暴日数。"}],"latinEntries":[]}},{"word":"lightning","ipa_uk":"/ˈlaɪtnɪŋ/","ipa_us":"/ˈlaɪtnɪŋ/","definition_zh":"闪电；一次放电；雷击；球状闪电；闪电般的；突如其来的打击","definition_en":"the bright flash of atmospheric electricity, or a single discharge of it, often striking the ground","core_image":"漆黑云层里骤然裂开一道折线状的白光，瞬间照亮整片原野又立刻消失","scene":"雷雨夜里，一道白光把路旁的老橡树从中间劈开。A single lightning strike split the old oak beside the road.","sceneCN":"这里指「大气放电产生的闪电，一次击中地面」（第 1 个义项：云地之间的一次放电通道）；句意为一次雷击把路旁的老橡树劈成两半。图中可辨识物件：折线状的电光、被劈裂的树干、雨幕、被照亮的路面。","pos":[{"tag":"n.","zh":"闪电；雷击；闪电般的事物"},{"tag":"adj.","zh":"闪电般的；极快的"}],"collocations":[{"phrase":"lightning strike","zh":"雷击"},{"phrase":"lightning rod","zh":"避雷针"},{"phrase":"lightning bolt","zh":"一道闪电"},{"phrase":"lightning speed","zh":"闪电般的速度"},{"phrase":"ball lightning","zh":"球状闪电"},{"phrase":"lightning storm","zh":"雷电交加的风暴"}],"forms":[{"label":"复数（罕见，指多次放电）","form":"lightnings"},{"label":"动词（发闪电，罕用）","form":"lighten"},{"label":"形容词（闪电般的）","form":"lightning-fast"},{"label":"复合名词（避雷针）","form":"lightning rod"},{"label":"复合名词（雷击）","form":"lightning strike"}],"derivatives":[{"word":"lightning rod","pos":"n.","zh":"避雷针；替人挡责者"},{"word":"lightning bolt","pos":"n.","zh":"一道闪电"},{"word":"lightning bug","pos":"n.","zh":"萤火虫（美式）"},{"word":"lightning strike","pos":"n.","zh":"雷击"},{"word":"lightning-fast","pos":"adj.","zh":"极快的"}],"senses":[{"no":"01","title":"The flash of atmospheric electricity","titleCN":"大气放电形成的闪电","definition":"the bright flash produced when electrical charge in a cloud discharges through the air","definitionCN":"云中电荷通过空气放电时产生的明亮闪光","example":"A single lightning strike split the old oak beside the road.","exampleCN":"一次雷击把路旁的老橡树劈成两半。","why":"The noun names the visible event, the flash, rather than the invisible charge that causes it.","whyCN":"这个名词命名的是可见的事件——那道闪光，而不是造成它的不可见电荷。"},{"no":"02","title":"A single discharge stroke","titleCN":"一次放电回击","definition":"one return stroke of a discharge, which may repeat several times within a single flash","definitionCN":"一次放电的回击，同一道闪光内可重复数次","example":"Instruments recorded four strokes inside one lightning flash.","exampleCN":"仪器记录到一道闪电内包含四次回击。","why":"Physics needs to separate the flash we see from the strokes that compose it.","whyCN":"物理学需要把肉眼所见的闪光与构成它的回击分开。"},{"no":"03","title":"A strike that hits something","titleCN":"击中物体的雷击","definition":"a discharge that reaches the ground or an object and damages it","definitionCN":"到达地面或某物体并造成损害的放电","example":"Lightning struck the church tower twice that summer.","exampleCN":"那年夏天，雷击了教堂塔楼两次。","why":"Once the flash touches something, the event becomes an impact with consequences.","whyCN":"当闪光触到某物，事件就变成了一次有后果的撞击。"},{"no":"04","title":"Ball lightning","titleCN":"球状闪电","definition":"a rare glowing sphere reported to float for seconds after a strike","definitionCN":"雷击后据报可漂浮数秒的罕见发光球体","example":"Witnesses described ball lightning drifting through the kitchen.","exampleCN":"目击者描述球状闪电飘过厨房。","why":"The subtype keeps the base word and adds a shape, because the phenomenon is still classed as a discharge.","whyCN":"这一下位类型保留原词并加上形状，因为该现象仍被归入放电。"},{"no":"05","title":"Extremely fast, as an attributive","titleCN":"闪电般极快的（定语用法）","definition":"used before a noun to mean extremely quick, as in lightning speed or a lightning response","definitionCN":"置于名词前表示极快，如闪电般的速度或反应","example":"The agency mounted a lightning response to the outbreak.","exampleCN":"该机构对疫情作出了闪电般的响应。","why":"Speed is read off the flash: the light appears and is gone before the eye can follow.","whyCN":"速度是从闪光读出来的：光出现又消失，眼睛来不及跟上。"},{"no":"06","title":"A very brief visit or event","titleCN":"极短暂的一次到访或事件","definition":"a short, intense visit or event that begins and ends almost at once","definitionCN":"开始与结束几乎同时发生的短暂而强烈的到访或事件","example":"The minister made a lightning visit to the flooded town.","exampleCN":"部长对受淹城镇做了一次闪电式访问。","why":"The metaphor borrows duration, not electricity: what matters is that there is almost no interval.","whyCN":"这一比喻借用的是时长而非电：要点在于几乎没有间隔。"},{"no":"07","title":"A sudden shock of insight or disaster","titleCN":"突如其来的灵感或打击","definition":"a sudden, illuminating idea or a sudden destructive event likened to a flash","definitionCN":"被比作闪光的突然顿悟，或突然的破坏性事件","example":"The solution came to her like lightning in the middle of the night.","exampleCN":"答案在半夜像闪电一样击中了她。","why":"Both insight and catastrophe arrive without warning, which is the single feature the metaphor keeps.","whyCN":"顿悟与灾祸都不打招呼就到，这正是该比喻保留的唯一特征。"},{"no":"08","title":"Sheet lightning without audible thunder","titleCN":"只现光而听不到雷的片状闪电","definition":"a diffuse flash seen without a distinct channel, usually from a distant storm whose thunder is unheard","definitionCN":"看不到清晰通道的弥散闪光，通常来自雷声已不可闻的远处风暴","example":"Heat lightning flickered along the southern horizon all evening.","exampleCN":"整个傍晚，南边地平线上闪着无声的片状闪电。","why":"When the stroke is too far away for sound, only the illuminated cloud sheet remains visible.","whyCN":"当放电太远、声音传不到时，剩下的只有被照亮的云幕。"}],"etymology":{"intro":{"en":"Lightning began as lightening, the verbal noun of lighten 'to flash', and lost its medial e in the modern spelling. The verb goes back to Old English lēoht 'light', a Germanic word whose Indo-European stock also produced Latin lux.","cn":"lightning 最初写作 lightening，是动词 lighten「发闪」的动名词，现代拼写中丢掉了中间的 e。该动词可溯至古英语 lēoht「光」，这一日耳曼词所属的印欧词干也产生了拉丁 lux。"},"items":[{"era":"OLD ENGLISH LEOHT","en":"Old English lēoht meant 'light, brightness' and also 'not heavy', a pair of senses still kept by the modern word light.","cn":"古英语 lēoht 既指「光、明亮」，也指「不重」，现代词 light 仍保留这两组意思。"},{"era":"LIGHTENING","en":"In Middle English the flashing was called lightening, the -ing noun of the verb lighten 'to flash'; the modern spelling dropped the e.","cn":"中古英语把闪电现象称作 lightening，即动词 lighten「发闪」的 -ing 名词；现代拼写丢掉了那个 e。"},{"era":"GERMANIC COGNATES","en":"German Leuchten 'to shine' and Dutch licht belong to the same Germanic stock, so the word is native rather than borrowed.","cn":"德语 Leuchten「发光」与荷兰语 licht 属同一日耳曼词干，因此该词是本族词而非借词。"},{"era":"LATIN COGNATE, NOT SOURCE","en":"Latin lux, lucis 'light' and lucere 'to shine' are distant cousins through Indo-European *leuk-, not ancestors of the English word.","cn":"拉丁 lux, lucis「光」与 lucere「发光」经印欧 *leuk- 与之远亲同源，并非英语词的祖先。"},{"era":"METEOROLOGICAL SENSE","en":"Only the weather sense survives in ordinary use; the verb lighten in the sense 'to flash' is now archaic.","cn":"日常使用中只剩天气义；动词 lighten 的「发闪」义现已古旧。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (spelling history): the loss of the medial e is usually explained by contraction in fast speech, but no single documented path is agreed.","cn":"来源不确定（拼写史）：中间 e 的脱落通常用快速语流中的缩合解释，但没有公认的单一文献路径。"}]},"similar":{"note":{"en":"Group one holds the words most often confused with lightning by spelling; group two holds names for the same flash or for its parts.","cn":"第一组是拼写最易与本词混淆的词；第二组是同一道闪光或其组成部分的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lighten","ipa":"/ˈlaɪtn/","tag":"different word, easily confused","definition":"To make lighter or less heavy, or to brighten; despite the shared letters it is not the modern noun for the flash.","definitionCN":"使更轻或更亮；尽管字形相近，它并不是现代指闪电的名词。"},{"word":"lighting","ipa":"/ˈlaɪtɪŋ/","tag":"one letter apart","definition":"The equipment or design of lights in a room or on a stage; it has nothing to do with weather.","definitionCN":"房间或舞台的灯具与布光；与天气无关。"},{"word":"lightning rod","ipa":"/ˈlaɪtnɪŋ rɒd/","tag":"derived compound","definition":"A metal rod that carries a strike safely to earth; the compound keeps the base word unchanged.","definitionCN":"把雷击安全导入地面的金属杆；复合词保留原词形不变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bolt","ipa":"/bəʊlt/","tag":"a single shaft","definition":"A shaft of lightning, or the act of striking; shorter and more concrete than the phenomenon itself.","definitionCN":"一道闪电，或一次击中；比作为现象的闪电更短、更具体。"},{"word":"flash","ipa":"/flæʃ/","tag":"the visible moment","definition":"The instant of light, not the electrical process that lies behind it.","definitionCN":"光出现的那一瞬，而非其背后的放电过程。"},{"word":"thunderbolt","ipa":"/ˈθʌndəbəʊlt/","tag":"literary and mythic","definition":"A lightning stroke imagined as a weapon, common in myth and older prose.","definitionCN":"被想象成武器的雷击，多见于神话与旧体散文。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real source verb, the real cognates and the real compounds.","cn":"正常联想：真实的来源动词、真实的同源词与真实的复合词。"},"normal":[{"en":"The word was once lightening, the -ing noun of the verb lighten 'to flash'.","cn":"该词原本写作 lightening，即动词「发闪」的 -ing 名词。"},{"en":"Latin lux and lucere are cousins through the same Indo-European stock, not ancestors.","cn":"拉丁 lux 与 lucere 是同一印欧词干的远亲，而不是祖先。"},{"en":"Compounds keep the base unchanged: lightning rod, lightning bolt, lightning strike.","cn":"复合词保留原词形：避雷针、一道闪电、雷击。"},{"en":"Resultative verb pattern: lightning struck the tower.","cn":"结果动词模式：闪电击中了塔楼。"},{"en":"The attributive use carries speed: lightning speed, a lightning response.","cn":"定语用法承载速度义：闪电般的速度、闪电般的响应。"}],"abstract":[{"en":"Picture a crack in the dark that lasts less than a heartbeat.","cn":"想象黑暗里裂开一道缝，持续时间不到一次心跳。"},{"en":"Picture a whole room lit for an instant, then darker than before.","cn":"想象整间屋子亮了一瞬，随后比先前更暗。"},{"en":"Picture an idea arriving with no warning and no sound.","cn":"想象一个念头毫无预警、毫无声响地到来。"}]},"examples":[{"en":"Lightning lit the valley three times before the rain began.","cn":"雨落下之前，闪电把山谷照亮了三次。"},{"en":"The tower has been fitted with a lightning rod since the fire.","cn":"那场火灾之后，塔楼装上了避雷针。"},{"en":"News of the verdict spread at lightning speed.","cn":"裁决的消息以闪电般的速度传开。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「light（光）+ ning」——黑云里骤然亮起的光 → 闪电","word":"lightning"},"root":"由动词 lighten「发闪」的 -ing 名词 lightening 缩合而来，可溯至古英语 lēoht「光」；与德语 Leuchten、荷兰语 licht 同源，并与拉丁 lux、lucere 经印欧 *leuk- 远亲同源。","sensesIntro":{"en":"Eight senses move from the flash itself to a single stroke, its impact, a rare spherical form, then to speed, brevity, sudden shock and the distant sheet flash.","cn":"八个义项从闪光本身，走到单次回击、击中物体、罕见的球状形态，再走到速度、短暂、突然冲击与远处的片状闪光。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crack of white light that exists for an instant and then leaves the world darker.","cn":"核心意象：一道只存在一瞬、随后让世界更暗的白光裂缝。"},"chain":["CHARGE BUILDS","AIR BREAKS DOWN","FLASH","RETURN STROKE","IMPACT","AFTERIMAGE"],"branches":[{"senses":"01 · 02","en":"EVENT AND UNIT: the visible flash and the single stroke are one discharge seen at two scales.","cn":"事件与单位：可见的闪光与单次回击，是同一次放电在两种尺度上。"},{"senses":"03 · 04","en":"WHERE IT LANDS: a strike gains consequences; a rare spherical form gains a shape.","cn":"落在何处：击中某物便有了后果；罕见的球状形态则有了形状。"},{"senses":"05 · 06","en":"BORROWED SPEED: the flash lends its instant to responses and visits.","cn":"借来的速度：闪光把它的瞬间借给响应与到访。"},{"senses":"07","en":"SUDDEN ARRIVAL: insight and disaster both come without warning.","cn":"突然到来：顿悟与灾祸都不打招呼就到。"},{"senses":"08","en":"FAR-OFF LIGHT: when sound cannot reach, only the lit cloud sheet is left.","cn":"远方之光：声音到不了时，只剩被照亮的云幕。"}]},"affixes":{"intro":{"en":"Lightning is a deverbal noun from a native verb, so its parts are English and Germanic rather than Latin.","cn":"lightning 是由本族动词派生的动名词，其成分属英语与日耳曼语，而非拉丁语。"},"latinIntro":{"en":"Latin lux and lucere are cognate at the Indo-European level only; they are quoted here as cousins, not as sources.","cn":"拉丁 lux 与 lucere 仅在印欧语层面同源；此处把它们作为远亲引用，而非来源。"},"items":[{"word":"light","structure":"light (Old English lēoht, noun and adjective)","meaning":"brightness; not heavy","meaningCN":"光亮；不重","example":"The base supplies both brightness and lightness.","exampleCN":"这个词根同时提供「光」与「轻」两层意思。"},{"word":"-en","structure":"-en (verb-forming suffix)","meaning":"to make or become","meaningCN":"使……；变得……","example":"The sky lightened before dawn.","exampleCN":"天亮前天空变亮了。"},{"word":"-ing","structure":"-ing (noun suffix from verbs)","meaning":"the act or event of","meaningCN":"……的动作或事件","example":"The lightening was visible for miles.","exampleCN":"数英里外都能看见那次闪电。"},{"word":"lightning rod","structure":"lightning + rod (compound noun)","meaning":"a conductor that takes the strike","meaningCN":"承接雷击的导体","example":"The rod ran down the side of the barn.","exampleCN":"避雷针沿着谷仓侧面接到地面。"},{"word":"lightning bolt","structure":"lightning + bolt (compound noun)","meaning":"a single shaft of lightning","meaningCN":"一道闪电","example":"A bolt scorched the fence post.","exampleCN":"一道闪电把栅栏柱烧焦了。"},{"word":"lightning bug","structure":"lightning + bug (compound noun, American)","meaning":"a firefly","meaningCN":"萤火虫","example":"Lightning bugs rose from the wet grass.","exampleCN":"萤火虫从湿草里飞起。"},{"word":"lightning strike","structure":"lightning + strike (compound noun)","meaning":"an impact by lightning","meaningCN":"雷击","example":"The strike felled a pine.","exampleCN":"雷击放倒了一棵松树。"},{"word":"-fast","structure":"-fast (combining adjective, 'firm, quick')","meaning":"fixed or rapid","meaningCN":"牢固的；迅速的","example":"The door was lightning-fast to open.","exampleCN":"那扇门开得极快。"},{"word":"lightning speed","structure":"lightning + speed (compound noun)","meaning":"extremely high speed","meaningCN":"极快的速度","example":"The reply came at lightning speed.","exampleCN":"回复以极快的速度到来。"}],"latinEntries":[{"word":"lux","structure":"lux, lucis (f., third declension)","meaning":"light, brightness","meaningCN":"光；明亮"},{"word":"lucere","structure":"lucere, luxi (verb, second conjugation)","meaning":"to shine, to be light","meaningCN":"发光；明亮"},{"word":"lumen","structure":"lumen, luminis (n., third declension)","meaning":"light, a light source","meaningCN":"光；光源"}]}},{"word":"thunder","ipa_uk":"/ˈθʌndə/","ipa_us":"/ˈθʌndər/","definition_zh":"雷；雷声；雷鸣般的巨响；怒喝；轰隆作响地移动；发出威吓","definition_en":"the loud sound heard after a lightning discharge, or a similarly loud and threatening noise","core_image":"云层深处一声闷响滚过山谷，声音像有重量一样压下来","scene":"雨停之后很久，低沉的雷声才从山谷那头滚过来。Thunder rolled across the valley long after the rain had stopped.","sceneCN":"这里指「雷电放电产生的雷声」（第 1 个义项：云中放电引起的声波）；句意为雨停很久之后，雷声仍从山谷那头滚过。图中可辨识物件：远处发暗的云底、山谷轮廓、被雨打湿的岩壁、仍未散尽的雨雾。","pos":[{"tag":"n.","zh":"雷；雷声；雷鸣般的响声"},{"tag":"v.","zh":"打雷；轰隆作响；怒喝"}],"collocations":[{"phrase":"thunder and lightning","zh":"雷电交加"},{"phrase":"a clap of thunder","zh":"一声霹雳"},{"phrase":"a thunder of applause","zh":"雷鸣般的掌声"},{"phrase":"steal someone's thunder","zh":"抢走别人的风头"},{"phrase":"thunder against","zh":"大声抨击"},{"phrase":"distant thunder","zh":"远处的雷声"}],"forms":[{"label":"复数（罕用）","form":"thunders"},{"label":"三单（第三人称单数）","form":"thunders"},{"label":"过去式","form":"thundered"},{"label":"过去分词","form":"thundered"},{"label":"现在分词","form":"thundering"},{"label":"形容词（雷鸣般的）","form":"thunderous"}],"derivatives":[{"word":"thunderous","pos":"adj.","zh":"雷鸣般的；轰隆作响的"},{"word":"thunderously","pos":"adv.","zh":"雷鸣般地"},{"word":"thundery","pos":"adj.","zh":"有雷的；闷雷似的"},{"word":"thunderbolt","pos":"n.","zh":"霹雳；雷电"},{"word":"thundercloud","pos":"n.","zh":"雷云"}],"senses":[{"no":"01","title":"The sound made by a discharge","titleCN":"放电产生的雷声","definition":"the loud sound caused by the rapid heating and expansion of air along a lightning channel","definitionCN":"闪电通道中空气被迅速加热膨胀而产生的巨响","example":"Thunder rolled across the valley long after the rain had stopped.","exampleCN":"雨停很久之后，雷声仍从山谷那头滚过。","why":"The word names what the ear receives, not the electricity that produced it.","whyCN":"这个词命名的是耳朵接收到的声音，而不是产生它的电。"},{"no":"02","title":"To produce thunder, impersonally","titleCN":"打雷（无人称用法）","definition":"used with it as subject to say that thunder is happening","definitionCN":"以空主语表示正在打雷","example":"It thundered all night and the river rose by morning.","exampleCN":"整夜打雷，到早晨河水就涨了。","why":"Weather verbs often take an empty subject because no agent can be named.","whyCN":"天气动词常用空主语，因为说不出是谁在动作。"},{"no":"03","title":"A loud rumbling like thunder","titleCN":"雷鸣般的轰隆巨响","definition":"a deep, rolling noise resembling thunder, as of hooves, traffic or applause","definitionCN":"像雷声一样低沉滚动的巨响，如马蹄声、车流声或掌声","example":"A thunder of hooves came up the lane.","exampleCN":"一阵雷鸣般的马蹄声从巷子那头传来。","why":"The comparison works because low rolling sound is the shared feature, not the weather.","whyCN":"这一比喻成立，是因为共同点在于低沉滚动的声音，而非天气。"},{"no":"04","title":"To shout angrily at someone","titleCN":"对人大声怒喝","definition":"to speak very loudly and angrily to someone","definitionCN":"怒气冲冲地大声对某人说话","example":"The coach thundered at the players from the touchline.","exampleCN":"教练在边线上对着球员大声咆哮。","why":"Anger borrows the storm's volume; the mouth becomes the cloud.","whyCN":"愤怒借用了风暴的音量：嘴成了云。"},{"no":"05","title":"To move with a loud rumbling","titleCN":"轰隆作响地移动","definition":"to move forward heavily and noisily, as a train or a column of vehicles","definitionCN":"沉重而喧响地向前移动，如火车或车队","example":"Freight trains thundered through the station without stopping.","exampleCN":"货运列车轰隆隆地穿过车站，没有停下。","why":"The sound of the object is again described by the sound of weather.","whyCN":"这里又是用天气的声音来描述物体的声音。"},{"no":"06","title":"To utter threats or condemnation","titleCN":"发出威吓或猛烈抨击","definition":"to declare threats or strong condemnation in a loud, forceful way","definitionCN":"以响亮有力的方式发出威胁或强烈谴责","example":"The editorial thundered against the new tax.","exampleCN":"那篇社论猛烈抨击新税。","why":"Public denunciation was once imagined as a voice from the sky, so the verb kept that weight.","whyCN":"公开谴责曾被想象成来自天空的声音，因此这个动词保留了那种分量。"},{"no":"07","title":"A sign of approaching weather","titleCN":"预示天气变化的雷声","definition":"distant thunder heard as a warning that a storm is approaching","definitionCN":"远处传来的雷声，作为风暴临近的征兆","example":"Distant thunder sent the climbers back to the hut.","exampleCN":"远处的雷声让登山者撤回小屋。","why":"Because sound travels farther than rain, thunder is heard before the storm arrives.","whyCN":"因为声音比雨传得更远，所以雷声总在风暴到达之前被听到。"},{"no":"08","title":"Overwhelming authority or pressure","titleCN":"压倒性的权威或压力","definition":"an overwhelming display of power, opinion or authority felt as a loud force","definitionCN":"如巨响般压下来的权力、舆论或权威展示","example":"The report landed with the thunder of a committee that had lost patience.","exampleCN":"这份报告带着一个失去耐心的委员会的分量砸了下来。","why":"The abstract sense keeps only the impression of irresistible volume.","whyCN":"抽象义只保留了那种不可抵挡的声势印象。"}],"etymology":{"intro":{"en":"Thunder is Old English thunor, from Proto-Germanic *thunraz, and is cognate with Latin tonitrus and tonare through the same Indo-European root *(s)tenh₂- 'to resound'.","cn":"thunder 是古英语 thunor，源自原始日耳曼 *thunraz，并经同一印欧词根 *(s)tenh₂-「回响」与拉丁 tonitrus、tonare 同源。"},"items":[{"era":"OLD ENGLISH THUNOR","en":"Old English thunor named both the sound and the god of thunder, and the word kept the weather sense after the god's name split off as Thor.","cn":"古英语 thunor 既指雷声，也指雷神；雷神之名分出去成为托尔之后，这个词保留了天气义。"},{"era":"PROTO-GERMANIC *THUNRAZ","en":"German Donner and Old Norse Þórr descend from the same Germanic base, so the cognate set is broad and exact.","cn":"德语 Donner 与古诺斯语 Þórr 出自同一日耳曼词干，因此同源词群既广又明确。"},{"era":"PIE *(S)TENH2-","en":"The Indo-European root *(s)tenh₂- 'to resound, to thunder' is reconstructed from several branches; it is a reconstruction, not a recorded form.","cn":"印欧词根 *(s)tenh₂-「回响、打雷」由多个语支重构而来，属重构形式，并非有记录的词形。"},{"era":"LATIN COGNATES","en":"Latin tonare 'to thunder' and tonitrus 'thunder' are cousins through that same root, not sources of the English word.","cn":"拉丁 tonare「打雷」与 tonitrus「雷」经同一词根与之远亲同源，并非英语词的来源。"},{"era":"VERBAL AND FIGURATIVE USE","en":"From the fourteenth century the noun supplied a verb; by the seventeenth it also meant to denounce loudly.","cn":"14 世纪起名词衍生出动词；到 17 世纪又指大声谴责。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the precise Indo-European shape and the split between the weather word and the god's name are reconstructed, and not every dictionary accepts the same root.","cn":"来源不确定（更深词源）：印欧词形的具体面貌，以及天气词与神名之间的分化，均为重构；各家词典采纳的词根并不一致。"}]},"similar":{"note":{"en":"Group one holds forms built directly on this word; group two holds other loud low sounds that are often used as synonyms.","cn":"第一组直接由本词构成；第二组是常被当作同义词使用的其他低沉巨响。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"thunderous","ipa":"/ˈθʌndərəs/","tag":"same root, adjective","definition":"Thunder plus -ous: as loud as thunder, as in thunderous applause.","definitionCN":"由 thunder 加 -ous：像雷一样响，如雷鸣般的掌声。"},{"word":"thunderbolt","ipa":"/ˈθʌndəbəʊlt/","tag":"compound noun","definition":"Thunder plus bolt: a stroke of lightning imagined as a missile, not a sound.","definitionCN":"由 thunder 加 bolt：被想象成投掷物的雷击，而不是声音。"},{"word":"thundercloud","ipa":"/ˈθʌndəklaʊd/","tag":"compound noun","definition":"Thunder plus cloud: the cloud that produces the sound, not the sound itself.","definitionCN":"由 thunder 加 cloud：产生雷声的云，而不是雷声本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rumble","ipa":"/ˈrʌmbl/","tag":"low and continuous","definition":"A continuous low sound such as distant thunder or a heavy cart; it stresses duration.","definitionCN":"如远处雷声或重车般的持续低响；强调持续时间。"},{"word":"roar","ipa":"/rɔː/","tag":"open and violent","definition":"A full, violent sound from an animal, engine or crowd; louder and less rolling than thunder.","definitionCN":"动物、发动机或人群发出的浑厚猛烈之声；比雷声更响、更少滚动感。"},{"word":"boom","ipa":"/buːm/","tag":"single impact","definition":"A single deep hollow sound, as of an explosion; it lacks thunder's long roll.","definitionCN":"如爆炸般的单次低沉空洞巨响；没有雷声那种长长的滚动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real cognates, real idioms and the real physical cause of the sound.","cn":"正常联想：真实的同源词、真实的习语，以及声音真实的物理成因。"},"normal":[{"en":"German Donner and Old Norse Þórr share the base, so the cognates are exact.","cn":"德语 Donner 与古诺斯语 Þórr 共享词干，同源关系明确。"},{"en":"Latin tonare and tonitrus are cousins through the same Indo-European root.","cn":"拉丁 tonare 与 tonitrus 经同一印欧词根与之远亲同源。"},{"en":"Fixed phrases: a clap of thunder, thunder and lightning, distant thunder.","cn":"固定搭配：一声霹雳、雷电交加、远处的雷声。"},{"en":"Steal someone's thunder is the idiom for taking another's credit.","cn":"「抢走别人的风头」是夺取他人功劳的固定说法。"},{"en":"The verb has both a weather use and an angry-speech use.","cn":"这个动词既有天气用法，也有愤怒言语的用法。"}],"abstract":[{"en":"Picture a sound with weight, rolling downhill and flattening everything in its path.","cn":"想象一个有重量的声音滚下山坡，把路上的一切压平。"},{"en":"Picture a mouth so loud that the room behaves like open sky.","cn":"想象一张嘴响到让整间屋子像露天的天空。"},{"en":"Picture a warning heard before the thing it warns about arrives.","cn":"想象一个警告，在被警告的事物到达之前就先被听见。"}]},"examples":[{"en":"Thunder woke the camp an hour before the rain.","cn":"雨来之前一小时，雷声把营地惊醒。"},{"en":"The crowd thundered its approval as the goal went in.","cn":"球进门时，人群爆发出雷鸣般的喝彩。"},{"en":"He thundered that the delay was unacceptable.","cn":"他大声斥责说这种拖延不可接受。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「轰得」——一声轰得山响 → 雷、雷鸣","word":"thunder"},"root":"古英语 thunor，源自原始日耳曼 *thunraz；与德语 Donner、古诺斯语 Þórr 同源，并经印欧 *(s)tenh₂-「回响」与拉丁 tonare、tonitrus 远亲同源。","sensesIntro":{"en":"Eight senses start from the physical sound, pass through the impersonal verb, then use that sound for crowds, anger, moving vehicles, public denunciation, weather warning and finally sheer pressure.","cn":"八个义项从物理声音出发，经无人称动词，再把这种声音用于人群、怒气、行进的车辆、公开谴责、天气征兆，最后用于纯粹的压力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sound heavy enough to travel over a valley and arrive long after its cause.","cn":"核心意象：一个重到能越过山谷、在成因过去很久之后才抵达的声音。"},"chain":["CHARGE HEATS AIR","AIR EXPANDS","SHOCK WAVE","LOW ROLL","ECHO","SILENCE"],"branches":[{"senses":"01 · 02","en":"THE SOUND AND ITS VERB: what is heard and the impersonal event of hearing it.","cn":"声音与其动词：被听见的东西，以及听见它的无人称事件。"},{"senses":"03 · 05","en":"BORROWED VOLUME: hooves and trains are described with weather sound.","cn":"借来的音量：马蹄与列车都用天气的声音来描述。"},{"senses":"04 · 06","en":"VOICE AS THUNDER: anger and public condemnation take on the sky's authority.","cn":"声音如雷：怒气与公开谴责带上了天空的权威。"},{"senses":"07","en":"EARLY WARNING: sound outruns rain, so thunder precedes the storm.","cn":"提前预警：声音跑得比雨快，因此雷先于风暴到达。"},{"senses":"08","en":"PRESSURE: only the sense of irresistible volume remains.","cn":"压力：只剩不可抵挡的声势这一层。"}]},"affixes":{"intro":{"en":"Thunder is a native Germanic noun with an English verb and adjective family, not a Latin construction.","cn":"thunder 是日耳曼语本族名词，其动词与形容词家族属英语构词，而非拉丁结构。"},"latinIntro":{"en":"Latin tonare and tonitrus are cognate cousins quoted for comparison; no Latin affix builds this English word.","cn":"拉丁 tonare 与 tonitrus 是供比较的同源远亲；本英语词不由任何拉丁词缀构成。"},"items":[{"word":"thunder","structure":"thunder (Old English thunor, noun and verb)","meaning":"the sound of a discharge; to make that sound","meaningCN":"放电之声；发出这种声音","example":"The sky thundered for an hour.","exampleCN":"天空打了一个小时的雷。"},{"word":"-ous","structure":"-ous (adjective suffix, 'full of')","meaning":"full of; like","meaningCN":"充满；像……的","example":"The applause was thunderous.","exampleCN":"掌声如雷。"},{"word":"-ly","structure":"-ly (adverb suffix from adjectives)","meaning":"in a thunderous manner","meaningCN":"以雷鸣般的方式","example":"The door closed thunderously.","exampleCN":"门雷鸣般地关上了。"},{"word":"-y","structure":"-y (adjective suffix)","meaning":"having the quality of","meaningCN":"具有……性质","example":"A thundery sky closed the pass.","exampleCN":"有雷的天空封住了山口。"},{"word":"thunder-","structure":"thunder (combining first element)","meaning":"of thunder","meaningCN":"雷的","example":"A thundercloud rose over the ridge.","exampleCN":"雷云在山脊上升起。"},{"word":"-bolt","structure":"-bolt (combining noun, 'arrow, shaft')","meaning":"a stroke imagined as a missile","meaningCN":"被想象成投掷物的雷击","example":"A thunderbolt split the elm.","exampleCN":"一道霹雳劈开了榆树。"},{"word":"-cloud","structure":"-cloud (combining noun)","meaning":"the cloud that carries thunder","meaningCN":"承载雷声的云","example":"The thundercloud blocked the sun.","exampleCN":"雷云遮住了太阳。"},{"word":"-struck","structure":"-struck (combining adjective, 'hit by')","meaning":"hit by thunder or lightning","meaningCN":"被雷击中的","example":"The thunderstruck oak lost its crown.","exampleCN":"被雷击中的橡树失去了树冠。"},{"word":"-head","structure":"-head (combining noun, 'top')","meaning":"the towering top of a storm cloud","meaningCN":"风暴云高耸的顶部","example":"The thunderhead spread into an anvil.","exampleCN":"雷暴云顶铺展成砧状。"}],"latinEntries":[{"word":"tonare","structure":"tonare, tonui (verb, first conjugation)","meaning":"to thunder","meaningCN":"打雷；发出雷鸣"},{"word":"tonitrus","structure":"tonitrus, tonitrus (m., fourth declension)","meaning":"thunder","meaningCN":"雷；雷声"},{"word":"tonitrualis","structure":"tonitrualis, -e (adjective, third declension)","meaning":"of thunder, thundering","meaningCN":"雷的；雷鸣般的"}]}},{"word":"flood","ipa_uk":"/flʌd/","ipa_us":"/flʌd/","definition_zh":"洪水；泛滥；大量涌入；被……淹没；涨潮；灌满","definition_en":"a large overflow of water onto land that is normally dry, or a very large number of things arriving at once","core_image":"河水翻过堤岸，浑黄的水面漫过田埂，把道路、树根与院墙一并吞掉","scene":"连日的雨把河水推上堤岸，村口的道路消失在浑黄的水面下。The flood cut the village off for three days.","sceneCN":"这里指「漫过陆地的洪水」（第 1 个义项：水体超出正常范围淹没干燥土地）；句意为洪水把村子与外界隔绝了三天。图中可辨识物件：翻过堤岸的水、被淹的道路、露出水面的树梢、关闭的桥。","pos":[{"tag":"n.","zh":"洪水；泛滥；大量；涨潮"},{"tag":"v.","zh":"淹没；泛滥；大量涌入；灌满"}],"collocations":[{"phrase":"flash flood","zh":"山洪；暴洪"},{"phrase":"flood warning","zh":"洪水警报"},{"phrase":"a flood of applications","zh":"大量申请"},{"phrase":"be flooded with","zh":"被……淹没；充斥着"},{"phrase":"flood plain","zh":"洪泛平原"},{"phrase":"flood tide","zh":"涨潮"}],"forms":[{"label":"复数","form":"floods"},{"label":"三单（第三人称单数）","form":"floods"},{"label":"过去式","form":"flooded"},{"label":"过去分词","form":"flooded"},{"label":"现在分词","form":"flooding"},{"label":"名词（洪涝）","form":"flooding"}],"derivatives":[{"word":"flooding","pos":"n.","zh":"洪涝；淹没"},{"word":"floodplain","pos":"n.","zh":"洪泛平原"},{"word":"floodgate","pos":"n.","zh":"防洪闸门"},{"word":"floodlight","pos":"n.","zh":"泛光灯"},{"word":"floodwater","pos":"n.","zh":"洪水"}],"senses":[{"no":"01","title":"An overflow of water onto dry land","titleCN":"漫过干燥陆地的洪水","definition":"a large body of water that rises and covers land that is normally dry","definitionCN":"水位上涨并覆盖通常干燥土地的大片水体","example":"The flood cut the village off for three days.","exampleCN":"洪水把村子与外界隔绝了三天。","why":"The noun names the state in which water occupies land it does not usually occupy.","whyCN":"这个名词命名的是水占据了平日不占之地的状态。"},{"no":"02","title":"To cover land with water","titleCN":"河水漫过并淹没陆地","definition":"to rise and spread over land, as a river does when it breaks its banks","definitionCN":"水位上涨并铺展到陆地上，如河流破堤时那样","example":"The river flooded the lower fields in a single night.","exampleCN":"河水一夜之间淹没了低处的田地。","why":"The verb turns the state into an event with a cause and a direction.","whyCN":"动词把状态变成有起因、有方向的事件。"},{"no":"03","title":"A very large number arriving at once","titleCN":"大量事物同时涌来","definition":"an overwhelming quantity of people, messages or requests arriving together","definitionCN":"人、信息或请求同时到来的压倒性数量","example":"A flood of applications arrived after the posting.","exampleCN":"岗位公布之后，大量申请涌了进来。","why":"Quantity is imagined as water: it rises, spreads and cannot be stopped by hand.","whyCN":"数量被想象成水：上涨、铺开，用手拦不住。"},{"no":"04","title":"To overwhelm with a large quantity","titleCN":"被大量事物淹没","definition":"to receive so many things that one cannot deal with them, usually in the passive","definitionCN":"收到过多事物以致无法应付，通常用被动式","example":"The office was flooded with complaints after the outage.","exampleCN":"停电之后，办公室被投诉淹没了。","why":"The passive keeps the water image: the receiver is under the surface.","whyCN":"被动式保留水的意象：接收者被压在水面之下。"},{"no":"05","title":"The rising tide","titleCN":"涨潮","definition":"the incoming tide, or the period when the sea rises, as in ebb and flood","definitionCN":"上涨的潮水，或海水升高的时段，如落潮与涨潮","example":"Fishermen set out on the flood and returned on the ebb.","exampleCN":"渔民趁涨潮出海，落潮时返回。","why":"Tides were the first everyday experience of water rising on a schedule, so the word named them too.","whyCN":"潮汐是人们最早熟悉的有规律上涨的水，因此这个词也被用来指潮。"},{"no":"06","title":"To fill an enclosed space with liquid","titleCN":"把封闭空间灌满液体","definition":"to fill a space or a machine with liquid, sometimes excessively","definitionCN":"用液体灌满空间或机器，有时是过量地灌","example":"Water flooded the engine through the air intake.","exampleCN":"水从进气口灌进了发动机。","why":"The core image narrows to a container: the liquid behaves like a flood inside it.","whyCN":"核心意象收窄到容器：液体在容器里像洪水一样。"},{"no":"07","title":"To fill with light or colour","titleCN":"光线或色彩充满空间","definition":"to fill a place with light or colour so that everything in it is changed","definitionCN":"让光或色彩充满某处，使其中一切都被改变","example":"Sunlight flooded the hall when the doors opened.","exampleCN":"门一开，阳光涌满了大厅。","why":"Light spreads like water and fills every corner, so the same verb serves both.","whyCN":"光像水一样铺开并填满每个角落，因此同一个动词两处都适用。"},{"no":"08","title":"To be overwhelmed by feeling","titleCN":"被情感淹没","definition":"to be overcome by a strong emotion that seems to rise and cover one","definitionCN":"被一种似乎上涨并覆盖自身的强烈情感压倒","example":"She was flooded with relief when the call finally came.","exampleCN":"电话终于打来时，她松了一口气，如释重负。","why":"The last sense keeps only the movement: something rises inside a person and there is no room left.","whyCN":"最后一个义项只保留运动本身：某物在人心里上涨，再没有余下空间。"}],"etymology":{"intro":{"en":"Flood is Old English flōd, from Proto-Germanic *flōduz, and belongs to the Indo-European stock of *pleu- 'to flow, to float', which also gave Latin pluere 'to rain' and pluvia 'rain'.","cn":"flood 是古英语 flōd，源自原始日耳曼 *flōduz，属印欧 *pleu-「流动、漂浮」词干，这一词干也产生了拉丁 pluere「下雨」与 pluvia「雨」。"},"items":[{"era":"OLD ENGLISH FLOD","en":"Old English flōd named the rising water and, by extension, the sea tide; the verb flōdian followed.","cn":"古英语 flōd 指上涨的水，引申也指海潮；动词 flōdian 随后出现。"},{"era":"PROTO-GERMANIC *FLODUZ","en":"German Flut and Dutch vloed descend from the same base, all naming a rising body of water.","cn":"德语 Flut 与荷兰语 vloed 出自同一词干，都指上涨的水体。"},{"era":"PIE *PLEU- 'TO FLOW'","en":"The Indo-European root *pleu- 'to flow, to float' is reconstructed from several branches and is widely accepted, though its exact shape remains a reconstruction.","cn":"印欧词根 *pleu-「流动、漂浮」由多个语支重构而来，学界广泛接受，但其确切形态仍属重构。"},{"era":"LATIN COGNATES","en":"Latin pluere 'to rain' and pluvia 'rain' come from the same root; they are cousins, not ancestors, of the English word.","cn":"拉丁 pluere「下雨」与 pluvia「雨」出自同一词根；它们是英语词的远亲，而非祖先。"},{"era":"FIGURATIVE SENSE","en":"The sense of a flood of words or people is recorded from the sixteenth century, when water imagery was applied to quantity.","cn":"言语或人群的「洪流」义自 16 世纪有记录，当时水的意象被用于数量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin only): the pre-Germanic formation of *flōduz is not attested, and the connection with the tide sense rests on usage rather than on a recorded semantic chain.","cn":"来源不确定（仅更深词源）：*flōduz 在日耳曼语之前的构造没有书证，与潮汐义的联系依据用法而非有记录的语义链。"}]},"similar":{"note":{"en":"Group one holds words built on flood itself and easily confused with it; group two holds near synonyms for a great quantity of water.","cn":"第一组是由本词构成、易与之混淆的词；第二组是表示大量水的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"flooding","ipa":"/ˈflʌdɪŋ/","tag":"same root, gerund","definition":"Flood plus -ing: the process or event of being flooded, not a single body of water.","definitionCN":"由 flood 加 -ing：被淹的过程或事件，而不是一片水体。"},{"word":"floodplain","ipa":"/ˈflʌdpleɪn/","tag":"compound noun","definition":"Flood plus plain: the flat land beside a river that floods by design, not the water itself.","definitionCN":"由 flood 加 plain：河边按规律会被淹的平地，而不是水本身。"},{"word":"floodgate","ipa":"/ˈflʌdɡeɪt/","tag":"compound noun","definition":"Flood plus gate: a gate that controls water, and figuratively a release of restrained feeling.","definitionCN":"由 flood 加 gate：控制水流的闸门，比喻被压抑情绪的释放。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inundation","ipa":"/ˌɪnʌnˈdeɪʃn/","tag":"formal","definition":"A formal noun for covering land with water; it stresses the state of being overrun.","definitionCN":"正式用语，指水覆盖土地；强调被水侵占的状态。"},{"word":"deluge","ipa":"/dɪˈluːdʒ/","tag":"violent and sudden","definition":"A violent, sudden flood or downpour, often used figuratively for an overwhelming rush.","definitionCN":"猛烈突然的洪水或暴雨，常比喻压倒性的涌来。"},{"word":"torrent","ipa":"/ˈtɒrənt/","tag":"fast-flowing","definition":"A fast, violent stream of water; it stresses speed and force rather than spread.","definitionCN":"快速猛烈的水流；强调速度与冲力，而非漫延范围。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Germanic cognates, the real root and the real compounds.","cn":"正常联想：真实的日耳曼同源词、真实词根与真实复合词。"},"normal":[{"en":"German Flut and Dutch vloed are exact cognates.","cn":"德语 Flut 与荷兰语 vloed 是同源词。"},{"en":"Latin pluere 'to rain' comes from the same Indo-European root, as a cousin.","cn":"拉丁 pluere「下雨」出自同一印欧词根，是远亲。"},{"en":"Fixed phrases: flash flood, flood warning, flood tide.","cn":"固定搭配：暴洪、洪水警报、涨潮。"},{"en":"The passive pattern be flooded with carries the figurative senses.","cn":"被动结构「被……淹没」承载比喻义。"},{"en":"Compounds mark the technical senses: floodplain, floodgate, floodlight.","cn":"复合词标出技术义：洪泛平原、防洪闸、泛光灯。"}],"abstract":[{"en":"Picture a letterbox that fills faster than anyone can empty it.","cn":"想象一个信件比任何人清空得都快的信箱。"},{"en":"Picture light pouring through a door like water through a breach.","cn":"想象光从门口涌进来，像水从缺口涌进来。"},{"en":"Picture a feeling rising until the person has no room left for anything else.","cn":"想象一种情绪上涨，直到人心里再装不下别的。"}]},"examples":[{"en":"The flood destroyed the bridge but spared the church.","cn":"洪水毁掉了桥，却保住了教堂。"},{"en":"After the broadcast, the station was flooded with calls.","cn":"节目播出后，电台被电话淹没了。"},{"en":"The goalkeeper was flooded with relief when the whistle blew.","cn":"哨声响起时，守门员如释重负。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「扶路得」——水漫过来，扶着路才走得出去 → 洪水","word":"flood"},"root":"古英语 flōd「上涨的水」，源自原始日耳曼 *flōduz；与德语 Flut、荷兰语 vloed 同源，并经印欧 *pleu-「流动」与拉丁 pluere「下雨」、pluvia「雨」远亲同源。","sensesIntro":{"en":"Eight senses all describe something rising beyond its bounds: water over land, tide over the shore, messages over an office, light over a room and feeling over a person.","cn":"八个义项都在描述某物涨出边界：水漫过土地、潮漫过海岸、信息漫过办公室、光漫过房间、情绪漫过人。"},"semanticMap":{"core":{"en":"CORE IMAGE: water that refuses the channel it was given and takes the land instead.","cn":"核心意象：水不肯待在给它的河道里，转而占去陆地。"},"chain":["WATER RISES","BANK BREAKS","LAND COVERED","QUANTITY POURS","SPACE FILLED","FEELING OVERFLOWS"],"branches":[{"senses":"01 · 02","en":"STATE AND EVENT: the body of water and the act of covering land are one phenomenon.","cn":"状态与事件：那片水体与淹没土地的动作是同一现象。"},{"senses":"03 · 04","en":"QUANTITY AS WATER: arrivals rise until the receiver is submerged.","cn":"以水喻量：涌来的事物上涨，直到接收者被淹没。"},{"senses":"05","en":"TIDE: the first scheduled rising water gave the word its sea sense.","cn":"潮汐：最早有规律的涨水给了这个词海洋义。"},{"senses":"06 · 07","en":"CONTAINER AND LIGHT: liquid and light both fill whatever space is open.","cn":"容器与光：液体与光都会填满敞开的空间。"},{"senses":"08","en":"INNER WEATHER: the flood is now inside a person, with no room left.","cn":"内心天气：洪水进入人的内部，再没有余下空间。"}]},"affixes":{"intro":{"en":"Flood is a native Germanic word whose family is built with English suffixes and compounds.","cn":"flood 是日耳曼语本族词，其词族由英语后缀与复合成分构成。"},"latinIntro":{"en":"Latin pluere and pluvia are cognates at the Indo-European level and are quoted for comparison, not as building blocks.","cn":"拉丁 pluere 与 pluvia 在印欧语层面同源，此处仅作比较，并非构词成分。"},"items":[{"word":"flood","structure":"flood (Old English flōd, noun and verb)","meaning":"rising water; to cover with water","meaningCN":"上涨的水；用水覆盖","example":"The river flooded the road.","exampleCN":"河水淹没了道路。"},{"word":"-ing","structure":"-ing (noun suffix from verbs)","meaning":"the process or event of","meaningCN":"……的过程或事件","example":"Flooding closed the subway.","exampleCN":"积水使地铁停运。"},{"word":"-plain","structure":"-plain (combining noun, 'flat land')","meaning":"flat land shaped by a river","meaningCN":"由河流塑造的平地","example":"Farmers work the floodplain each spring.","exampleCN":"农民每年春天在洪泛平原上耕作。"},{"word":"-gate","structure":"-gate (combining noun, 'barrier that opens')","meaning":"a gate controlling water","meaningCN":"控制水流的闸门","example":"The floodgate held through the night.","exampleCN":"闸门整夜守住了。"},{"word":"flood-","structure":"flood (combining first element)","meaning":"of a flood; very broad","meaningCN":"洪水的；范围很广的","example":"A floodlight lit the yard.","exampleCN":"一盏泛光灯照亮了院子。"},{"word":"-water","structure":"-water (combining noun)","meaning":"water from a flood","meaningCN":"洪水带来的水","example":"Floodwater filled the cellar.","exampleCN":"洪水灌满了地窖。"},{"word":"-light","structure":"-light (combining noun, 'lamp')","meaning":"a broad beam that floods an area","meaningCN":"照亮整片区域的宽光束","example":"The stadium floodlights came on.","exampleCN":"体育场的泛光灯亮了。"},{"word":"flash flood","structure":"flash + flood (compound noun)","meaning":"a flood that arrives with little warning","meaningCN":"几乎没有预警就到达的暴洪","example":"A flash flood swept the canyon road.","exampleCN":"暴洪冲过峡谷公路。"},{"word":"-prone","structure":"-prone (combining adjective, 'liable to')","meaning":"likely to suffer a flood","meaningCN":"容易遭受洪水的","example":"The delta is flood-prone.","exampleCN":"这片三角洲易遭洪水。"}],"latinEntries":[{"word":"pluere","structure":"pluere, plui (verb, third conjugation)","meaning":"to rain","meaningCN":"下雨"},{"word":"pluvia","structure":"pluvia, -ae (f., first declension)","meaning":"rain","meaningCN":"雨"},{"word":"pluvialis","structure":"pluvialis, -e (adjective, third declension)","meaning":"of rain, rainy","meaningCN":"雨的；多雨的"}]}},{"word":"flooding","ipa_uk":"/ˈflʌdɪŋ/","ipa_us":"/ˈflʌdɪŋ/","definition_zh":"洪涝；淹没过程；城市内涝；大量涌入；满溢；进水","definition_en":"the process or event of water covering land, or of an overwhelming quantity of things filling a place","core_image":"雨水在城市街道上积成一片浅海，井盖下翻涌，车灯在水面拉出长条倒影","scene":"连日暴雨让低洼的街区积水不退，校车无法通行。Persistent flooding forced the school to close for a week.","sceneCN":"这里指「持续积水造成的洪涝现象」（第 1 个义项：地表被水覆盖的灾害过程）；句意为持续的洪涝迫使学校停课一周。图中可辨识物件：漫过路缘的积水、半没的车轮、翻涌的井口、关闭的校门。","pos":[{"tag":"n.","zh":"洪涝；淹没；大量涌入；满溢"}],"collocations":[{"phrase":"flash flooding","zh":"突发性洪涝"},{"phrase":"coastal flooding","zh":"沿海洪涝"},{"phrase":"urban flooding","zh":"城市内涝"},{"phrase":"flooding of the market","zh":"市场被大量商品涌入"},{"phrase":"flooding risk","zh":"洪涝风险"},{"phrase":"severe flooding","zh":"严重洪涝"}],"forms":[{"label":"复数（技术用法）","form":"floodings"},{"label":"原形动词","form":"flood"},{"label":"三单（第三人称单数）","form":"floods"},{"label":"过去式","form":"flooded"},{"label":"过去分词","form":"flooded"},{"label":"现在分词","form":"flooding"}],"derivatives":[{"word":"floodplain","pos":"n.","zh":"洪泛平原"},{"word":"floodgate","pos":"n.","zh":"防洪闸门"},{"word":"floodlight","pos":"n.","zh":"泛光灯"},{"word":"floodwater","pos":"n.","zh":"洪水"},{"word":"flood-prone","pos":"adj.","zh":"易涝的"}],"senses":[{"no":"01","title":"The event of water covering land","titleCN":"地表被水覆盖的洪涝事件","definition":"the event or process in which water covers land that is normally dry","definitionCN":"水覆盖通常干燥土地的事件或过程","example":"Persistent flooding forced the school to close for a week.","exampleCN":"持续的洪涝迫使学校停课一周。","why":"The -ing form names the going-on of the event, so it suits reports, warnings and insurance.","whyCN":"这一动名词形式命名事件的持续过程，因此适用于报告、警报与保险。"},{"no":"02","title":"A river overflowing its channel","titleCN":"河道漫溢","definition":"the process by which a river or stream rises above its banks and spreads over the floodplain","definitionCN":"河流或溪流涨过河岸、铺展到洪泛平原的过程","example":"River flooding began upstream and reached the town by nightfall.","exampleCN":"河流漫溢从上游开始，到傍晚抵达城镇。","why":"Hydrology needs a name for the process rather than for a single flood.","whyCN":"水文学需要一个指过程而非单次洪水的名称。"},{"no":"03","title":"Urban flooding after heavy rain","titleCN":"暴雨后的城市内涝","definition":"the accumulation of rainwater in streets and underpasses when drainage cannot keep up","definitionCN":"排水跟不上时，雨水在街道与地下通道积聚的现象","example":"Urban flooding stranded buses under the flyover.","exampleCN":"城市内涝把公交车困在高架桥下。","why":"The word shifts from rivers to pavement: the cause is not a bank burst but a drain that is too small.","whyCN":"这个词从河流转到路面：成因不是堤岸决口，而是排水口太小。"},{"no":"04","title":"An overwhelming inflow of goods or messages","titleCN":"商品或信息的大量涌入","definition":"the arrival of so many goods, applications or messages that a system cannot absorb them","definitionCN":"商品、申请或信息到来过多，使系统无法吸收","example":"The flooding of the market with cheap imports hurt local mills.","exampleCN":"廉价进口商品大量涌入市场，打击了本地工厂。","why":"The water image survives in the metaphor: the system is a channel that has been overtopped.","whyCN":"水的意象在比喻中保留：系统成了一条被漫过的渠道。"},{"no":"05","title":"Filling a place with light","titleCN":"光线充满某处","definition":"the effect of light spreading through and filling a space","definitionCN":"光在空间中铺开并充满的效果","example":"The flooding of the stage with white light erased every shadow.","exampleCN":"白光涌满舞台，把所有阴影都抹掉了。","why":"Light and water share the behaviour of spreading until a boundary stops them.","whyCN":"光与水共享同一种行为：不断铺开，直到边界拦住。"},{"no":"06","title":"An engine or carburettor taking in too much fuel","titleCN":"发动机或化油器进液过多","definition":"the condition in which excess fuel or water enters an engine and prevents it from starting","definitionCN":"过多燃料或水进入发动机、使其无法启动的状态","example":"Repeated short trips caused flooding in the carburettor.","exampleCN":"反复短途行驶导致化油器进液过多。","why":"The technical sense treats the engine as a chamber that has been overfilled.","whyCN":"这一技术义把发动机视为被灌得过满的腔室。"},{"no":"07","title":"Being overwhelmed by emotion","titleCN":"被情绪淹没","definition":"a state in which strong feeling rises and leaves no room for thought","definitionCN":"强烈情绪上涨、使思考再无空间的状态","example":"The flooding of grief came later, when the house was quiet.","exampleCN":"悲伤的淹没来得更晚，在屋子安静下来之后。","why":"The abstract sense keeps the rise and the loss of room, with no water at all.","whyCN":"抽象义只保留「上涨」与「没有余地」，完全不涉及水。"},{"no":"08","title":"Information overload","titleCN":"信息过载","definition":"the condition of receiving far more information than one can process, as in a flooded feed","definitionCN":"收到远超处理能力的信息的状态，如被灌满的信息流","example":"Constant flooding of the feed made the important notice invisible.","exampleCN":"信息流不断被灌满，使那条重要通知变得看不见。","why":"Digital life reused the old image: a channel that carries too much ceases to carry anything.","whyCN":"数字生活沿用旧意象：承载过多的渠道反而什么都传送不了。"}],"etymology":{"intro":{"en":"Flooding is flood plus the noun suffix -ing. The base is Old English flōd from Proto-Germanic *flōduz, and the suffix is the native English -ing that turns verbs into names for processes.","cn":"flooding 由 flood 加名词后缀 -ing 构成。词基是古英语 flōd，源自原始日耳曼 *flōduz；后缀是英语本族的 -ing，把动词转为过程名称。"},"items":[{"era":"OLD ENGLISH FLOD","en":"The base flōd named rising water, and the derived verb flōdian already allowed a process noun in principle.","cn":"词基 flōd 指上涨的水，其派生动词 flōdian 原则上已可构成过程名词。"},{"era":"MIDDLE ENGLISH -ING","en":"The native -ing suffix was fully productive in Middle English, forming nouns for ongoing actions and events.","cn":"本族 -ing 后缀在中古英语中已高度能产，可构成表示持续动作与事件的名词。"},{"era":"HYDROLOGY","en":"Modern hydrology and insurance gave flooding a technical standing as a measurable hazard rather than a single event.","cn":"现代水文学与保险业使 flooding 获得技术地位，成为可度量的灾害而非单次事件。"},{"era":"URBAN AND COASTAL COMPOUNDS","en":"Twentieth-century planning produced fixed terms such as urban flooding, coastal flooding and flooding risk.","cn":"20 世纪的规划实践产生了城市内涝、沿海洪涝、洪涝风险等固定术语。"},{"era":"DIGITAL EXTENSION","en":"From the late twentieth century the word was extended to overloaded information channels, keeping the water image.","cn":"20 世纪后期，该词被扩展到过载的信息渠道，水的意象得以保留。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the exact first written use of the -ing noun is not pinned down, though its formation is transparent and not in doubt.","cn":"来源不确定（仅首见年代）：该 -ing 名词最早的书证难以确定，但其构成方式透明，并无疑义。"}]},"similar":{"note":{"en":"Group one holds forms of the same verb that differ in grammatical role; group two holds nouns for water disasters and for overwhelming inflows.","cn":"第一组是同一动词的不同语法形式；第二组是水灾与压倒性涌入的近义名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"flood","ipa":"/flʌd/","tag":"base noun or verb","definition":"The base form: one body of water, or the act of covering land; it can be counted.","definitionCN":"原形：一片水体，或淹没土地的动作；可以计数。"},{"word":"flooded","ipa":"/ˈflʌdɪd/","tag":"past participle","definition":"The completed state, as in a flooded road; it describes the result rather than the process.","definitionCN":"完成状态，如被淹的道路；描述结果而非过程。"},{"word":"floodplain","ipa":"/ˈflʌdpleɪn/","tag":"compound noun","definition":"The flat land that flooding is expected to cover; the word names terrain, not the event.","definitionCN":"预期会被洪涝覆盖的平地；该词指地形，而非事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inundation","ipa":"/ˌɪnʌnˈdeɪʃn/","tag":"formal synonym","definition":"A formal noun for the state of being covered by water; it is countable and often literary.","definitionCN":"表示被水覆盖状态的正式名词；可计数，常带文学色彩。"},{"word":"waterlogging","ipa":"/ˈwɔːtəlɒɡɪŋ/","tag":"soil saturation","definition":"Saturation of soil so that water cannot drain away; narrower than flooding, and usually about ground, not streets.","definitionCN":"土壤饱和以致水无法排出；比 flooding 窄，通常指地面而非街道。"},{"word":"overflow","ipa":"/ˌəʊvəˈfləʊ/","tag":"beyond capacity","definition":"The spilling of water or anything else past a container's limit; it stresses the moment of exceeding capacity.","definitionCN":"水或任何事物超出容器限度而溢出；强调超出容量的那一刻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real base word, the real suffix and the real technical compounds.","cn":"正常联想：真实的词基、真实的后缀与真实的技术复合词。"},"normal":[{"en":"Flood plus -ing: the base names the water, the suffix names the process.","cn":"flood 加 -ing：词基指水，后缀指过程。"},{"en":"Hydrology prefers the -ing form because hazards are processes, not objects.","cn":"水文学偏爱 -ing 形式，因为灾害是过程而不是物体。"},{"en":"Fixed terms: urban flooding, coastal flooding, flash flooding.","cn":"固定术语：城市内涝、沿海洪涝、突发性洪涝。"},{"en":"The metaphorical use survives in flooding the market and flooding the feed.","cn":"比喻用法保留在「商品涌满市场」与「信息流被灌满」中。"},{"en":"The engine sense treats a chamber as overfilled.","cn":"发动机义把腔室视为被灌得过满。"}],"abstract":[{"en":"Picture a drain that is asked to carry a river.","cn":"想象一个被要求排走一条河的排水口。"},{"en":"Picture a screen where the important line is buried under a thousand others.","cn":"想象一块屏幕，重要的一行被上千行别的埋住。"},{"en":"Picture quiet returning to a house and grief arriving with it.","cn":"想象屋子重新安静下来，悲伤随之到来。"}]},"examples":[{"en":"Flooding closed the coastal road for two tides.","cn":"洪涝使沿海公路连续两个潮汐无法通行。"},{"en":"Engineers map flooding risk before approving new housing.","cn":"工程师在批准新建住宅前先绘制洪涝风险图。"},{"en":"The flooding of the archive with unsorted files slowed every search.","cn":"未整理文件大量涌入档案库，使每次检索都变慢。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「flood（洪水）+ ing（进行）」——洪水正在进行 → 洪涝、淹没","word":"flooding"},"root":"由 flood（古英语 flōd，原始日耳曼 *flōduz）+ 本族后缀 -ing 构成；词基与德语 Flut、荷兰语 vloed 同源，并经印欧 *pleu-「流动」与拉丁 pluere「下雨」远亲同源。","sensesIntro":{"en":"Eight senses all name a process of exceeding a limit: water over land, drains over capacity, goods over a market, light over a stage, fuel over an engine and information over attention.","cn":"八个义项都命名「超出限度」的过程：水漫过土地、排水超过容量、商品涌过市场、光铺满舞台、燃料灌满发动机、信息超过注意力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surface that keeps rising until the container it was meant to stay in is irrelevant.","cn":"核心意象：不断上涨的水面，直到原本该容纳它的容器形同虚设。"},"chain":["RAIN FALLS","DRAINS FAIL","WATER SPREADS","SYSTEM OVERTOPPED","SPACE FILLED","ABSORPTION STOPS"],"branches":[{"senses":"01 · 02","en":"THE PROCESS: a single event and a river's seasonal behaviour are the same noun at two scales.","cn":"过程：单次事件与河流的季节性行为，是同一名词的两种尺度。"},{"senses":"03","en":"PAVEMENT: when the drain is too small, streets behave like river banks.","cn":"路面：当排水口太小，街道就像河岸。"},{"senses":"04","en":"INFLOW: goods and messages become water that overfills a channel.","cn":"涌入：商品与信息变成灌满渠道的水。"},{"senses":"05 · 06","en":"FILLING: light and fuel both occupy a chamber until it is full.","cn":"充满：光与燃料都占满腔室，直到再装不下。"},{"senses":"07 · 08","en":"NO ROOM LEFT: grief and information both leave nothing for anything else.","cn":"再无余地：悲伤与信息都不给别的事物留位置。"}]},"affixes":{"intro":{"en":"Flooding is a transparent English derivative of flood, so its morphology is suffixal and Germanic.","cn":"flooding 是 flood 的透明英语派生词，其形态构成为日耳曼语后缀法。"},"latinIntro":{"en":"The Latin rain words quoted here are cognates of the base at the Indo-European level, not sources of the suffix.","cn":"此处引用的拉丁「雨」词在印欧语层面与词基同源，并非该后缀的来源。"},"items":[{"word":"flood","structure":"flood (Old English flōd, verb and noun)","meaning":"to cover land with water","meaningCN":"用水覆盖土地","example":"The river floods every spring.","exampleCN":"这条河每年春天泛滥。"},{"word":"-ing","structure":"-ing (native noun suffix from verbs)","meaning":"the process or event of","meaningCN":"……的过程或事件","example":"The flooding lasted four days.","exampleCN":"洪涝持续了四天。"},{"word":"urban flooding","structure":"urban + flooding (technical compound)","meaning":"rainwater pooling in a city","meaningCN":"雨水在城市中积存","example":"Urban flooding closed three underpasses.","exampleCN":"城市内涝关闭了三个地下通道。"},{"word":"coastal flooding","structure":"coastal + flooding (technical compound)","meaning":"sea water covering coastal land","meaningCN":"海水覆盖沿海土地","example":"Coastal flooding followed the spring tide.","exampleCN":"大潮之后出现了沿海洪涝。"},{"word":"flash flooding","structure":"flash + flooding (technical compound)","meaning":"sudden local flooding after intense rain","meaningCN":"强降雨后突发的局地洪涝","example":"Flash flooding caught drivers in the canyon.","exampleCN":"突发性洪涝把司机困在峡谷里。"},{"word":"flood-","structure":"flood (combining first element)","meaning":"of a flood","meaningCN":"洪水的","example":"Floodwater reached the first floor.","exampleCN":"洪水涨到了一楼。"},{"word":"-plain","structure":"-plain (combining noun, 'flat land')","meaning":"land built by river deposits","meaningCN":"由河流沉积形成的平地","example":"The floodplain absorbs the surplus water.","exampleCN":"洪泛平原吸收多余的水。"},{"word":"-gate","structure":"-gate (combining noun, 'barrier')","meaning":"a barrier that controls water","meaningCN":"控制水流的屏障","example":"The floodgate was raised at noon.","exampleCN":"闸门在正午升起。"},{"word":"-light","structure":"-light (combining noun, 'lamp')","meaning":"a wide beam that fills an area","meaningCN":"照亮整片区域的宽光束","example":"Floodlights turned the pitch white.","exampleCN":"泛光灯把球场照成白色。"}],"latinEntries":[{"word":"pluere","structure":"pluere, plui (verb, third conjugation)","meaning":"to rain","meaningCN":"下雨"},{"word":"pluvia","structure":"pluvia, -ae (f., first declension)","meaning":"rain","meaningCN":"雨"},{"word":"inundatio","structure":"inundatio, inundationis (f., third declension)","meaning":"a flooding, an overflow","meaningCN":"泛滥；淹没"}]}},{"word":"monsoon","ipa_uk":"/mɒnˈsuːn/","ipa_us":"/mɑːnˈsuːn/","definition_zh":"季风；季风季节；季风降雨；雨季","definition_en":"a seasonal wind that reverses direction between summer and winter, or the rainy season that such a wind brings","core_image":"海上的风整季转向，湿气像一堵移动的墙推向陆地，山坡上雨幕倾泻","scene":"六月的风一转向，海上的水汽便整片压向内陆。The monsoon arrives in June and rewrites the river's course.","sceneCN":"这里指「随季节反转、带来雨季的区域性风系」（第 1 个义项：夏季由海向陆的盛行风）；句意为季风在六月到来，并改写了河道。图中可辨识物件：转向的风向标、压向陆地的湿气、山坡上的雨幕、改道的河水。","pos":[{"tag":"n.","zh":"季风；季风季节；雨季"},{"tag":"adj.","zh":"季风的（多作定语，如季风降雨）"}],"collocations":[{"phrase":"the summer monsoon","zh":"夏季风"},{"phrase":"the winter monsoon","zh":"冬季风"},{"phrase":"monsoon rains","zh":"季风雨"},{"phrase":"monsoon season","zh":"季风季节"},{"phrase":"monsoon trough","zh":"季风槽"},{"phrase":"monsoon climate","zh":"季风气候"}],"forms":[{"label":"复数","form":"monsoons"},{"label":"形容词（季风的）","form":"monsoonal"},{"label":"季风季节（复合名词）","form":"monsoon season"},{"label":"季风雨（复合名词）","form":"monsoon rain"},{"label":"季风槽（气象术语）","form":"monsoon trough"}],"derivatives":[{"word":"monsoonal","pos":"adj.","zh":"季风的；季风性的"},{"word":"monsoon season","pos":"n.","zh":"季风季节；雨季"},{"word":"monsoon trough","pos":"n.","zh":"季风槽"},{"word":"monsoon forest","pos":"n.","zh":"季风林"},{"word":"monsoon rainfall","pos":"n.","zh":"季风降水"}],"senses":[{"no":"01","title":"A seasonal wind that reverses direction","titleCN":"随季节反向的盛行风","definition":"a large-scale wind that blows from sea to land in summer and reverses in winter","definitionCN":"夏季由海吹向陆地、冬季反向的大尺度风系","example":"The monsoon arrives in June and rewrites the river's course.","exampleCN":"季风在六月到来，并改写了河道。","why":"The word names the reversal itself: the same region receives opposite winds in two halves of the year.","whyCN":"这个词命名的正是反向：同一地区在一年两半里收到方向相反的风。"},{"no":"02","title":"The rainy season brought by that wind","titleCN":"季风带来的雨季","definition":"the rainy season associated with the summer monsoon, especially in South and Southeast Asia","definitionCN":"与夏季风相关、尤见于南亚与东南亚的雨季","example":"The whole town prepares for the monsoon in May.","exampleCN":"整个城镇在五月为雨季做准备。","why":"Rain follows the wind so reliably that the season took the wind's name.","whyCN":"降雨跟随风来得如此可靠，以致季节直接取了风的名称。"},{"no":"03","title":"The moist summer monsoon","titleCN":"湿润的夏季风","definition":"the summer half of the system, which carries moist maritime air onshore and releases heavy rain","definitionCN":"该风系的夏季一半，把湿润的海洋空气送上陆地并释放强降雨","example":"The summer monsoon lifted the moist air over the Western Ghats.","exampleCN":"夏季风把湿空气抬升到西高止山上空。","why":"Land heats faster than sea, so pressure falls inland and the ocean air is drawn in.","whyCN":"陆地比海洋升温快，内陆气压降低，海洋空气便被吸进来。"},{"no":"04","title":"The dry winter monsoon","titleCN":"干燥的冬季风","definition":"the winter half of the system, which blows dry cool air from the interior toward the sea","definitionCN":"该风系的冬季一半，把干冷的内陆空气吹向海洋","example":"The winter monsoon brings clear skies but no rain.","exampleCN":"冬季风带来晴空，却不带来雨。","why":"In winter the pressure pattern flips, so the same word names the opposite airflow.","whyCN":"冬季气压格局翻转，因此同一个词命名了相反的气流。"},{"no":"05","title":"Monsoon rainfall","titleCN":"季风降雨","definition":"the heavy seasonal precipitation produced when moist monsoon air is forced to rise","definitionCN":"湿润季风空气被迫抬升时产生的强季节性降水","example":"Monsoon rainfall fills the reservoirs that supply the plain.","exampleCN":"季风降雨灌满了供给平原的水库。","why":"The rain is not a separate phenomenon but the visible result of the wind's forced ascent.","whyCN":"这种雨并非另一现象，而是风被迫抬升后可见的结果。"},{"no":"06","title":"The monsoon trough","titleCN":"季风槽","definition":"a low-pressure trough where the monsoon flow converges, often spawning depressions","definitionCN":"季风气流汇合处的低压槽，常孕育低压系统","example":"The monsoon trough shifted north and the depressions followed.","exampleCN":"季风槽北移，低压系统随之而来。","why":"Meteorology marks the convergence line as a named structure, because storms form along it.","whyCN":"气象学把这条辐合线标记为有名称的结构，因为风暴沿它生成。"},{"no":"07","title":"A monsoon climate and its agriculture","titleCN":"季风气候及其农业","definition":"a climate dominated by seasonal winds, on which planting and irrigation are timed","definitionCN":"由季节性风主导、播种与灌溉据此安排的气候","example":"Rice farming in the delta depends on a monsoon climate.","exampleCN":"三角洲的水稻种植依赖季风气候。","why":"Once farmers plan around the reversal, the word becomes a label for a whole agricultural regime.","whyCN":"当农民围绕这一反转安排生产，这个词就成了整套农业制度的标签。"},{"no":"08","title":"A periodic mass arrival, figuratively","titleCN":"比喻周期性的大量到来","definition":"a large amount of something arriving on a regular cycle, likened to a rainy season","definitionCN":"按固定周期大量到来的事物，被比作雨季","example":"A monsoon of paperwork hits the office every September.","exampleCN":"每年九月，文书如季风般涌进办公室。","why":"The metaphor keeps periodicity and volume, not the wind's direction.","whyCN":"这一比喻保留周期性与体量，而不保留风向。"}],"etymology":{"intro":{"en":"Monsoon reached English in the sixteenth century through Portuguese monção, from Arabic mawsim 'season, time of year', originally the fixed season for sailing. A Malay route has been proposed but is not settled.","cn":"monsoon 于 16 世纪经葡萄牙语 monção 进入英语，源自阿拉伯语 mawsim「季节、时令」，原指固定的航行季节。经马来语的传播路径有人提出，但尚无定论。"},"items":[{"era":"ARABIC MAWSIM","en":"Arabic mawsim meant 'season, festival, time of year', and in the Indian Ocean trade it named the season when winds allowed a voyage.","cn":"阿拉伯语 mawsim 指「季节、节庆、时令」，在印度洋贸易中特指风向允许航行的季节。"},{"era":"PORTUGUESE MONCAO","en":"Portuguese sailors adopted the word and applied it to the seasonal wind itself, not only to the sailing season.","cn":"葡萄牙水手 采用了这个词，并把它用到季节风本身，而不只是航行季节。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"English took the Portuguese form in the sixteenth century, at first as a nautical term for the Indian Ocean winds.","cn":"英语在 16 世纪借入葡萄牙语形式，最初是印度洋风向的航海术语。"},{"era":"METEOROLOGICAL GENERALISATION","en":"Later meteorology generalised the word to any seasonal reversing wind system, including the West African and Australian monsoons.","cn":"后来的气象学把该词推广到任何季节性反向风系，包括西非与澳大利亚季风。"},{"era":"RAINY SEASON SENSE","en":"Because the summer wind reliably brings rain, the word also came to mean the rainy season itself.","cn":"由于夏季风可靠地带来降雨，这个词也转而指雨季本身。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (transmission route): a Malay or Persian intermediary is sometimes proposed, but the documented chain runs through Portuguese; the exact first English date varies by several decades.","cn":"来源不确定（传播路径）：有时有人提出马来语或波斯语中介，但有文献的链条经葡萄牙语；英语首见的确切年代各家相差数十年。"}]},"similar":{"note":{"en":"Group one holds forms built on the headword; group two holds nearby seasonal-rain terms that are often used loosely as synonyms.","cn":"第一组由本词构成；第二组是常被宽泛当作同义词的季节性降雨词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monsoonal","ipa":"/mɒnˈsuːnl/","tag":"same root, adjective","definition":"Monsoon plus -al: of or caused by a monsoon, as in monsoonal rain.","definitionCN":"由 monsoon 加 -al：季风的或由季风引起的，如季风性降雨。"},{"word":"monsoon trough","ipa":"/mɒnˈsuːn trɒf/","tag":"technical compound","definition":"The convergence line of the monsoon flow, not the wind or the season.","definitionCN":"季风气流的辐合线，而非风本身或季节。"},{"word":"monsoon forest","ipa":"/mɒnˈsuːn ˈfɒrɪst/","tag":"ecological compound","definition":"A forest shaped by a pronounced dry season and heavy monsoon rain; the word names vegetation.","definitionCN":"受显著旱季与强季风雨塑造的森林；该词指植被。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rainy season","ipa":"/ˈreɪni ˈsiːzn/","tag":"plain description","definition":"The period of the year when most rain falls; it names the season without naming the wind.","definitionCN":"一年中降雨最多的时期；只指季节，不指风。"},{"word":"wet season","ipa":"/wet ˈsiːzn/","tag":"tropical usage","definition":"The wet half of a tropical year, used where the contrast with a dry season matters most.","definitionCN":"热带年份中湿润的一半，多用于强调与旱季对照的语境。"},{"word":"trade wind","ipa":"/ˈtreɪd wɪnd/","tag":"steady, not seasonal","definition":"A steady easterly wind of the tropics; it reverses far less than a monsoon and is not a rainy season.","definitionCN":"热带稳定的东风；其反向远不如季风明显，也不指雨季。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Arabic source, the real reversal mechanism and the real technical compounds.","cn":"正常联想：真实的阿拉伯语来源、真实的反转机制与真实的技术复合词。"},"normal":[{"en":"Arabic mawsim meant 'season', and the sailing season gave the wind its name.","cn":"阿拉伯语 mawsim 指「季节」，航行季节把名字给了这种风。"},{"en":"Portuguese monção is the documented bridge into English.","cn":"葡萄牙语 monção 是有文献记录的中介形式。"},{"en":"Summer and winter halves blow in opposite directions.","cn":"夏季与冬季两半吹向相反。"},{"en":"Fixed terms: summer monsoon, winter monsoon, monsoon trough.","cn":"固定术语：夏季风、冬季风、季风槽。"},{"en":"The rainy season takes the wind's name because the rain follows it.","cn":"雨季取了风的名称，因为雨随它而来。"}],"abstract":[{"en":"Picture a door that swings one way for half the year and the other way for the rest.","cn":"想象一扇门，半年朝一边开，另半年朝另一边开。"},{"en":"Picture a wall of moisture walking inland and dropping its load on the first slope.","cn":"想象一堵湿气之墙走向内陆，在第一道山坡上卸下重负。"},{"en":"Picture an office calendar that floods on the same date every year.","cn":"想象一份办公日历，每年同一天准时被淹没。"}]},"examples":[{"en":"Farmers sow before the monsoon and harvest after it.","cn":"农民在季风前播种，在季风后收获。"},{"en":"The winter monsoon clears the haze from the coast.","cn":"冬季风吹散了海岸的霾。"},{"en":"The monsoon failed that year, and the wells dropped below the intake.","cn":"那年季风失约，井水降到了取水口以下。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「忙松」——雨季一到，农事忙、人难松 → 季风、雨季","word":"monsoon"},"root":"经葡萄牙语 monção 借自阿拉伯语 mawsim「季节、时令」，原指固定的航行季节；传入英语后指季节性反向风系与雨季。无拉丁同族，latinEntries 留空。","sensesIntro":{"en":"Eight senses follow the reversal: the wind itself, the season it creates, its two halves, the rain it releases, the trough where it converges, the agriculture built on it and finally a periodic flood of anything.","cn":"八个义项沿这一反转展开：风本身、它造成的季节、它的两半、它释放的雨、它辐合的槽、依赖它的农业，最后是任何事物的周期性涌来。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wind that changes its mind once a year, and everything living waits for the change.","cn":"核心意象：一年改一次主意的风，而一切生物都在等这次改变。"},"chain":["LAND HEATS","PRESSURE FALLS","SEA AIR DRAWN IN","MOISTURE LIFTED","RAIN RELEASED","SEASON NAMED"],"branches":[{"senses":"01 · 02","en":"WIND AND SEASON: the seasonal reversal and the rainy season it brings share one name.","cn":"风与季节：季节性反转与它带来的雨季共用一个名称。"},{"senses":"03 · 04","en":"TWO HALVES: the same system blows moist onshore in summer and dry offshore in winter.","cn":"两半：同一系统夏季把湿气吹上岸，冬季把干气吹向海。"},{"senses":"05","en":"RAIN: forced ascent turns the wind's moisture into visible precipitation.","cn":"雨：被迫抬升把风中的水汽变成可见降水。"},{"senses":"06 · 07","en":"STRUCTURE AND FARM: the convergence line organises storms; farmers organise their year around the wind.","cn":"结构与农事：辐合线组织风暴；农民围绕风安排一年。"},{"senses":"08","en":"PERIODIC ARRIVAL: only rhythm and volume are kept.","cn":"周期性到来：只保留节奏与体量。"}]},"affixes":{"intro":{"en":"Monsoon is a loanword with almost no native affix family; what English adds are the adjective suffix and compound nouns.","cn":"monsoon 是借词，几乎没有本族词缀家族；英语所加的是形容词后缀与复合名词。"},"latinIntro":{"en":"No Latin word takes part in this word; the source language is Arabic, transmitted through Portuguese.","cn":"本词没有拉丁语成分参与；来源语言为阿拉伯语，经葡萄牙语传入。"},"items":[{"word":"monsoon","structure":"monsoon (loanword from Portuguese monção)","meaning":"seasonal reversing wind","meaningCN":"季节性反向风","example":"The monsoon governs the delta.","exampleCN":"季风支配着这片三角洲。"},{"word":"-al","structure":"-al (adjective suffix)","meaning":"of or relating to","meaningCN":"……的；与……有关的","example":"Monsoonal cloudbands moved north.","exampleCN":"季风云带北移。"},{"word":"-season","structure":"-season (combining noun)","meaning":"the part of the year dominated by the wind","meaningCN":"由该风主导的时段","example":"The monsoon season begins in June.","exampleCN":"季风季节从六月开始。"},{"word":"monsoon-","structure":"monsoon (combining first element)","meaning":"of the monsoon","meaningCN":"季风的","example":"Monsoon rain reached the coast.","exampleCN":"季风雨抵达海岸。"},{"word":"-trough","structure":"-trough (technical combining noun)","meaning":"an elongated low-pressure zone","meaningCN":"狭长的低压带","example":"The monsoon trough spawned a depression.","exampleCN":"季风槽孕育了一个低压。"},{"word":"-forest","structure":"-forest (combining noun)","meaning":"woodland shaped by the seasonal rain","meaningCN":"由季节性降雨塑造的林地","example":"Monsoon forest covers the lower slopes.","exampleCN":"季风林覆盖着低处山坡。"},{"word":"-rainfall","structure":"-rainfall (combining noun)","meaning":"precipitation from the monsoon","meaningCN":"季风带来的降水","example":"Monsoon rainfall varies by decade.","exampleCN":"季风降水按十年尺度变化。"},{"word":"summer monsoon","structure":"summer + monsoon (compound noun)","meaning":"the moist onshore half","meaningCN":"湿润的上岸一半","example":"The summer monsoon broke in early June.","exampleCN":"夏季风在六月初爆发。"},{"word":"winter monsoon","structure":"winter + monsoon (compound noun)","meaning":"the dry offshore half","meaningCN":"干燥的离岸一半","example":"The winter monsoon brings dry air.","exampleCN":"冬季风带来干燥空气。"}],"latinEntries":[]}},{"word":"trade wind","ipa_uk":"/ˈtreɪd wɪnd/","ipa_us":"/ˈtreɪd wɪnd/","definition_zh":"信风；信风带；东北信风；东南信风","definition_en":"a steady easterly wind that blows from the subtropical high-pressure belt toward the equator","core_image":"帆船连续多日向同一舷侧倾斜，海面被恒定方向的风压出长条白纹","scene":"帆船驶出港口，风向整日不变，船首始终朝着同一个方向。A steady trade wind carried the sailing ship west across the Atlantic.","sceneCN":"这里指「副热带高压吹向赤道的持续偏东风」（第 1 个义项：风向稳定的低层行星风）；句意为稳定的信风把帆船一路向西送过大西洋。图中可辨识物件：同一舷侧倾斜的帆、长条白纹的海面、固定的风向旗、直线航迹。","pos":[{"tag":"n.","zh":"信风；信风带"}],"collocations":[{"phrase":"the northeast trade winds","zh":"东北信风"},{"phrase":"the southeast trade winds","zh":"东南信风"},{"phrase":"the trade-wind belt","zh":"信风带"},{"phrase":"steady trade winds","zh":"稳定的信风"},{"phrase":"the trade-wind inversion","zh":"信风逆温"},{"phrase":"sailing on the trade winds","zh":"借信风航行"}],"forms":[{"label":"复数","form":"trade winds"},{"label":"单数（可数）","form":"trade wind"},{"label":"东北信风（复合）","form":"northeast trade wind"},{"label":"东南信风（复合）","form":"southeast trade wind"},{"label":"信风带（复合）","form":"trade-wind belt"}],"derivatives":[{"word":"trades","pos":"n.","zh":"信风（复数，航海用语）"},{"word":"trade-wind belt","pos":"n.","zh":"信风带"},{"word":"northeast trade wind","pos":"n.","zh":"东北信风"},{"word":"southeast trade wind","pos":"n.","zh":"东南信风"},{"word":"trade-wind inversion","pos":"n.","zh":"信风逆温"}],"senses":[{"no":"01","title":"A steady easterly wind toward the equator","titleCN":"吹向赤道的持续偏东风","definition":"a persistent low-level wind that blows from the subtropical highs toward the equatorial low","definitionCN":"从副热带高压带持续吹向赤道低压带的低层风","example":"A steady trade wind carried the sailing ship west across the Atlantic.","exampleCN":"稳定的信风把帆船一路向西送过大西洋。","why":"The name marks constancy: the wind keeps one course for weeks, which is what sailors needed.","whyCN":"这个名称标记的是恒定性：风连续数周保持同一路径，这正是水手所需。"},{"no":"02","title":"The trade-wind belt","titleCN":"信风带","definition":"the zone on each side of the equator dominated by these winds, roughly between the equator and thirty degrees","definitionCN":"赤道两侧大致位于赤道至三十度之间、由信风主导的带状区域","example":"The trade-wind belt shifted poleward that summer.","exampleCN":"那年夏天，信风带向极地方向移动。","why":"A single wind becomes a geographical belt once its typical position is mapped.","whyCN":"一旦绘出典型位置，单独的风就成了地理上的带。"},{"no":"03","title":"The northeast trades","titleCN":"东北信风","definition":"the trade winds of the Northern Hemisphere, blowing from the northeast toward the southwest","definitionCN":"北半球的信风，自东北吹向西南","example":"The northeast trades kept the convoy on a southerly course.","exampleCN":"东北信风使船队保持向南的航向。","why":"Coriolis deflection turns the equatorward flow to the right in the north, so the wind arrives from the northeast.","whyCN":"科里奥利偏转使北半球向赤道的气流向右偏，因此风从东北方吹来。"},{"no":"04","title":"The southeast trades","titleCN":"东南信风","definition":"the trade winds of the Southern Hemisphere, blowing from the southeast toward the northwest","definitionCN":"南半球的信风，自东南吹向西北","example":"The southeast trades drove the whaling fleet north.","exampleCN":"东南信风把捕鲸船队推向北方。","why":"The same deflection mirrors across the equator, giving the southern half the opposite name.","whyCN":"同一偏转在赤道两侧镜像对称，使南半部得到相反的名称。"},{"no":"05","title":"Winds that made ocean sailing routine","titleCN":"使远洋帆船得以常态化航行的风","definition":"the winds whose reliability allowed regular round-trip trade routes under sail","definitionCN":"其可靠性使帆船定期往返航线成为可能的信风","example":"Sugar and cotton moved on ships that depended on the trade winds.","exampleCN":"糖与棉花靠依赖信风的船只运输。","why":"A wind that can be predicted makes a timetable possible, and a timetable makes trade possible.","whyCN":"可预测的风使时刻表成为可能，而时刻表使贸易成为可能。"},{"no":"06","title":"The trade-wind inversion","titleCN":"信风逆温","definition":"a temperature inversion within the trade-wind layer that caps cloud growth and keeps the lower air moist","definitionCN":"信风层内的温度逆温，抑制云的发展并使低层空气保持湿润","example":"The trade-wind inversion kept the showers shallow.","exampleCN":"信风逆温使阵雨只能停留在浅薄层次。","why":"Meteorology names the stable layer because it explains why tropical trade-wind weather is often fair.","whyCN":"气象学为这一稳定层命名，因为它解释了信风区天气为何多半晴好。"},{"no":"07","title":"Trade winds that weaken with El Nino","titleCN":"厄尔尼诺期间减弱的信风","definition":"the weakening or reversal of equatorial trade winds that permits warm water to spread eastward","definitionCN":"赤道信风减弱或反向，使暖水得以向东扩展","example":"When the trade winds slackened, the warm pool drifted east.","exampleCN":"信风一减弱，暖水团便向东漂移。","why":"The wind normally piles warm water in the west; take the wind away and the pile relaxes eastward.","whyCN":"信风平常把暖水堆在西侧；风一撤，水堆便向东松弛。"},{"no":"08","title":"A steady, dependable force, figuratively","titleCN":"比喻稳定可靠、持续推动的力量","definition":"a dependable force that keeps pushing something in one direction over a long period","definitionCN":"长期把某事物朝同一方向推动的可靠力量","example":"Steady demand acted as a trade wind for the small port.","exampleCN":"稳定的需求成了推动这个小港的信风。","why":"The metaphor keeps only reliability and direction, which is what the wind's name originally meant.","whyCN":"这一比喻只保留可靠性与方向，而这正是该风名最初的意思。"}],"etymology":{"intro":{"en":"Trade wind joins trade and wind. Here trade is not commerce: it goes back to Old English tredan 'to tread' and meant a fixed course or track, so the phrase named winds that keep one steady path. Wind is the native Old English wind.","cn":"trade wind 由 trade 与 wind 组合。此处 trade 并非商业：它可溯至古英语 tredan「踩、行走」，意为固定的路径或轨迹，因此该短语命名沿一条稳定路径吹的风。wind 则是古英语本族词。"},"items":[{"era":"OLD ENGLISH TREDAN","en":"Tredan meant 'to tread, to go on foot'; its noun trade developed the sense of a habitual course or track.","cn":"tredan 意为「踩、步行」；其名词 trade 发展出「惯常路径、轨迹」的意思。"},{"era":"SIXTEENTH-CENTURY NAUTICAL PHRASE","en":"In sixteenth-century sailing records trade wind named a wind that blows on a constant track, the sense sailors cared about.","cn":"在 16 世纪的航海记录中，trade wind 指沿固定轨迹吹的风，这正是水手关心的意思。"},{"era":"COMMERCE SENSE SEPARATE","en":"The commercial sense of trade grew from a different line of the same verb, through the idea of a regular business course; it did not create the wind phrase.","cn":"trade 的商业义由同一动词的另一条线索发展而来，经由「常规业务路径」的观念；它并未创造这个风名。"},{"era":"HADLEY CIRCULATION EXPLAINED","en":"Eighteenth- and nineteenth-century meteorology explained the winds as part of the tropical circulation, and the name was kept.","cn":"18 至 19 世纪的气象学把这些风解释为热带环流的一部分，名称沿用下来。"},{"era":"MODERN CLIMATOLOGY","en":"Modern climatology uses trade winds for the low-level easterlies and measures their strength as an index of El Nino.","cn":"现代气候学用 trade winds 指低层东风，并以其强度作为厄尔尼诺的指标。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and bridge): the step from 'trodden path' to 'steady wind' is generally accepted but not documented in detail, and the first English date is approximate.","cn":"来源不确定（首见年代与语义过渡）：「踩出的路径」到「稳定的风」这一步一般被接受，但缺乏细节书证；英语首见年代亦为约数。"}]},"similar":{"note":{"en":"Group one holds phrases built from the same two words that are easily confused with the meteorological term; group two holds neighbouring wind names.","cn":"第一组是由同样两个词构成、易与气象术语混淆的短语；第二组是邻近的风名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"trade route","ipa":"/ˈtreɪd ruːt/","tag":"commerce, not wind","definition":"A route used for commerce; here trade carries its business sense, not the 'fixed track' sense of the wind phrase.","definitionCN":"用于商业的路线；此处 trade 取商业义，而非风名中「固定路径」的意思。"},{"word":"trade winds","ipa":"/ˈtreɪd wɪndz/","tag":"plural form","definition":"The usual plural, naming the belt of winds rather than a single current of air.","definitionCN":"常用复数形式，指整条信风带，而非单独一股气流。"},{"word":"prevailing wind","ipa":"/prɪˈveɪlɪŋ wɪnd/","tag":"general term","definition":"The wind direction most frequent at a place; it is a statistical summary, not a specific tropical system.","definitionCN":"某地出现最多的风向；属统计概括，并非特定的热带风系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"easterlies","ipa":"/ˈiːstəliz/","tag":"direction only","definition":"Winds blowing from the east, including the trade winds; the term states direction, not origin or steadiness.","definitionCN":"自东吹来的风，包括信风；该词只说明方向，不说明起源或稳定性。"},{"word":"westerlies","ipa":"/ˈwestəliz/","tag":"opposite belt","definition":"The prevailing winds of the middle latitudes, blowing from the west; they lie poleward of the trades.","definitionCN":"中纬度的盛行风，自西吹来；位于信风带的向极一侧。"},{"word":"monsoon","ipa":"/mɒnˈsuːn/","tag":"seasonal, not steady","definition":"A seasonal reversing wind; unlike the trades it changes direction between summer and winter.","definitionCN":"季节性反向风；与信风不同，它在夏冬之间改变方向。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real 'tread' etymology, the real Hadley explanation and the real compass names.","cn":"正常联想：真实的「踩踏」词源、真实的哈得来环流解释与真实的方向名称。"},"normal":[{"en":"Trade here means a fixed track, from the verb to tread, not commerce.","cn":"此处 trade 指固定路径，出自动词「踩踏」，而非商业。"},{"en":"The northeast trades are the northern half; the southeast trades the southern half.","cn":"东北信风是北半部，东南信风是南半部。"},{"en":"Their constancy made ocean timetables possible.","cn":"它们的恒定性使远洋时刻表成为可能。"},{"en":"Fixed terms: trade-wind belt, trade-wind inversion, the trades.","cn":"固定术语：信风带、信风逆温、信风。"},{"en":"Weakening trades are an index of El Nino.","cn":"信风减弱是厄尔尼诺的一个指标。"}],"abstract":[{"en":"Picture a sail leaning the same way for twenty days.","cn":"想象一张帆连续二十天朝同一侧倾斜。"},{"en":"Picture a conveyor that never needs to be restarted.","cn":"想象一条从不需要重新启动的传送带。"},{"en":"Picture a path worn into the sea by repetition alone.","cn":"想象一条仅靠重复就在海面上磨出的路。"}]},"examples":[{"en":"The trade winds kept the humidity low over the leeward coast.","cn":"信风使背风海岸的湿度保持较低。"},{"en":"Old logbooks record the trades as reliably as a calendar.","cn":"旧航海日志记录信风的规律，可靠得像日历。"},{"en":"A weaker trade wind lets warm water drift east along the equator.","cn":"信风减弱时，暖水沿赤道向东漂移。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「trade（固定路径）+ wind（风）」——沿固定路径吹的风 → 信风","word":"trade wind"},"root":"trade 出自古英语 tredan「踩、行走」，此处取「固定路径」义，与商业义分属不同语义线；wind 为古英语本族词。无拉丁同族，latinEntries 留空。","sensesIntro":{"en":"Eight senses move from the single steady wind to its belt, its two hemispheric names, its role in sailing, its inversion, its weakening in El Nino and finally to any dependable force.","cn":"八个义项从单股稳定风，走到信风带、两个半球的名字、航海中的作用、逆温层、厄尔尼诺时的减弱，最后是任何可靠的力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wind that keeps one path so long that the path becomes a timetable.","cn":"核心意象：一股风长期保持同一条路径，久到这条路径变成了时刻表。"},"chain":["HIGH PRESSURE","EQUATORWARD FLOW","CORIOLIS TURN","STEADY EASTERLY","SAILING TRACK","CLIMATE INDEX"],"branches":[{"senses":"01 · 02","en":"WIND AND BELT: a single steady current becomes a mapped zone.","cn":"风与带：单股稳定气流变成图上的一条带。"},{"senses":"03 · 04","en":"TWO HEMISPHERES: the same deflection gives opposite names on either side of the equator.","cn":"两个半球：同一偏转在赤道两侧给出相反的名称。"},{"senses":"05","en":"SAILING: predictability turns wind into a schedule.","cn":"航海：可预测性把风变成时刻表。"},{"senses":"06 · 07","en":"STRUCTURE AND FAILURE: an inversion caps the cloud; a weakened wind releases warm water eastward.","cn":"结构与失效：逆温压住云顶；风减弱则把暖水向东释放。"},{"senses":"08","en":"METAPHOR: reliability and direction are all that remain.","cn":"比喻：只剩可靠性与方向。"}]},"affixes":{"intro":{"en":"Trade wind is a two-word English phrase; its internal parts are native verbs and nouns, not classical affixes.","cn":"trade wind 是英语双词短语，其内部成分是本族动词与名词，而非古典词缀。"},"latinIntro":{"en":"No Latin element enters either word; the phrase is wholly Germanic in origin.","cn":"两个词都不含拉丁成分；该短语完全源自日耳曼语。"},"items":[{"word":"trade","structure":"trade (noun from Old English tredan 'to tread')","meaning":"a fixed course or track","meaningCN":"固定的路径或轨迹","example":"The old meaning survives only in the wind phrase.","exampleCN":"这一旧义只保留在信风短语里。"},{"word":"wind","structure":"wind (Old English noun)","meaning":"moving air","meaningCN":"流动的空气","example":"The wind held from the east for a week.","exampleCN":"东风持续了一个星期。"},{"word":"-s","structure":"-s (plural inflection)","meaning":"more than one; the belt as a whole","meaningCN":"多于一个；整体指信风带","example":"The trades filled the sails.","exampleCN":"信风鼓满了帆。"},{"word":"northeast","structure":"north + east (compound direction)","meaning":"from the northeast","meaningCN":"来自东北","example":"The northeast trades blow toward the southwest.","exampleCN":"东北信风吹向西南。"},{"word":"southeast","structure":"south + east (compound direction)","meaning":"from the southeast","meaningCN":"来自东南","example":"The southeast trades cross the equator.","exampleCN":"东南信风越过赤道。"},{"word":"-belt","structure":"-belt (combining noun, 'band')","meaning":"a latitudinal zone","meaningCN":"纬向的带状区域","example":"The trade-wind belt widened in the warm year.","exampleCN":"暖年信风带变宽。"},{"word":"-inversion","structure":"-inversion (technical combining noun)","meaning":"a layer where temperature rises with height","meaningCN":"温度随高度上升的层次","example":"The trade-wind inversion limits shower depth.","exampleCN":"信风逆温限制阵雨厚度。"},{"word":"-ward","structure":"-ward (direction suffix)","meaning":"in the direction of","meaningCN":"朝……方向","example":"The leeward side stays dry.","exampleCN":"背风侧保持干燥。"},{"word":"trade-","structure":"trade (combining first element)","meaning":"of the trade winds","meaningCN":"信风的","example":"Trade-wind cloud streets lined the sea.","exampleCN":"信风云街排列在海面上。"}],"latinEntries":[]}},{"word":"jet stream","ipa_uk":"/ˈdʒet striːm/","ipa_us":"/ˈdʒet striːm/","definition_zh":"急流；高空强而窄的气流带；极地急流；副热带急流","definition_en":"a narrow, fast band of wind in the upper troposphere that steers weather systems and aircraft","core_image":"高空一条绷紧的白色卷云带被拉成细长直线，飞机顺着它加速，风暴在它下方被牵着走","scene":"高空那条狭长的高速气流像一根绷紧的绳，把风暴一路牵向东北。The jet stream steered the storm north-east across the Pacific.","sceneCN":"这里指「对流层上部狭长的高速风带」（第 1 个义项：风速极大、呈带状的上层气流）；句意为急流把风暴引导向东北，横越太平洋。图中可辨识物件：拉长的卷云带、顺流加速的飞机、被牵引的风暴云系、高空流线。","pos":[{"tag":"n.","zh":"急流；高空强风带"}],"collocations":[{"phrase":"the polar jet stream","zh":"极地急流"},{"phrase":"the subtropical jet stream","zh":"副热带急流"},{"phrase":"a jet stream trough","zh":"急流槽"},{"phrase":"the jet stream pattern","zh":"急流型"},{"phrase":"ride the jet stream","zh":"借急流飞行"},{"phrase":"jet stream winds","zh":"急流风速"}],"forms":[{"label":"复数","form":"jet streams"},{"label":"极地急流（复合）","form":"polar jet stream"},{"label":"副热带急流（复合）","form":"subtropical jet stream"},{"label":"急流核（术语）","form":"jet streak"},{"label":"急流槽（术语）","form":"jet stream trough"}],"derivatives":[{"word":"polar jet stream","pos":"n.","zh":"极地急流"},{"word":"subtropical jet stream","pos":"n.","zh":"副热带急流"},{"word":"jet streak","pos":"n.","zh":"急流核"},{"word":"jet stream trough","pos":"n.","zh":"急流槽"},{"word":"jet-stream level","pos":"n.","zh":"急流高度层"}],"senses":[{"no":"01","title":"A narrow fast band in the upper troposphere","titleCN":"对流层上部狭长的高速风带","definition":"a narrow band of very strong wind near the tropopause, marked by sharp horizontal wind shear","definitionCN":"对流层顶附近风力极强、水平风切变明显的狭长风带","example":"The jet stream steered the storm north-east across the Pacific.","exampleCN":"急流把风暴引导向东北，横越太平洋。","why":"The name joins a fast jet of air to a stream of water: both are narrow, fast and confined.","whyCN":"这个名字把高速气流之「射流」与水流之「溪流」合在一起：两者都窄、都快、都受限。"},{"no":"02","title":"The polar jet stream","titleCN":"极地急流","definition":"the jet stream associated with the polar front, lying between the mid-latitudes and the polar air","definitionCN":"与极锋相关、位于中纬度与极地空气之间的急流","example":"The polar jet stream dipped south and brought Arctic air to the plains.","exampleCN":"极地急流南压，把北极空气带到平原。","why":"The temperature contrast at the polar front is what concentrates the wind into a narrow core.","whyCN":"极锋处的温差正是把风集中成狭窄核心的原因。"},{"no":"03","title":"The subtropical jet stream","titleCN":"副热带急流","definition":"the jet stream found near thirty degrees latitude, linked to the subtropical high and the Hadley circulation","definitionCN":"位于纬度三十度附近、与副热带高压及哈得来环流相关的急流","example":"The subtropical jet stream carried moisture toward the coast.","exampleCN":"副热带急流把水汽送向海岸。","why":"A second maximum exists where the Hadley cell returns its air aloft, separate from the polar front.","whyCN":"在哈得来环流高空回流处还存在第二个极大值，与极锋无关。"},{"no":"04","title":"The wind that changes flight times","titleCN":"改变飞行时间的风","definition":"the upper wind whose direction can shorten an eastbound flight or lengthen a westbound one","definitionCN":"其方向可缩短向东航班、延长向西航班的高空风","example":"A strong jet stream cut two hours off the eastbound flight.","exampleCN":"强劲的急流使向东航班缩短了两小时。","why":"Aircraft fly within the flow, so a following stream adds ground speed and an opposing one subtracts it.","whyCN":"飞机在气流中飞行，顺流增加地速，逆流则减少。"},{"no":"05","title":"A guide for surface weather systems","titleCN":"地面天气系统的引导带","definition":"the upper flow that steers cyclones and anticyclones along its path","definitionCN":"沿其路径引导气旋与反气旋移动的上层气流","example":"The jet stream turned the depression toward the British Isles.","exampleCN":"急流把低压转向不列颠群岛。","why":"Surface lows are steered by the stronger flow above them, so the jet acts as rails.","whyCN":"地面低压被上方更强的气流引导，因此急流起了轨道的作用。"},{"no":"06","title":"Clear-air turbulence","titleCN":"晴空颠簸","definition":"turbulence near the jet stream that occurs without cloud, caused by wind shear","definitionCN":"急流附近无云却由风切变引起的颠簸","example":"The crew warned passengers about clear-air turbulence near the jet stream.","exampleCN":"机组提醒乘客急流附近有晴空颠簸。","why":"Where fast air meets slower air, the boundary becomes unstable even when the sky looks empty.","whyCN":"当快气流遇到慢气流，即使天空看起来空无一物，边界也会失稳。"},{"no":"07","title":"The seasonal shift of the jet","titleCN":"急流的季节性移动","definition":"the poleward shift in summer and equatorward shift in winter of the jet stream's typical position","definitionCN":"急流典型位置在夏季向极地、冬季向赤道的移动","example":"The jet stream's seasonal shift decides where the rains arrive.","exampleCN":"急流的季节性移动决定了雨带抵达何处。","why":"The temperature contrast that drives the jet moves with the seasons, so the rail moves with it.","whyCN":"驱动急流的温差随季节移动，因此这条轨道也随之移动。"},{"no":"08","title":"A fast, unceasing channel, figuratively","titleCN":"比喻高速不息的通道","definition":"a fast, continuous channel that carries things along with little friction","definitionCN":"把事物低阻力地持续带走的快速通道","example":"The city became a jet stream of capital and talent.","exampleCN":"这座城市成了一条资金与人才的高速通道。","why":"The metaphor keeps speed, narrowness and one-way flow, dropping the meteorology.","whyCN":"这一比喻保留速度、狭窄与单向流动，去掉气象内容。"}],"etymology":{"intro":{"en":"Jet stream joins jet, from Old French jeter 'to throw' and Latin iactare, with stream, the native Old English word for flowing water. Meteorologists coined the compound in the 1940s for the upper wind maximum.","cn":"jet stream 由 jet 与 stream 组合。jet 经古法语 jeter「投掷」来自拉丁 iactare；stream 是古英语本族词，指流动的水。气象学家在 20 世纪 40 年代用这个复合词指上层风的最大值。"},"items":[{"era":"LATIN IACTARE","en":"Latin iactare 'to throw, to hurl' is the frequentative of iacere; through Old French jeter it gave English jet, a fast stream of something thrown out.","cn":"拉丁 iactare「投、掷」是 iacere 的反复式；经古法语 jeter 给出英语 jet，指被喷出的高速流。"},{"era":"OLD ENGLISH STREAM","en":"Stream is the native word for a flowing body of water, so the compound compares air to water.","cn":"stream 是表示流动水体的本族词，因此复合词把空气比作水。"},{"era":"HIGH-ALTITUDE DISCOVERY","en":"Pilots in the Second World War met unexpectedly strong upper winds; the phenomenon was named in the 1940s.","cn":"二战飞行员遭遇了意外的上层强风；这一现象在 20 世纪 40 年代获得名称。"},{"era":"DYNAMICAL EXPLANATION","en":"Post-war meteorology explained the jet as a response to the temperature contrast between tropical and polar air.","cn":"战后气象学把急流解释为对热带与极地空气温差的响应。"},{"era":"GLOBAL FORECASTING","en":"Numerical models made the jet's waves central to medium-range forecasting and aviation routing.","cn":"数值模式使急流的波动成为中期预报与航空航线规划的核心。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact year and the first author of the term are reported differently; the elements and their meanings are themselves not in doubt.","cn":"来源不确定（首见年代）：该术语的确切年份与首创者各家记述不同；其构成成分与含义本身并无疑义。"}]},"similar":{"note":{"en":"Group one holds phrases and terms that look or sound like the meteorological jet stream; group two holds other names for the upper-level flow.","cn":"第一组是字形或读音近似气象术语的词组；第二组是上层气流的其他名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"jet","ipa":"/dʒet/","tag":"base word, many senses","definition":"A fast stream of gas or liquid, or an aircraft engine; the compound uses only the first of these.","definitionCN":"气体或液体的高速流，或喷气发动机；复合词只用前者。"},{"word":"Gulf Stream","ipa":"/ˈɡʌlf striːm/","tag":"ocean current, not wind","definition":"A warm ocean current in the Atlantic; it shares the water word but is not part of the atmosphere.","definitionCN":"大西洋中的暖洋流；共享「水流」这一词，但不在大气中。"},{"word":"jet lag","ipa":"/ˈdʒet læɡ/","tag":"travel fatigue","definition":"The fatigue caused by crossing time zones quickly; it borrows jet from air travel, not from the wind.","definitionCN":"快速跨越时区造成的疲劳；其 jet 借自航空旅行，而非风。"}]},{"heading":"NEAR MEANING","entries":[{"word":"westerlies","ipa":"/ˈwestəliz/","tag":"broad belt","definition":"The broad mid-latitude westerly flow within which the jet stream is embedded; wider and slower.","definitionCN":"急流所嵌入的中纬度宽广西风气流；更宽也更慢。"},{"word":"upper-level flow","ipa":"/ˈʌpə levl fləʊ/","tag":"general description","definition":"Any wind flow in the upper troposphere; the jet stream is its narrow, fastest part.","definitionCN":"对流层上部的任何气流；急流是其中最窄最快的部分。"},{"word":"thermal wind","ipa":"/ˈθɜːml wɪnd/","tag":"derived quantity","definition":"The vertical shear of the horizontal wind produced by temperature gradients; the jet is explained through it.","definitionCN":"由温度梯度产生的水平风垂直切变；急流借它得到解释。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin source of jet, the real water word and the real meteorological purpose.","cn":"正常联想：喷流一词真实的拉丁来源、真实的「水流」词，以及真实的气象用途。"},"normal":[{"en":"Jet is a fast stream thrown out; stream is flowing water: air behaves like both.","cn":"jet 是喷出的高速流，stream 是流动的水：空气兼具两者特征。"},{"en":"Two jets: polar and subtropical.","cn":"两条急流：极地急流与副热带急流。"},{"en":"It steers surface lows, so it works as a rail.","cn":"它引导地面低压，因此像一条轨道。"},{"en":"Flying east with it saves time; flying west against it costs time.","cn":"顺它向东省时，逆它向西费时。"},{"en":"Near the jet, wind shear causes clear-air turbulence without cloud.","cn":"急流附近的风切变会在无云时造成晴空颠簸。"}],"abstract":[{"en":"Picture a river of air drawn thin and fast, with weather hanging from it.","cn":"想象一条被拉得又细又快的空气之河，天气挂在它下面。"},{"en":"Picture an aircraft that gains speed without burning more fuel.","cn":"想象一架不烧更多油却变快的飞机。"},{"en":"Picture a channel so fast that nothing inside it can slow down.","cn":"想象一条快到其中任何东西都无法减速的通道。"}]},"examples":[{"en":"The jet stream split, sending cold air south and warm air north.","cn":"急流分成两支，把冷空气送向南、暖空气送向北。"},{"en":"Forecasters watch the jet stream to place the rain band.","cn":"预报员观察急流以确定雨带位置。"},{"en":"The return flight took longer because it flew against the jet stream.","cn":"返程航班因逆着急流飞行而耗时更久。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「jet（喷射）+ stream（水流）」——像喷射水流一样的高空急流 → 急流","word":"jet stream"},"root":"jet 经古法语 jeter「投掷」出自拉丁 iactare（iacere 的反复式）；stream 为古英语本族词，指流动的水。复合词由气象学在 20 世纪 40 年代造出，指上层风的最大值。","sensesIntro":{"en":"Eight senses move from the upper wind band itself to its polar and subtropical forms, its effects on flight, on storms, on turbulence, its seasonal drift and finally its use as an image of any fast channel.","cn":"八个义项从上层风带本身，走到极地与副热带两种形态、对飞行的影响、对风暴的引导、对颠簸的作用、季节性漂移，最后用作任何快速通道的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a river of air pulled thin and fast, with everything below hanging from it.","cn":"核心意象：一条被拉得又细又快的空气之河，下方一切都挂在它上面。"},"chain":["TEMPERATURE CONTRAST","PRESSURE GRADIENT","NARROW CORE","WIND SHEAR","STEERING","SEASONAL DRIFT"],"branches":[{"senses":"01 · 02 · 03","en":"ONE PHENOMENON, THREE NAMES: the general band and its polar and subtropical forms.","cn":"同一现象三种名称：一般风带及其极地、副热带两种形态。"},{"senses":"04","en":"FLIGHT: flying with the flow adds speed; flying against it subtracts.","cn":"飞行：顺流加速，逆流减速。"},{"senses":"05","en":"STEERING: surface lows follow the rails above them.","cn":"引导：地面低压沿着上方的轨道走。"},{"senses":"06","en":"SHEAR: fast air beside slow air becomes turbulent even in clear sky.","cn":"切变：快空气贴着慢空气，即使晴空也会起湍流。"},{"senses":"07 · 08","en":"DRIFT AND METAPHOR: the rail moves with the season, and any fast channel borrows its name.","cn":"漂移与比喻：轨道随季节移动，任何快速通道都借用它的名字。"}]},"affixes":{"intro":{"en":"Jet stream is a modern English compound of a French-derived noun and a native noun, so its parts are best read as two words rather than as affixes.","cn":"jet stream 是现代英语复合词，由一个法语来源名词与一个本族名词构成，因此宜按两个词来读，而非按词缀。"},"latinIntro":{"en":"Only jet has a Latin ancestor, iactare; stream is Germanic, and no Latin prefix is involved.","cn":"只有 jet 有拉丁祖先 iactare；stream 属日耳曼语，且不涉及任何拉丁前缀。"},"items":[{"word":"jet","structure":"jet (noun from Old French jeter, Latin iactare)","meaning":"a fast stream thrown out","meaningCN":"被喷出的高速流","example":"A jet of water cut the soil.","exampleCN":"一股水流切开土壤。"},{"word":"stream","structure":"stream (Old English, flowing water)","meaning":"a continuous flow","meaningCN":"连续的水流","example":"The stream ran fast after the rain.","exampleCN":"雨后溪水流得很快。"},{"word":"jet-","structure":"jet (combining first element)","meaning":"of a jet or of jets","meaningCN":"射流的；喷气式的","example":"Jet aircraft cross the ocean in hours.","exampleCN":"喷气飞机数小时就跨越海洋。"},{"word":"-stream","structure":"-stream (combining noun, 'flow')","meaning":"a flow imagined as water","meaningCN":"被想象成水流的流动","example":"The data stream never pauses.","exampleCN":"数据流从不停歇。"},{"word":"polar","structure":"polar (adjective, 'of the pole')","meaning":"associated with polar air","meaningCN":"与极地空气相关的","example":"The polar jet sits farther north in summer.","exampleCN":"极地急流在夏季位置更北。"},{"word":"subtropical","structure":"sub- + tropical (adjective)","meaning":"just outside the tropics","meaningCN":"紧邻热带之外的","example":"The subtropical jet is highest in winter.","exampleCN":"副热带急流在冬季最强。"},{"word":"-streak","structure":"-streak (technical combining noun)","meaning":"a local maximum within the jet","meaningCN":"急流中的局地最大值","example":"A jet streak crossed the ridge.","exampleCN":"一个急流核越过山脊。"},{"word":"-trough","structure":"-trough (technical combining noun)","meaning":"a downbend in the upper flow","meaningCN":"上层气流的下凹处","example":"The jet stream trough deepened over the coast.","exampleCN":"急流槽在海岸上空加深。"},{"word":"-level","structure":"-level (combining noun, 'height')","meaning":"the altitude of the jet core","meaningCN":"急流核心所在的高度","example":"Ice crystals persist at jet-stream level.","exampleCN":"冰晶在急流高度层持续存在。"}],"latinEntries":[{"word":"iacere","structure":"iacere, ieci, iactum (verb, third conjugation)","meaning":"to throw, to cast","meaningCN":"投；掷"},{"word":"iactare","structure":"iactare, iactavi, iactatum (verb, first conjugation)","meaning":"to throw about, to hurl repeatedly","meaningCN":"反复投掷；猛掷"},{"word":"iactus","structure":"iactus, iactus (m., fourth declension)","meaning":"a throw, a cast","meaningCN":"投掷；抛出"}]}},{"word":"air mass","ipa_uk":"/ˈeə mæs/","ipa_us":"/ˈer mæs/","definition_zh":"气团；气团源地；冷气团；暖气团；气团变性","definition_en":"a large body of air with broadly uniform temperature and humidity, shaped over a source region and later modified as it moves","core_image":"一整块温湿度均匀的空气像看不见的厚毯盖住大陆，边缘与另一块空气相撞处云带陡起","scene":"北方的干冷空气整块南下，盆地的气温一夜之间降了下来。A cold air mass moved south and chilled the whole basin.","sceneCN":"这里指「性质水平均匀的大块空气」（第 1 个义项：在源地获得温湿度特征的大范围气块）；句意为一个冷气团南下，使整个盆地变冷。图中可辨识物件：整块推进的冷空气、被压低的云带、结霜的田面、下降的温度计。","pos":[{"tag":"n.","zh":"气团；气团源地；冷气团；暖气团"}],"collocations":[{"phrase":"a cold air mass","zh":"冷气团"},{"phrase":"a warm air mass","zh":"暖气团"},{"phrase":"air-mass source region","zh":"气团源地"},{"phrase":"air-mass modification","zh":"气团变性"},{"phrase":"a continental air mass","zh":"大陆气团"},{"phrase":"a maritime air mass","zh":"海洋气团"}],"forms":[{"label":"复数","form":"air masses"},{"label":"冷气团（复合）","form":"cold air mass"},{"label":"暖气团（复合）","form":"warm air mass"},{"label":"气团源地（复合）","form":"air-mass source region"},{"label":"气团变性（复合）","form":"air-mass modification"}],"derivatives":[{"word":"airmass","pos":"n.","zh":"气团（连写变体）"},{"word":"air-mass source region","pos":"n.","zh":"气团源地"},{"word":"air-mass modification","pos":"n.","zh":"气团变性"},{"word":"cold air mass","pos":"n.","zh":"冷气团"},{"word":"warm air mass","pos":"n.","zh":"暖气团"}],"senses":[{"no":"01","title":"A large body of uniform air","titleCN":"性质水平均匀的大块空气","definition":"a large volume of air whose temperature and humidity vary little across hundreds of kilometres","definitionCN":"在数百公里范围内温度与湿度变化很小的大体积空气","example":"A cold air mass moved south and chilled the whole basin.","exampleCN":"一个冷气团南下，使整个盆地变冷。","why":"Meteorology needed a unit larger than a local parcel and more uniform than the whole atmosphere.","whyCN":"气象学需要一个比局地气块更大、又比整个大气更均匀的单位。"},{"no":"02","title":"The source region where it forms","titleCN":"气团形成的源地","definition":"the extensive surface, ocean or ice, over which an air mass acquires its temperature and moisture","definitionCN":"气团借以获得温度与湿度的大面积地表、海洋或冰面","example":"The polar air mass formed over the ice and kept its low humidity.","exampleCN":"极地气团在冰面上形成，并保持了低湿度。","why":"A body of air takes the character of the ground it sits on, so the ground gets a name too.","whyCN":"空气会带上它所停留地面的性格，因此地面也有了一个名称。"},{"no":"03","title":"Classification by latitude and surface","titleCN":"按纬度与下垫面分类","definition":"the grouping of air masses as polar or tropical and as continental or maritime","definitionCN":"按极地或热带、大陆或海洋来划分气团","example":"Forecasters labelled the air mass continental polar.","exampleCN":"预报员把该气团标为大陆极地气团。","why":"Two axes, latitude and surface, give four main types, which is enough for synoptic charts.","whyCN":"纬度与下垫面两条轴给出四种主要类型，对天气图分析已经够用。"},{"no":"04","title":"A cold air mass","titleCN":"冷气团","definition":"an air mass colder than the surface beneath it, which cools the ground as it passes","definitionCN":"比所经地面更冷、经过时使地面降温的气团","example":"A cold air mass brought frost to the vineyards.","exampleCN":"冷气团给葡萄园带来了霜。","why":"The label is relative: the same air is 'cold' only with respect to what lies under it.","whyCN":"这个标签是相对的：同一团空气只是相对于其下方的表面才称为冷。"},{"no":"05","title":"A warm air mass","titleCN":"暖气团","definition":"an air mass warmer than the surface beneath it, which warms the ground as it passes","definitionCN":"比所经地面更暖、经过时使地面升温的气团","example":"A warm air mass from the sea raised the night temperature.","exampleCN":"来自海上的暖气团抬高了夜间气温。","why":"The warm label follows the same relative logic as the cold one.","whyCN":"暖气团的标签遵循与冷气团相同的相对逻辑。"},{"no":"06","title":"Modification as it travels","titleCN":"移动过程中的气团变性","definition":"the change an air mass undergoes when it passes over a surface with different temperature or moisture","definitionCN":"气团经过温度或湿度不同的下垫面时发生的变化","example":"Air-mass modification turned the dry continental air into a snow producer.","exampleCN":"气团变性把干燥的大陆空气变成了能下雪的气团。","why":"Air is not sealed; it exchanges heat and water with every surface it crosses.","whyCN":"空气不是密封的；它每经过一个表面都会交换热量与水汽。"},{"no":"07","title":"The boundary between two air masses","titleCN":"两个气团之间的交界","definition":"the sloping surface where two air masses meet, which is what a front maps","definitionCN":"两个气团相遇的倾斜界面，锋面所描绘的正是这个界面","example":"Where the two air masses met, a front sharpened the rain into a line.","exampleCN":"两个气团相遇之处，锋面把降雨收束成一条线。","why":"A front is not a separate object but the visible consequence of two air masses touching.","whyCN":"锋面不是独立物体，而是两个气团接触后可见的结果。"},{"no":"08","title":"A homogeneous bloc, figuratively","titleCN":"比喻同质的一大块","definition":"a large, uniform group or mood that moves as a single body through a population","definitionCN":"在人群中作为整体移动的一大块同质群体或情绪","example":"An air mass of indifference settled over the electorate.","exampleCN":"一大团冷漠笼罩了选民。","why":"The metaphor keeps size and internal uniformity, not the weather.","whyCN":"这一比喻保留体量与内部同质性，而不保留天气。"}],"etymology":{"intro":{"en":"Air mass joins air, from Greek aēr through Latin aer, and mass, from Latin massa 'lump', itself from Greek maza. The meteorological compound was coined in the early twentieth century by the Norwegian school of forecasting.","cn":"air mass 由 air 与 mass 组合。air 经拉丁 aer 出自希腊 aēr；mass 出自拉丁 massa「团块」，其源又是希腊 maza。这个气象复合词由挪威预报学派在 20 世纪初造出。"},"items":[{"era":"GREEK AER AND LATIN AER","en":"Greek aēr named the lower, misty air; Latin aer carried it into learned European vocabulary.","cn":"希腊 aēr 指低层有雾的空气；拉丁 aer 把它带入欧洲学术词汇。"},{"era":"LATIN MASSA","en":"Massa meant a lump or mass, from Greek maza 'kneaded dough', and gave English mass in both physical and figurative senses.","cn":"massa 指团块，源自希腊 maza「揉好的面团」，并给出英语 mass 的物理义与比喻义。"},{"era":"NORWEGIAN SCHOOL","en":"Forecasters at Bergen in the early twentieth century treated the atmosphere as colliding bodies of air and named those bodies air masses.","cn":"20 世纪初卑尔根的预报员把大气视为相互碰撞的空气体，并把这些空气体命名为气团。"},{"era":"CLASSIFICATION","en":"The same school classified air masses by source latitude and surface, and linked their boundaries to fronts.","cn":"同一学派按源地纬度与下垫面对气团分类，并把它们的交界与锋面联系起来。"},{"era":"MODIFICATION STUDIES","en":"Later work on air-mass modification explained how cold continental air becomes unstable over warm sea.","cn":"后来的气团变性研究解释了冷大陆空气经过暖海面时如何变得不稳定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the exact year the compound entered print is reported differently, and the priority between Bergen authors is debated; the technical meaning itself is settled.","cn":"来源不确定（仅首见年代）：复合词进入印刷的确切年份各家记述不同，卑尔根诸作者的首创权亦有争议；技术含义本身已确定。"}]},"similar":{"note":{"en":"Group one holds terms built on the same two words or on the same concept; group two holds neighbouring atmospheric bodies and boundaries.","cn":"第一组是由同样两个词或同一概念构成的术语；第二组是邻近的大气气块与交界名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"airmass","ipa":"/ˈeəmæs/","tag":"spelling variant","definition":"The same term written as one word, common in meteorology texts; there is no difference in meaning.","definitionCN":"同一术语的连写形式，常见于气象文献；含义没有差别。"},{"word":"air mass thunderstorm","ipa":"/ˈeə mæs ˈθʌndəstɔːm/","tag":"technical compound","definition":"A thunderstorm formed within one air mass rather than at a front; the phrase is not the air mass itself.","definitionCN":"在同一气团内部而非锋面处形成的雷暴；该短语并非气团本身。"},{"word":"mass","ipa":"/mæs/","tag":"base word, wider","definition":"A quantity of matter or a large body of anything; only the meteorological compound adds 'uniform air'.","definitionCN":"物质的数量，或任何事物的一大团；只有气象复合词才增加「均匀空气」这层意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"air parcel","ipa":"/ˈeə pɑːsl/","tag":"smaller unit","definition":"A small imagined volume used in thermodynamics; an air mass is millions of such parcels sharing properties.","definitionCN":"热力学中使用的小体积想象单位；气团是共享性质的大量此类气块。"},{"word":"front","ipa":"/frʌnt/","tag":"the boundary","definition":"The sloping interface between two air masses; the air masses are the bodies, the front is their contact.","definitionCN":"两个气团之间的倾斜界面；气团是体，锋面是它们的接触处。"},{"word":"weather system","ipa":"/ˈweðə ˈsɪstəm/","tag":"broader term","definition":"Any organised atmospheric structure, including lows, highs and air masses; it is not a synonym.","definitionCN":"任何有组织的大气结构，包括低压、高压与气团；并非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek and Latin sources and the real Bergen-school origin.","cn":"正常联想：真实的希腊与拉丁来源，以及真实的卑尔根学派源头。"},"normal":[{"en":"Air plus mass: a lump of air big enough to cover a region.","cn":"air 加 mass：一大团大到能覆盖一个区域的空气。"},{"en":"Two axes classify it: polar or tropical, continental or maritime.","cn":"两条轴给气团分类：极地或热带、大陆或海洋。"},{"en":"The source region stamps its temperature and humidity on the air.","cn":"源地把温度与湿度印在空气上。"},{"en":"The Bergen school linked air masses to fronts in the early twentieth century.","cn":"卑尔根学派在 20 世纪初把气团与锋面联系起来。"},{"en":"Modification explains why cold dry air can snow over a warm sea.","cn":"气团变性解释了冷干空气为何能在暖海上致雪。"}],"abstract":[{"en":"Picture an invisible blanket with a place-name printed on it.","cn":"想象一条看不见的毯子，上面印着一个地名。"},{"en":"Picture two crowds walking into each other and a line forming where they meet.","cn":"想象两群人迎面走来，在相接处形成一条线。"},{"en":"Picture a mood large enough to cover a whole electorate.","cn":"想象一种大到能盖住全体选民的情绪。"}]},"examples":[{"en":"The air mass was so uniform that radiosondes gave the same reading twice.","cn":"该气团如此均匀，以致两次探空读数完全相同。"},{"en":"Maritime air masses keep the coast mild in winter.","cn":"海洋气团使海岸冬季温和。"},{"en":"Two air masses met over the plain and produced a sharp line of showers.","cn":"两个气团在平原上空相遇，形成一条清晰的阵雨带。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「air（空气）+ mass（团块）」——一大团性质均匀的空气 → 气团","word":"air mass"},"root":"air 经拉丁 aer 出自希腊 aēr「低层空气」；mass 出自拉丁 massa「团块」，源出希腊 maza「面团」。复合词为 20 世纪初气象学术语。","sensesIntro":{"en":"Eight senses describe one body of air: the uniform volume, its source, its classification, its cold and warm types, its modification, the front it makes and finally any uniform bloc of people.","cn":"八个义项描述同一团空气：均匀的体积、源地、分类、冷与暖的类型、变性、与其他气团形成的锋，最后是任何同质的人群大块。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible slab of air that carries the character of the ground it grew up on.","cn":"核心意象：一块看不见的空气板，带着它生长之地的性格。"},"chain":["SURFACE HEATS AIR","MOISTURE SETTLES","UNIFORM BODY","CLASSIFIED","MOVES AND CHANGES","MEETS ANOTHER"],"branches":[{"senses":"01 · 02","en":"BODY AND BIRTHPLACE: a uniform volume is defined by the region that made it uniform.","cn":"体与出生地：均匀的体积由使它均匀的区域来定义。"},{"senses":"03 · 04 · 05","en":"LABELS: latitude and surface classify it, and cold or warm is relative to the ground below.","cn":"标签：纬度与下垫面给它分类，冷或暖相对于下方地面。"},{"senses":"06","en":"CHANGE: nothing stays sealed; every surface exchanges heat and water with it.","cn":"变化：没有东西是密封的；每个表面都与它交换热与水。"},{"senses":"07","en":"CONTACT: a front is only the meeting place of two such bodies.","cn":"接触：锋面只是两个这样气团的相遇处。"},{"senses":"08","en":"METAPHOR: size and uniformity are lent to a crowd or a mood.","cn":"比喻：体量与均匀性被借给人群或情绪。"}]},"affixes":{"intro":{"en":"Air mass is a two-word technical compound, one Greek-derived word plus one Latin-derived word; its grammar is that of a noun phrase.","cn":"air mass 是双词技术复合语，由一个希腊来源词与一个拉丁来源词构成；其语法是名词短语。"},"latinIntro":{"en":"Latin aer supplies air and Latin massa supplies mass; both are learned borrowings, not native roots.","cn":"拉丁 aer 提供 air，拉丁 massa 提供 mass；两者都是学术借词，而非本族词根。"},"items":[{"word":"air","structure":"air (noun from Latin aer, Greek aēr)","meaning":"the atmosphere; moving air","meaningCN":"大气；流动的空气","example":"The air above the ice stayed dry.","exampleCN":"冰面上方的空气保持干燥。"},{"word":"mass","structure":"mass (noun from Latin massa, Greek maza)","meaning":"a lump; a large body","meaningCN":"团块；一大体","example":"A mass of cold air settled over the plain.","exampleCN":"一大团冷空气停在平原上空。"},{"word":"air-","structure":"air (combining first element)","meaning":"of the atmosphere","meaningCN":"大气的","example":"Air-mass boundaries show on the chart.","exampleCN":"气团边界显示在天气图上。"},{"word":"polar","structure":"polar (adjective, 'of the pole')","meaning":"formed at high latitude","meaningCN":"在高纬形成的","example":"Polar air masses are cold and dry.","exampleCN":"极地气团又冷又干。"},{"word":"tropical","structure":"tropical (adjective, 'of the tropics')","meaning":"formed at low latitude","meaningCN":"在低纬形成的","example":"Tropical air masses carry much moisture.","exampleCN":"热带气团携带大量水汽。"},{"word":"continental","structure":"continent + -al (adjective)","meaning":"formed over land","meaningCN":"在陆地上形成的","example":"Continental air masses are dry.","exampleCN":"大陆气团较为干燥。"},{"word":"maritime","structure":"maritime (adjective from Latin maritimus)","meaning":"formed over the sea","meaningCN":"在海上形成的","example":"Maritime air masses are humid.","exampleCN":"海洋气团较为湿润。"},{"word":"-source","structure":"source (combining noun)","meaning":"the region of origin","meaningCN":"起源区域","example":"The air-mass source lay over the steppe.","exampleCN":"气团源地在大草原上。"},{"word":"-modification","structure":"-modification (technical combining noun)","meaning":"the change undergone in transit","meaningCN":"移动途中经历的变化","example":"Air-mass modification warms the lower layer.","exampleCN":"气团变性使低层变暖。"}],"latinEntries":[{"word":"aer","structure":"aer, aeris (m., third declension)","meaning":"air, the lower atmosphere","meaningCN":"空气；低层大气"},{"word":"massa","structure":"massa, -ae (f., first declension)","meaning":"a lump, a mass","meaningCN":"团块；一堆"},{"word":"maritimus","structure":"maritimus, -a, -um (adjective)","meaning":"of the sea, maritime","meaningCN":"海的；沿海的"}]}},{"word":"front","ipa_uk":"/frʌnt/","ipa_us":"/frʌnt/","definition_zh":"锋面；前线；正面；前部；表象；阵线；掩护；面向","definition_en":"the forward part or face of something, a line of conflict, a public appearance, or the boundary between two air masses","core_image":"两种颜色的空气沿一道斜面相遇，暖的爬上去，冷的钻到底，交界处云带陡立","scene":"夜里有条界线悄悄扫过海岸，天亮时风向已经换了。A weak front passed the coast overnight without bringing rain.","sceneCN":"这里指「两个气团之间的倾斜交界」（第 1 个义项：冷暖气团相接的锋面）；句意为一条弱锋面夜里扫过海岸，却没有带来降雨。图中可辨识物件：倾斜的交界面、贴着海面的云带、转向的风向标、未落雨的码头。","pos":[{"tag":"n.","zh":"锋面；前线；正面；前部；表象；阵线"},{"tag":"v.","zh":"面向；朝向；作掩护"},{"tag":"adj.","zh":"前面的；正面的"}],"collocations":[{"phrase":"a cold front","zh":"冷锋"},{"phrase":"a warm front","zh":"暖锋"},{"phrase":"the front line","zh":"前线"},{"phrase":"put on a front","zh":"装出样子；强作镇定"},{"phrase":"a united front","zh":"联合阵线"},{"phrase":"on several fronts","zh":"在几条战线上；在多个方面"},{"phrase":"a front company","zh":"挂名公司；掩护公司"}],"forms":[{"label":"复数","form":"fronts"},{"label":"三单（第三人称单数）","form":"fronts"},{"label":"过去式","form":"fronted"},{"label":"过去分词","form":"fronted"},{"label":"现在分词","form":"fronting"},{"label":"形容词（锋面的；正面的）","form":"frontal"}],"derivatives":[{"word":"frontal","pos":"adj.","zh":"锋面的；正面的"},{"word":"frontage","pos":"n.","zh":"临街面；正面宽度"},{"word":"frontier","pos":"n.","zh":"边境；前沿"},{"word":"frontline","pos":"n./adj.","zh":"前线；一线的"},{"word":"frontward","pos":"adj./adv.","zh":"向前的"}],"senses":[{"no":"01","title":"The boundary between two air masses","titleCN":"两个气团之间的锋面","definition":"the sloping interface where two air masses of different temperature and density meet","definitionCN":"温度与密度不同的两个气团相接的倾斜界面","example":"A weak front passed the coast overnight without bringing rain.","exampleCN":"一条弱锋面夜里扫过海岸，却没有带来降雨。","why":"The weather sense borrows the military image: two bodies of air meet as two armies do, along a line.","whyCN":"气象义借用了军事意象：两团空气像两支军队一样，沿一条线相遇。"},{"no":"02","title":"The forward line in a conflict","titleCN":"冲突中的前线","definition":"the line or area where opposing armed forces are in contact","definitionCN":"敌对武装力量发生接触的战线或区域","example":"Supplies reached the front only after dark.","exampleCN":"补给在天黑之后才送抵前线。","why":"This is the oldest modern sense: the place where an army faces its opponent.","whyCN":"这是该词最早的现代义：军队面对对手的地方。"},{"no":"03","title":"The forward face of an object","titleCN":"物体的正面或前部","definition":"the part of a building, vehicle or body that faces forward","definitionCN":"建筑、车辆或身体朝前的一面","example":"The front of the house faces the square.","exampleCN":"房子的正面朝向广场。","why":"The word began as the forehead, so 'the face you present' is the original image.","whyCN":"这个词最初指额头，因此「你呈现出的那一面」就是它本来的意象。"},{"no":"04","title":"A public appearance put on","titleCN":"刻意做出给人看的样子","definition":"a manner or appearance adopted to hide one's real feelings or situation","definitionCN":"为掩盖真实情感或处境而采取的举止或外表","example":"He put on a brave front for the family.","exampleCN":"他在家人面前强作镇定。","why":"A face can be managed like a shop window, which is why the word means a display.","whyCN":"脸可以像橱窗一样被布置，因此这个词有了「展示」的意思。"},{"no":"05","title":"A united political line","titleCN":"联合阵线","definition":"a coalition of groups acting together on a shared issue","definitionCN":"就共同议题一致行动的团体联盟","example":"The parties formed a united front against the bill.","exampleCN":"各党结成联合阵线反对该法案。","why":"Politics borrowed the battle line and turned it into an alliance.","whyCN":"政治借用了战线，把它变成了一种联盟。"},{"no":"06","title":"One area of activity among several","titleCN":"若干方面中的一个","definition":"a particular area in which effort, progress or attack is being made","definitionCN":"投入努力、取得进展或发起攻势的某个特定领域","example":"The charity works on several fronts at once.","exampleCN":"该慈善机构同时在多个方面开展工作。","why":"If a struggle has a line, it can have several lines, and each becomes a 'front'.","whyCN":"如果一场斗争有一条线，就可以有多条线，每条都成为一个「方面」。"},{"no":"07","title":"A cover organisation","titleCN":"挂名掩护机构","definition":"a business or group that hides the real activity behind it","definitionCN":"在背后隐藏真实活动的商号或团体","example":"The warehouse was a front for the smuggling ring.","exampleCN":"那家仓库是走私团伙的掩护。","why":"A front is what is shown; here the shown surface is deliberately false.","whyCN":"该词本指被展示的一面；此处被展示的表面是故意虚假的。"},{"no":"08","title":"To face toward something","titleCN":"面向某物","definition":"to have the front directed toward a place, as a building does","definitionCN":"正面朝向某处，如建筑物那样","example":"The hotel fronts the harbour and the market.","exampleCN":"这家酒店正面朝向港口与市场。","why":"The verb simply applies the noun's 'forward face' as a direction.","whyCN":"该词本指被展示的一面；此处被展示的表面是故意虚假的。"}],"etymology":{"intro":{"en":"Front comes from Latin frons, frontis 'forehead, brow, front', through Old French front. The meteorological sense was added by the Norwegian school of forecasting in the early twentieth century.","cn":"front 经古法语 front 来自拉丁 frons, frontis「额头、眉、正面」。气象义由挪威预报学派在 20 世纪初加入。"},"items":[{"era":"LATIN FRONS","en":"Frons meant the forehead and, by extension, the face or the forward side of anything.","cn":"frons 指额头，引申指面部或任何事物的朝前一面。"},{"era":"OLD FRENCH FRONT","en":"Old French front kept the military and architectural senses, and English borrowed it after the Norman period.","cn":"古法语 front 保留了军事与建筑义，英语在诺曼时期之后借入。"},{"era":"MILITARY LINE","en":"By the seventeenth century front meant the line where armies meet, and from there a collective political line.","cn":"到 17 世纪，front 指军队相接的战线，并由此引申为集体政治阵线。"},{"era":"BERGEN SCHOOL","en":"In the 1910s and 1920s Bergen forecasters applied the military word to the boundary of two air masses, because it behaved like a battle line.","cn":"在 20 世纪一十至二十年代，卑尔根预报员把这个军事词用到两个气团的交界上，因为其行为像一条战线。"},{"era":"FRONTAL SYSTEMS","en":"The derived adjective frontal and the compound frontal system followed, fixing the term in synoptic meteorology.","cn":"派生的形容词 frontal 与复合语 frontal system 随之出现，把该术语固定在天气学中。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the earliest citation for the meteorological sense is given differently in different histories; the derivation from frons is not in doubt.","cn":"来源不确定（仅首见年代）：气象义的最早书证在不同史著中记载不一；其出自 frons 的派生关系并无疑义。"}]},"similar":{"note":{"en":"Group one holds words derived from front that differ in meaning; group two holds words for a boundary or a displayed face.","cn":"第一组是由本词派生而含义不同的词；第二组是表示交界或展示面的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"frontal","ipa":"/ˈfrʌntl/","tag":"same root, adjective","definition":"Front plus -al: of a front, as in frontal rain or a frontal lobe; it describes, it does not name the boundary.","definitionCN":"由 front 加 -al：锋面的，如锋面雨或额叶；它作描述，不指交界本身。"},{"word":"frontier","ipa":"/ˈfrʌntɪə/","tag":"same root, different sense","definition":"Front plus -ier: a border between countries or the edge of what is known, not a weather front.","definitionCN":"由 front 加 -ier：国家间的边境或已知领域的边缘，而非天气锋面。"},{"word":"frontage","ipa":"/ˈfrʌntɪdʒ/","tag":"same root, property term","definition":"Front plus -age: the width of a property along a street, a measurement rather than a face.","definitionCN":"由 front 加 -age：产业沿街的正面宽度，是量度而非面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"boundary","ipa":"/ˈbaʊndri/","tag":"general term","definition":"Any line marking a limit; a front is a boundary, but boundary is far broader and not meteorological.","definitionCN":"标记界限的任何线；锋面是一种边界，但 boundary 宽泛得多，且不属气象术语。"},{"word":"facade","ipa":"/fəˈsɑːd/","tag":"displayed face","definition":"The front of a building, and figuratively a deceptive outward appearance; it matches the 'put on a front' sense only.","definitionCN":"建筑的正面，比喻虚假的外表；只对应「装出样子」这一义项。"},{"word":"vanguard","ipa":"/ˈvænɡɑːd/","tag":"foremost part","definition":"The leading part of an army or movement; it names the troops at the front, not the line itself.","definitionCN":"军队或运动的最前部；指位于前方的部队，而非战线本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin frons, the real military line and the real Bergen extension.","cn":"正常联想：真实的拉丁词源、真实的军事战线与真实的卑尔根延伸。"},"normal":[{"en":"Latin frons meant forehead, so a front is the face you turn to the world.","cn":"拉丁 frons 指额头，因此 front 是你转向世界的那张脸。"},{"en":"Armies meet at the front, and so do air masses.","cn":"军队在前线相遇，气团也在锋面相遇。"},{"en":"Fixed phrases split the senses: front line, put on a front, united front.","cn":"固定搭配区分义项：前线、强作镇定、联合阵线。"},{"en":"On several fronts turns one line into several areas of effort.","cn":"「在几条战线」把一条线变成了多个努力领域。"},{"en":"Frontal is the derived adjective used in meteorology.","cn":"frontal 是气象学中使用的派生形容词。"}],"abstract":[{"en":"Picture a face held up like a shield while the person hides behind it.","cn":"想象一张像盾牌一样举起的脸，人藏在后面。"},{"en":"Picture two coloured liquids meeting along a tilted wall.","cn":"想象两种颜色的液体沿一道倾斜的墙相遇。"},{"en":"Picture a shop window that is all display and no shop.","cn":"想象一扇全是陈列、里面却没有店的橱窗。"}]},"examples":[{"en":"The front stalled over the mountains and rain persisted for days.","cn":"锋面在山地上空停滞，降雨持续了数日。"},{"en":"Reporters were kept well behind the front.","cn":"记者被留在前线之后很远的地方。"},{"en":"The charity is fighting on three fronts: housing, food and schooling.","cn":"该慈善机构在住房、食物与教育三条战线上努力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「弗龙特」——两军面对的那条线 → 前线、锋面、正面","word":"front"},"root":"拉丁 frons, frontis「额头、眉、正面」，经古法语 front 进入英语；气象义为 20 世纪初卑尔根学派所加。","sensesIntro":{"en":"Eight senses all turn on a forward face or a meeting line: weather boundary, battle line, building face, displayed manner, political alliance, area of effort, cover business and the verb of facing.","cn":"八个义项都围绕「朝前的一面」或「相接的线」：天气交界、战线、建筑正面、展示的举止、政治联盟、努力领域、掩护生意，以及面向的动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a face turned outward, and the line where that face meets another.","cn":"核心意象：一张朝外的脸，以及这张脸与另一者相接的线。"},"chain":["FOREHEAD","FACE TURNED OUT","FORWARD EDGE","CONTACT LINE","BATTLE LINE","WEATHER BOUNDARY"],"branches":[{"senses":"02","en":"THE LINE OF CONTACT: two armies meet along a front.","cn":"接触之线：两支军队沿一条线相遇。"},{"senses":"03 · 08","en":"FORWARD FACE: the noun names it, the verb turns it toward something.","cn":"朝前之面：名词命名它，动词把它转向某物。"},{"senses":"04 · 07","en":"WHAT IS SHOWN: a manner or a business can be a false surface.","cn":"被展示者：举止或商号都可能是虚假的表面。"},{"senses":"05 · 06","en":"LINES OF EFFORT: one battle line becomes an alliance, then several areas of work.","cn":"努力之线：一条战线变成联盟，再变成多个工作领域。"},{"senses":"01","en":"METEOROLOGY: the Bergen school reused the military image for air.","cn":"气象学：卑尔根学派把军事意象重新用于空气。"}]},"affixes":{"intro":{"en":"Front is a Latin noun that became an English word family through French; its suffixes are Latin-derived but its compounds are English.","cn":"front 是经法语进入英语的拉丁名词，其词族后缀源自拉丁，而复合词为英语构成。"},"latinIntro":{"en":"Latin frons, frontis is the source; frontal and frontage add Latin-derived suffixes to it.","cn":"拉丁 frons, frontis 是来源；frontal 与 frontage 在其上添加拉丁来源后缀。"},"items":[{"word":"front","structure":"front (noun from Latin frons, frontis)","meaning":"forehead; forward face; contact line","meaningCN":"额头；朝前的一面；接触线","example":"The front of the building was rebuilt.","exampleCN":"建筑的正面被重建了。"},{"word":"-al","structure":"-al (adjective suffix from Latin -alis)","meaning":"of or relating to","meaningCN":"……的；与……有关的","example":"Frontal cloud rose along the slope.","exampleCN":"锋面云沿斜面升起。"},{"word":"-age","structure":"-age (noun suffix from Latin -aticum)","meaning":"a measure or collective","meaningCN":"量度或集合","example":"The shop has a narrow frontage.","exampleCN":"这家店临街面很窄。"},{"word":"-ier","structure":"-ier (noun suffix, via French)","meaning":"the edge or border","meaningCN":"边缘或边境","example":"The frontier moved west.","exampleCN":"边境向西移动。"},{"word":"-line","structure":"-line (combining noun)","meaning":"the forward line","meaningCN":"前方的线","example":"Frontline units lacked fuel.","exampleCN":"一线部队缺油。"},{"word":"-ward","structure":"-ward (direction suffix)","meaning":"toward the front","meaningCN":"朝前方","example":"The seats face frontward.","exampleCN":"座位朝向前方。"},{"word":"cold front","structure":"cold + front (compound noun)","meaning":"a front led by cold air","meaningCN":"由冷空气主导推进的锋","example":"The cold front crossed at dawn.","exampleCN":"冷锋在黎明时过境。"},{"word":"warm front","structure":"warm + front (compound noun)","meaning":"a front led by warm air","meaningCN":"由暖空气主导推进的锋","example":"The warm front brought drizzle.","exampleCN":"暖锋带来了细雨。"},{"word":"front-runner","structure":"front + runner (compound noun)","meaning":"the leading competitor","meaningCN":"领先的竞争者","example":"She became the front-runner overnight.","exampleCN":"她一夜之间成了领跑者。"}],"latinEntries":[{"word":"frons","structure":"frons, frontis (f., third declension)","meaning":"forehead, brow, front","meaningCN":"额头；眉；正面"},{"word":"frontalis","structure":"frontalis, -e (adjective, third declension)","meaning":"of the forehead or front","meaningCN":"额部的；正面的"},{"word":"frontispicium","structure":"frontispicium, -i (n., second declension)","meaning":"a facade, a front view","meaningCN":"建筑正面；正面视图"}]}},{"word":"cold front","ipa_uk":"/ˈkəʊld frʌnt/","ipa_us":"/ˈkoʊld frʌnt/","definition_zh":"冷锋；冷锋过境；冷锋云带；冷锋后的降温","definition_en":"the leading edge of a cold air mass advancing into warmer air, marked by squalls and a sharp temperature drop","core_image":"一堵冷空气的陡坡把暖空气顶上去，锋后天空转晴，气温骤然下降","scene":"午后西边的云墙压来，气温在一个小时里掉了好几摄氏度。The cold front brought squalls and a sharp drop in temperature.","sceneCN":"这里指「冷气团向暖气团推进的交界面及其过境」（第 1 个义项：冷空气前沿的锋面）；句意为冷锋带来狂风阵雨，并伴随气温骤降。图中可辨识物件：压来的云墙、被顶升的暖空气、转向的风向标、骤降的温度计。","pos":[{"tag":"n.","zh":"冷锋；冷锋过境；冷锋云带"}],"collocations":[{"phrase":"a cold front passage","zh":"冷锋过境"},{"phrase":"the cold front moved east","zh":"冷锋东移"},{"phrase":"pre-frontal squalls","zh":"锋前飑"},{"phrase":"behind the cold front","zh":"冷锋之后"},{"phrase":"a strong cold front","zh":"强冷锋"},{"phrase":"cold-frontal cloud","zh":"冷锋云"}],"forms":[{"label":"复数","form":"cold fronts"},{"label":"冷锋过境（复合）","form":"cold front passage"},{"label":"冷锋的（形容词）","form":"cold-frontal"},{"label":"锋后的（形容词）","form":"post-frontal"},{"label":"锋前的（形容词）","form":"pre-frontal"}],"derivatives":[{"word":"cold-frontal","pos":"adj.","zh":"冷锋的"},{"word":"post-frontal","pos":"adj.","zh":"锋后的"},{"word":"pre-frontal","pos":"adj.","zh":"锋前的"},{"word":"cold front passage","pos":"n.","zh":"冷锋过境"},{"word":"cold-front thunderstorm","pos":"n.","zh":"冷锋雷暴"}],"senses":[{"no":"01","title":"The advancing edge of cold air","titleCN":"冷空气推进的前沿","definition":"the boundary along which a colder air mass pushes under and lifts a warmer one","definitionCN":"较冷气团从下方楔入并抬升较暖气团的交界面","example":"The cold front brought squalls and a sharp drop in temperature.","exampleCN":"冷锋带来狂风阵雨，并伴随气温骤降。","why":"Cold air is denser, so it moves like a wedge under the warmer air rather than riding over it.","whyCN":"冷空气密度更大，因此像楔子一样钻到暖空气下方，而非爬到它上面。"},{"no":"02","title":"The weather of its passage","titleCN":"冷锋过境时的天气","definition":"the sequence of squalls, heavy showers, wind shift and falling temperature as the front passes","definitionCN":"锋面经过时出现的飑、强阵雨、风向转变与降温序列","example":"During the cold front passage the wind veered and the rain turned torrential.","exampleCN":"冷锋过境时风向顺转，雨势变得猛烈。","why":"The passage is an event with a beginning and an end, so the phrase names the whole sequence.","whyCN":"过境是有始有终的事件，因此这个短语命名整个序列。"},{"no":"03","title":"A steep and fast-moving surface","titleCN":"陡峭而移动较快的锋面","definition":"the relatively steep slope and rapid advance that distinguish a cold front from a warm front","definitionCN":"使冷锋区别于暖锋的较陡坡度与较快推进速度","example":"Its steep slope squeezed the rain into a narrow band.","exampleCN":"其陡峭的坡度把降雨压缩成一条窄带。","why":"Friction slows cold air near the ground, but the wedge still advances faster than a warm front.","whyCN":"摩擦使近地面的冷空气减速，但整个楔体仍比暖锋推进得快。"},{"no":"04","title":"The narrow cloud band along it","titleCN":"沿锋面的狭窄云带","definition":"the line of cumulus and cumulonimbus cloud that marks the front on satellite images","definitionCN":"卫星图像上标示锋面的积云与积雨云线","example":"A cold-frontal cloud band stretched from the coast inland.","exampleCN":"一条冷锋云带从海岸向内陆延伸。","why":"Forced ascent is concentrated in a narrow zone, so the cloud appears as a line rather than a sheet.","whyCN":"被迫抬升集中在狭窄地带，因此云呈线状而非片状。"},{"no":"05","title":"Clear, dry air behind the front","titleCN":"锋后的晴朗干燥空气","definition":"the subsiding, cooler and often clearer air that follows the passage of a cold front","definitionCN":"冷锋过境后下沉、较冷且常更晴朗的空气","example":"Behind the cold front the visibility improved within an hour.","exampleCN":"冷锋之后一小时之内能见度就改善了。","why":"Cold air sinking behind the front dries the lower atmosphere and clears the cloud.","whyCN":"锋后下沉的冷空气使低层大气变干，云也随之消散。"},{"no":"06","title":"The leading edge of a cold outbreak","titleCN":"寒潮爆发的先导锋","definition":"the front that marks the arrival of a large cold-air outbreak, often with gales and snow","definitionCN":"标示大规模冷空气爆发到达的锋面，常伴大风与降雪","example":"The cold front preceded three days of hard frost.","exampleCN":"冷锋之后是连续三天的严霜。","why":"A strong front is simply the visible edge of a much larger cold advance.","whyCN":"强锋面不过是一次更大规模冷空气推进的可见边缘。"},{"no":"07","title":"The triangular symbol on a chart","titleCN":"天气图上的三角形符号","definition":"the line of filled triangles drawn on a synoptic chart to show the direction of advance of cold air","definitionCN":"天气图上用实心三角形标示冷空气推进方向的线","example":"On the chart, the cold front ran south-west with its triangles pointing east.","exampleCN":"图上冷锋向西南延伸，三角形朝东指。","why":"The symbol encodes what the words say: the triangles point the way the cold air is going.","whyCN":"符号把文字所说的内容编码：三角形指向冷空气推进的方向。"},{"no":"08","title":"An abrupt cooling in a relationship","titleCN":"比喻关系骤然降温","definition":"a sudden, sharp change to a colder or more distant mood between people or groups","definitionCN":"人与人、群体与群体之间骤然转向冷淡或疏远的变化","example":"The verdict acted as a cold front between the two ministries.","exampleCN":"这一裁决成了两个部门之间的冷锋。","why":"The metaphor keeps only the sudden drop and the line of separation.","whyCN":"这一比喻只保留骤降与分隔之线两层意思。"}],"etymology":{"intro":{"en":"Cold front joins the native adjective cold, from Old English cald, with front, from Latin frons 'forehead, front'. Meteorology coined the phrase in the early twentieth century for the advancing edge of cold air.","cn":"cold front 由本族形容词 cold（古英语 cald）与 front（拉丁 frons「额头、正面」）组合。气象学在 20 世纪初用这个短语指冷空气推进的前沿。"},"items":[{"era":"OLD ENGLISH CALD","en":"Cald is the native word for low temperature, cognate with German kalt and Dutch koud.","cn":"cald 是表示低温的本族词，与德语 kalt、荷兰语 koud 同源。"},{"era":"LATIN FRONS","en":"Front came through French from Latin frons, frontis, meaning the forehead and then any forward face or line.","cn":"front 经法语来自拉丁 frons, frontis，指额头，进而指任何朝前的一面或线。"},{"era":"BERGEN SCHOOL","en":"The Norwegian forecasters of the 1910s and 1920s separated cold fronts from warm fronts and drew them with triangles and semicircles.","cn":"20 世纪一十至二十年代的挪威预报员把冷锋与暖锋分开，并用三角形与半圆标绘。"},{"era":"AIR-MASS THEORY","en":"The phrase only makes sense within air-mass theory: a front is the edge of a body of cold air.","cn":"这个短语只有放在气团理论中才成立：锋面是一团冷空气的边缘。"},{"era":"AVIATION AND WARNING SERVICES","en":"Twentieth-century aviation and warning services fixed the compound in routine forecasts.","cn":"20 世纪的航空与警报服务把这个复合词固定在日常预报中。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the first printed use of the exact phrase is dated differently in different sources; its formation and meaning are settled.","cn":"来源不确定（仅首见年代）：该确切短语最早的书证在不同文献中年代不一；其构成与含义已经确定。"}]},"similar":{"note":{"en":"Group one holds the sibling front types and the base word; group two holds names for the cold air itself and its outbreak.","cn":"第一组是同类锋型与原词；第二组是冷空气本身及其爆发的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"front","ipa":"/frʌnt/","tag":"base word","definition":"The general boundary between air masses; it does not say which body is advancing.","definitionCN":"气团间的一般交界；不说明哪一团在推进。"},{"word":"warm front","ipa":"/ˈwɔːm frʌnt/","tag":"opposite type","definition":"The leading edge of warm air riding over cold air, with gentle slope and steady rain.","definitionCN":"暖空气爬到冷空气之上的前沿，坡度平缓、降雨持续。"},{"word":"occluded front","ipa":"/əˈkluːdɪd frʌnt/","tag":"later stage","definition":"The boundary left when a cold front catches a warm front and lifts it clear of the ground.","definitionCN":"冷锋追上暖锋并把暖空气完全抬离地面后留下的交界。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cold wave","ipa":"/kəʊld weɪv/","tag":"temperature event","definition":"A period of unusually low temperature over a region; it is the consequence, not the boundary.","definitionCN":"某地区一段异常低温时期；它是后果，而非交界。"},{"word":"cold-air outbreak","ipa":"/kəʊld eə ˈaʊtbreɪk/","tag":"the moving body","definition":"A rapid spread of cold continental air over a warmer surface; the front is its leading edge.","definitionCN":"冷大陆空气迅速铺展到较暖表面；冷锋是其前沿。"},{"word":"norther","ipa":"/ˈnɔːðə/","tag":"regional wind","definition":"A strong cold north wind in the Gulf of Mexico region, usually following a cold front.","definitionCN":"墨西哥湾地区强劲的冷北风，通常出现在冷锋之后。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real native cold, the real Latin front and the real Bergen symbols.","cn":"正常联想：真实的本族「冷」、真实的拉丁「正面」与真实的卑尔根符号。"},"normal":[{"en":"Cold is native, front is Latin: the phrase is a hybrid, like the science that coined it.","cn":"cold 是本族词，front 是拉丁词：这个短语是混合体，正如造出它的学科。"},{"en":"Cold air is denser, so it wedges under warm air.","cn":"冷空气密度更大，因此楔入暖空气下方。"},{"en":"Behind the front: clearing, drying and cooling.","cn":"锋后：转晴、变干、降温。"},{"en":"On a chart, triangles point the way the cold air moves.","cn":"天气图上，三角形指向冷空气移动的方向。"},{"en":"The passage is an event: squall, wind shift, temperature drop.","cn":"过境是一个事件：飑、风向转变、气温下降。"}],"abstract":[{"en":"Picture a wedge driving under a soft layer and lifting it off the ground.","cn":"想象一个楔子钻到柔软层下面，把它整体抬离地面。"},{"en":"Picture a line drawn across a map with little teeth pointing one way.","cn":"想象地图上画的一条线，小齿朝一个方向。"},{"en":"Picture a conversation that turns cold in a single hour.","cn":"想象一场对话在一个小时里转冷。"}]},"examples":[{"en":"The cold front reached the airport before the storm cells did.","cn":"冷锋在雷暴单体之前抵达机场。"},{"en":"Pressure rose sharply behind the cold front.","cn":"冷锋之后气压急剧上升。"},{"en":"Sailors welcome a cold front in summer and dread it in winter.","cn":"水手夏天欢迎冷锋，冬天却怕它。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「cold（冷）+ front（前沿）」——冷空气推进的前沿 → 冷锋","word":"cold front"},"root":"cold 为古英语 cald「低温」，与德语 kalt、荷兰语 koud 同源；front 经法语出自拉丁 frons, frontis「额头、正面」。短语为 20 世纪初气象学术语。","sensesIntro":{"en":"Eight senses move from the advancing edge to the weather of its passage, its steep slope, its cloud line, the clear air behind, a cold outbreak, the chart symbol and finally an abrupt chill between people.","cn":"八个义项从推进的前沿，走到过境天气、陡峭坡度、云线、锋后晴空、寒潮爆发、天气图符号，最后是人与人之间的骤然冷淡。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wedge of dense air driving under a softer layer and lifting it clear.","cn":"核心意象：一个密实空气的楔子钻到柔软层下面，把它抬离地面。"},"chain":["COLD AIR ADVANCES","WARM AIR LIFTED","SQUALL LINE","WIND SHIFT","TEMPERATURE FALLS","SKIES CLEAR"],"branches":[{"senses":"01 · 03","en":"THE WEDGE: density difference sets both the boundary and its steep slope.","cn":"楔体：密度差同时决定交界与陡坡。"},{"senses":"02 · 04","en":"PASSAGE: the concentrated lift produces a squall and a narrow cloud line.","cn":"过境：集中抬升产生飑与狭窄云线。"},{"senses":"05 · 06","en":"AFTERMATH: subsiding cold air clears the sky; a large advance becomes a cold wave.","cn":"后果：下沉冷空气使天转晴；大规模推进成为寒潮。"},{"senses":"07","en":"SYMBOL: triangles encode the direction of advance.","cn":"符号：三角形编码推进方向。"},{"senses":"08","en":"METAPHOR: only the sudden drop and the separating line remain.","cn":"比喻：只剩骤降与分隔线。"}]},"affixes":{"intro":{"en":"Cold front is an English noun phrase made of a native adjective and a Latin-derived noun; its technical family is built with prefixes and compounds.","cn":"cold front 是由本族形容词与拉丁来源名词构成的英语名词短语；其技术词族由前缀与复合成分构成。"},"latinIntro":{"en":"Latin frons, frontis gives front; Latin gelidus and frigus name cold, though English cold itself is native.","cn":"拉丁 frons, frontis 给出 front；拉丁 gelidus 与 frigus 表示冷，但英语 cold 本身是本族词。"},"items":[{"word":"cold","structure":"cold (Old English cald, adjective)","meaning":"of low temperature","meaningCN":"低温的","example":"Cold air sank behind the front.","exampleCN":"冷空气在锋后下沉。"},{"word":"front","structure":"front (noun from Latin frons)","meaning":"forward edge; boundary","meaningCN":"前缘；交界","example":"The front crossed the valley.","exampleCN":"锋面越过山谷。"},{"word":"pre-","structure":"pre- (Latin prefix, 'before')","meaning":"before the front","meaningCN":"在锋面之前","example":"Pre-frontal squalls hit the coast.","exampleCN":"锋前飑袭击了海岸。"},{"word":"post-","structure":"post- (Latin prefix, 'after')","meaning":"after the front","meaningCN":"在锋面之后","example":"Post-frontal air was dry and clear.","exampleCN":"锋后空气干燥晴朗。"},{"word":"-al","structure":"-al (adjective suffix)","meaning":"of the front","meaningCN":"锋面的","example":"Cold-frontal cloud formed a narrow band.","exampleCN":"冷锋云形成一条窄带。"},{"word":"-passage","structure":"-passage (combining noun)","meaning":"the event of crossing","meaningCN":"过境事件","example":"The passage lasted under an hour.","exampleCN":"过境持续不到一小时。"},{"word":"-thunderstorm","structure":"-thunderstorm (combining noun)","meaning":"a storm triggered at the front","meaningCN":"在锋面触发的雷暴","example":"A cold-front thunderstorm closed the road.","exampleCN":"一场冷锋雷暴封闭了道路。"},{"word":"-outbreak","structure":"-outbreak (combining noun)","meaning":"a sudden large advance of cold air","meaningCN":"冷空气的突然大规模推进","example":"The cold-air outbreak reached the gulf.","exampleCN":"冷空气爆发抵达海湾。"},{"word":"-wave","structure":"-wave (combining noun)","meaning":"a spell of low temperature","meaningCN":"一段低温期","example":"A cold wave followed the front.","exampleCN":"冷锋之后来了一次寒潮。"}],"latinEntries":[{"word":"frons","structure":"frons, frontis (f., third declension)","meaning":"forehead, front","meaningCN":"额头；正面"},{"word":"gelidus","structure":"gelidus, -a, -um (adjective)","meaning":"icy cold, freezing","meaningCN":"冰冷的；严寒的"},{"word":"frigus","structure":"frigus, frigoris (n., third declension)","meaning":"cold, coldness","meaningCN":"寒冷；冷"}]}},{"word":"warm front","ipa_uk":"/ˈwɔːm frʌnt/","ipa_us":"/ˈwɔːrm frʌnt/","definition_zh":"暖锋；暖锋过境；暖锋云系；缓慢升温","definition_en":"the leading edge of a warm air mass riding up over colder air, marked by layered cloud and steady rain","core_image":"暖空气沿一道缓坡爬上冷空气，云层像层层台阶铺开，细雨连绵不断","scene":"南来的暖湿空气缓缓爬上来，雨丝连着下了两天。The warm front brought two days of steady drizzle.","sceneCN":"这里指「暖气团爬升到冷气团之上的前沿」（第 1 个义项：暖空气主导推进的锋面）；句意为暖锋带来了连续两天的细雨。图中可辨识物件：缓坡状的交界面、层层铺开的云、持续的雨丝、上升的温度计。","pos":[{"tag":"n.","zh":"暖锋；暖锋过境；暖锋云系"}],"collocations":[{"phrase":"a warm front passage","zh":"暖锋过境"},{"phrase":"the warm front lifted over the cold air","zh":"暖锋沿冷空气爬升"},{"phrase":"pre-frontal drizzle","zh":"锋前细雨"},{"phrase":"the warm sector","zh":"暖区"},{"phrase":"a shallow warm front","zh":"坡度平缓的暖锋"},{"phrase":"warm-frontal cloud","zh":"暖锋云"}],"forms":[{"label":"复数","form":"warm fronts"},{"label":"暖锋过境（复合）","form":"warm front passage"},{"label":"暖锋的（形容词）","form":"warm-frontal"},{"label":"锋后的（形容词）","form":"post-frontal"},{"label":"锋前的（形容词）","form":"pre-frontal"}],"derivatives":[{"word":"warm-frontal","pos":"adj.","zh":"暖锋的"},{"word":"warm front passage","pos":"n.","zh":"暖锋过境"},{"word":"warm sector","pos":"n.","zh":"暖区"},{"word":"pre-frontal","pos":"adj.","zh":"锋前的"},{"word":"post-frontal","pos":"adj.","zh":"锋后的"}],"senses":[{"no":"01","title":"The leading edge of advancing warm air","titleCN":"暖气团推进的前沿","definition":"the boundary along which a warmer air mass rides up over a colder one","definitionCN":"较暖气团爬到较冷气团之上的交界面","example":"The warm front brought two days of steady drizzle.","exampleCN":"暖锋带来了连续两天的细雨。","why":"Warm air is less dense, so it climbs the cold air instead of burrowing under it.","whyCN":"暖空气密度更小，因此顺着冷空气向上爬，而不是钻到它下面。"},{"no":"02","title":"The weather of its passage","titleCN":"暖锋过境时的天气","definition":"the sequence of thickening cloud, steady rain and slowly rising temperature as the front passes","definitionCN":"锋面经过时云层加厚、降雨持续、气温缓慢上升的序列","example":"During the warm front passage the rain never quite stopped.","exampleCN":"暖锋过境期间，雨几乎没有停过。","why":"Because the ascent is gentle and widespread, rain is steady rather than showery.","whyCN":"由于抬升平缓而范围广，降雨是持续的而非阵性的。"},{"no":"03","title":"The layered sequence of cloud","titleCN":"层状排列的云序列","definition":"the ordered cloud types from high cirrus through altostratus to low nimbostratus ahead of the front","definitionCN":"锋前由高云向下依次出现的卷云、高层云与雨层云序列","example":"Cirrus first, then altostratus: the warm front announced itself hours ahead.","exampleCN":"先是卷云，再是高层云：暖锋提前数小时就自我宣告了。","why":"A shallow slope means the cloud is spread over hundreds of kilometres, so the sequence arrives as a timetable.","whyCN":"坡度平缓意味着云铺展在数百公里上，因此云的序列像时刻表一样依次到达。"},{"no":"04","title":"A gentle slope and a wide rain shield","titleCN":"平缓坡度与宽广雨区","definition":"the shallow incline and broad precipitation area that distinguish a warm front from a cold front","definitionCN":"使暖锋区别于冷锋的平缓坡度与宽阔降水区","example":"Its gentle slope spread the rain across three provinces.","exampleCN":"其平缓坡度把降雨铺展到三个省。","why":"The same volume of lifted air is spread over a much longer distance, so rain is lighter but wider.","whyCN":"同样体积的抬升空气被摊在更长的距离上，因此雨更轻但范围更广。"},{"no":"05","title":"The semicircle symbol on a chart","titleCN":"天气图上的半圆符号","definition":"the line of filled semicircles on a synoptic chart showing the direction warm air is advancing","definitionCN":"天气图上用实心半圆标示暖空气推进方向的线","example":"The map drew the warm front with semicircles pointing north.","exampleCN":"地图用朝北的半圆画出暖锋。","why":"The semicircles mark the side toward which the warm air is moving.","whyCN":"半圆标出暖空气正在前往的那一侧。"},{"no":"06","title":"Freezing rain above a cold layer","titleCN":"冷层之上的冻雨","definition":"the condition in which rain falling from a warm layer aloft freezes on contact with cold air or ground below","definitionCN":"高空暖层落下的雨在接触下方冷空气或地面时冻结的情形","example":"A warm front aloft produced freezing rain across the valley.","exampleCN":"高空的暖锋在整个山谷造成冻雨。","why":"Warm air can sit above cold air, so the front's rain passes through a freezing layer before landing.","whyCN":"暖空气可以停在冷空气之上，因此锋面的雨在落地前要穿过一层冰点以下空气。"},{"no":"07","title":"The warm sector ahead of it","titleCN":"锋前的暖区","definition":"the wedge of warm air between a warm front and the cold front behind it","definitionCN":"暖锋与其后冷锋之间那块暖空气楔形区","example":"The warm sector stayed humid and hazy for a day.","exampleCN":"暖区潮湿而朦胧，持续了一天。","why":"In a mid-latitude cyclone the warm air occupies a sector, and that sector has its own weather.","whyCN":"在中纬度气旋中，暖空气占据一个扇形区域，该区域有自己的天气。"},{"no":"08","title":"A gradual, mild change, figuratively","titleCN":"比喻温和渐进的转变","definition":"a slow, gentle change toward a warmer or friendlier state","definitionCN":"朝更温暖或更友好状态缓慢温和的变化","example":"The treaty worked like a warm front on relations between the towns.","exampleCN":"这份条约对两镇关系的作用像一道暖锋。","why":"The metaphor keeps the gentleness and the gradual warming, not the rain.","whyCN":"这一比喻保留温和与渐暖，而不保留降雨。"}],"etymology":{"intro":{"en":"Warm front joins the native adjective warm, from Old English wearm, with front, from Latin frons 'forehead, front'. Meteorology coined the phrase in the early twentieth century for the front led by advancing warm air.","cn":"warm front 由本族形容词 warm（古英语 wearm）与 front（拉丁 frons「额头、正面」）组合。气象学在 20 世纪初用这个短语指由暖空气主导推进的锋。"},"items":[{"era":"OLD ENGLISH WEARM","en":"Wearm is the native word for moderately hot, cognate with German warm and Dutch warm.","cn":"wearm 是表示温暖的本族词，与德语 warm、荷兰语 warm 同源。"},{"era":"LATIN FRONS","en":"Front came through French from Latin frons, frontis, naming the forehead and then any forward face or boundary.","cn":"front 经法语来自拉丁 frons, frontis，指额头，进而指任何朝前的一面或交界。"},{"era":"BERGEN SCHOOL","en":"Bergen forecasters of the 1910s and 1920s paired warm fronts with cold fronts and gave each its own symbol.","cn":"20 世纪一十至二十年代的卑尔根预报员把暖锋与冷锋配对，并各给一个符号。"},{"era":"WARM-SECTOR MODEL","en":"The Norwegian cyclone model placed the warm sector between the two fronts, explaining its humid weather.","cn":"挪威气旋模型把暖区置于两条锋之间，从而解释了暖区潮湿的天气。"},{"era":"AVIATION AND WARNINGS","en":"Twentieth-century aviation forecasts fixed the phrase in routine use, especially for icing and low cloud.","cn":"20 世纪的航空预报把这个短语固定于日常使用，尤其用于结冰与低云。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the first printed use is dated differently across histories; the formation of the phrase is not in doubt.","cn":"来源不确定（仅首见年代）：最早书证在不同史著中年代不一；短语的构成并无疑义。"}]},"similar":{"note":{"en":"Group one holds the sibling front types and the base word; group two holds words for mild air and for the warm wedge itself.","cn":"第一组是同类锋型与原词；第二组是表示温和空气与暖空气楔的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"front","ipa":"/frʌnt/","tag":"base word","definition":"The general boundary between air masses, without saying which body advances.","definitionCN":"气团间的一般交界，不说明哪一团在推进。"},{"word":"cold front","ipa":"/ˈkəʊld frʌnt/","tag":"opposite type","definition":"The steep edge of cold air wedging under warm air, with squalls and a sharp drop.","definitionCN":"冷空气楔入暖空气下方的陡峭边缘，伴飑与骤降。"},{"word":"stationary front","ipa":"/ˈsteɪʃənri frʌnt/","tag":"not advancing","definition":"A front that has stopped moving, so rain can persist over one district for days.","definitionCN":"停止移动的锋，因此降雨可在同一地区持续数日。"}]},{"heading":"NEAR MEANING","entries":[{"word":"thaw","ipa":"/θɔː/","tag":"warming event","definition":"A period of warmer weather that melts snow and ice; it is the result, not the boundary.","definitionCN":"使冰雪融化的回暖期；是结果，而非交界。"},{"word":"mild spell","ipa":"/maɪld spel/","tag":"temperature period","definition":"A stretch of unusually mild weather in a cold season; it says nothing about fronts.","definitionCN":"冷季中一段异常温和的天气；不涉及锋面。"},{"word":"warm sector","ipa":"/wɔːm ˈsektə/","tag":"the air between fronts","definition":"The wedge of warm air between a warm front and a following cold front.","definitionCN":"暖锋与其后冷锋之间的暖空气楔形区。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real native warm, the real Latin front and the real layered cloud sequence.","cn":"正常联想：真实的本族「暖」、真实的拉丁「正面」与真实的层状云序列。"},"normal":[{"en":"Warm air is lighter, so it climbs; cold air is heavier, so it wedges under.","cn":"暖空气更轻，因此向上爬；冷空气更重，因此向下楔入。"},{"en":"The cloud arrives as a timetable: cirrus, altostratus, nimbostratus.","cn":"云按时刻表到达：卷云、高层云、雨层云。"},{"en":"Gentle slope means light rain over a wide area.","cn":"坡度平缓意味着雨轻而范围广。"},{"en":"On a chart, semicircles point the way the warm air is going.","cn":"天气图上，半圆指向暖空气前进的方向。"},{"en":"The warm sector sits between the warm front and the cold front behind it.","cn":"暖区位于暖锋与其后的冷锋之间。"}],"abstract":[{"en":"Picture a blanket laid gently over a colder floor, warming it slowly.","cn":"想象一条毯子轻轻盖在更冷的地面上，慢慢把它焐热。"},{"en":"Picture rain that arrives as a schedule rather than a shout.","cn":"想象一场像日程表而非喊声那样到来的雨。"},{"en":"Picture a friendship that thaws by one degree a day.","cn":"想象一段友情每天回暖一度。"}]},"examples":[{"en":"Ahead of the warm front the pressure fell steadily for twelve hours.","cn":"暖锋到来前，气压连续十二小时稳定下降。"},{"en":"The warm front lifted over the cold valley air and produced freezing rain.","cn":"暖锋沿冷谷空气爬升，造成了冻雨。"},{"en":"After the warm front passed, the snow line retreated up the slope.","cn":"暖锋过境后，雪线沿山坡上退。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「warm（暖）+ front（前沿）」——暖空气推进的前沿 → 暖锋","word":"warm front"},"root":"warm 为古英语 wearm「温暖」，与德语 warm、荷兰语 warm 同源；front 经法语出自拉丁 frons, frontis「额头、正面」。短语为 20 世纪初气象学术语。","sensesIntro":{"en":"Eight senses move from the advancing warm edge to its steady rain, layered cloud, gentle slope, chart symbol, freezing rain, warm sector and finally a gradual thaw in relations.","cn":"八个义项从暖空气推进的边缘，走到持续降雨、层状云、平缓坡度、天气图符号、冻雨、暖区，最后是关系中渐进的回暖。"},"semanticMap":{"core":{"en":"CORE IMAGE: warm air climbing a long shallow ramp, laying cloud across the sky like steps.","cn":"核心意象：暖空气沿一条长长缓坡向上爬，把云像台阶一样铺满天空。"},"chain":["WARM AIR ARRIVES","SHALLOW RAMP","HIGH CIRRUS","LAYER CLOUD","STEADY RAIN","SLOW WARMING"],"branches":[{"senses":"01 · 04","en":"THE RAMP: density decides the climb, and a shallow slope spreads the weather wide.","cn":"缓坡：密度决定爬升，平缓坡度把天气摊得很宽。"},{"senses":"02 · 03","en":"TIMETABLE: layered cloud and steady rain arrive in a fixed order.","cn":"时刻表：层状云与持续雨按固定顺序到达。"},{"senses":"05","en":"SYMBOL: semicircles mark the direction of the warm advance.","cn":"符号：半圆标记暖空气推进的方向。"},{"senses":"06 · 07","en":"STRUCTURE: warm air can sit aloft over cold air, and the warm sector is its wedge.","cn":"结构：暖空气可以停在冷空气之上，暖区就是它的楔形区。"},{"senses":"08","en":"METAPHOR: gentleness and gradual warming survive; rain does not.","cn":"比喻：温和与渐暖留下，降雨被去掉。"}]},"affixes":{"intro":{"en":"Warm front is an English noun phrase of a native adjective plus a Latin-derived noun; its technical family uses prefixes and compounds.","cn":"warm front 是由本族形容词加拉丁来源名词构成的英语名词短语；其技术词族使用前缀与复合成分。"},"latinIntro":{"en":"Latin frons supplies front; Latin calidus and tepidus name warmth, though English warm itself is native.","cn":"拉丁 frons 提供 front；拉丁 calidus 与 tepidus 表示温暖，但英语 warm 本身是本族词。"},"items":[{"word":"warm","structure":"warm (Old English wearm, adjective)","meaning":"moderately hot","meaningCN":"温暖的","example":"Warm air rose over the cold layer.","exampleCN":"暖空气在冷层之上上升。"},{"word":"front","structure":"front (noun from Latin frons)","meaning":"forward edge; boundary","meaningCN":"前缘；交界","example":"The front reached the coast at dusk.","exampleCN":"锋面在黄昏抵达海岸。"},{"word":"pre-","structure":"pre- (Latin prefix, 'before')","meaning":"before the front","meaningCN":"在锋面之前","example":"Pre-frontal drizzle began at noon.","exampleCN":"锋前细雨在正午开始。"},{"word":"post-","structure":"post- (Latin prefix, 'after')","meaning":"after the front","meaningCN":"在锋面之后","example":"Post-frontal air was warm and damp.","exampleCN":"锋后空气温暖潮湿。"},{"word":"-al","structure":"-al (adjective suffix)","meaning":"of the front","meaningCN":"锋面的","example":"Warm-frontal cloud is layered.","exampleCN":"暖锋云是层状的。"},{"word":"-passage","structure":"-passage (combining noun)","meaning":"the event of crossing","meaningCN":"过境事件","example":"The passage brought two days of rain.","exampleCN":"过境带来两天的雨。"},{"word":"-sector","structure":"-sector (combining noun, 'wedge')","meaning":"the warm air between fronts","meaningCN":"锋间的暖空气","example":"The warm sector stayed hazy.","exampleCN":"暖区保持朦胧。"},{"word":"-semicircle","structure":"-semicircle (symbol name)","meaning":"the chart mark for warm air","meaningCN":"暖空气的图面标记","example":"Semicircles lined the warm front.","exampleCN":"半圆排列在暖锋上。"},{"word":"-outbreak","structure":"-outbreak (combining noun)","meaning":"a sudden arrival of warm air","meaningCN":"暖空气的突然到来","example":"A warm-air outbreak melted the snow.","exampleCN":"暖空气爆发融化了积雪。"}],"latinEntries":[{"word":"frons","structure":"frons, frontis (f., third declension)","meaning":"forehead, front","meaningCN":"额头；正面"},{"word":"calidus","structure":"calidus, -a, -um (adjective)","meaning":"warm, hot","meaningCN":"温暖的；热的"},{"word":"tepidus","structure":"tepidus, -a, -um (adjective)","meaning":"lukewarm","meaningCN":"温的；不冷不热的"}]}},{"word":"cloud","ipa_uk":"/klaʊd/","ipa_us":"/klaʊd/","definition_zh":"云；云朵；云量；阴云；一团烟尘；云端；使模糊","definition_en":"a visible mass of water droplets or ice crystals in the air, or a mass of smoke, dust or data perceived as a similar floating body","core_image":"山谷上升的水汽在半山凝成一片白团，边缘被风梳成丝，遮住半个太阳","scene":"山脊上方只有一团云停着，整个下午没有移动。A single cloud hung above the ridge all afternoon.","sceneCN":"这里指「空中可见的水滴或冰晶集合体」（第 1 个义项：悬浮在空气中的凝结物）；句意为只有一朵云停在山脊上方，整个下午没有移动。图中可辨识物件：半山以上的白团、被风梳出的丝状边缘、被遮住一半的太阳、起伏的山脊。","pos":[{"tag":"n.","zh":"云；云朵；云量；阴云；一团烟尘；云端"},{"tag":"v.","zh":"使模糊；使混乱；使蒙上阴云"}],"collocations":[{"phrase":"a cloud of smoke","zh":"一团烟"},{"phrase":"cloud cover","zh":"云量"},{"phrase":"a cloud on the horizon","zh":"地平线上的阴云；隐患"},{"phrase":"under a cloud","zh":"受怀疑；失宠"},{"phrase":"cloud computing","zh":"云计算"},{"phrase":"every cloud has a silver lining","zh":"黑暗中总有一线光明"}],"forms":[{"label":"复数","form":"clouds"},{"label":"三单（第三人称单数）","form":"clouds"},{"label":"过去式","form":"clouded"},{"label":"过去分词","form":"clouded"},{"label":"现在分词","form":"clouding"},{"label":"形容词（多云的）","form":"cloudy"}],"derivatives":[{"word":"cloudy","pos":"adj.","zh":"多云的；浑浊的；模糊的"},{"word":"cloudless","pos":"adj.","zh":"无云的"},{"word":"cloudiness","pos":"n.","zh":"云量；多云状态"},{"word":"cloudburst","pos":"n.","zh":"骤雨；暴雨"},{"word":"cloudscape","pos":"n.","zh":"云景"}],"senses":[{"no":"01","title":"A visible mass of droplets or crystals","titleCN":"可见的水滴或冰晶集合体","definition":"a visible body of condensed water or ice suspended in the atmosphere","definitionCN":"悬浮在大气中的凝结水或冰的可见集合体","example":"A single cloud hung above the ridge all afternoon.","exampleCN":"只有一朵云停在山脊上方，整个下午没有移动。","why":"The word names what the eye sees, not the humidity that made it.","whyCN":"这个词命名的是眼睛看到的东西，而不是造成它的湿度。"},{"no":"02","title":"One cloud as an object","titleCN":"作为个体的云朵","definition":"a single distinct cloud, countable and shaped, as seen against the sky","definitionCN":"天空中可数、有形状的单独一朵云","example":"Three clouds crossed the moon within an hour.","exampleCN":"一小时之内有三朵云掠过月亮。","why":"Everyday vision treats clouds as objects even though their edges are never fixed.","whyCN":"日常视觉把云当作物体，尽管它们的边缘从不固定。"},{"no":"03","title":"Cloud cover as a measured fraction","titleCN":"作为可测比例的云量","definition":"the fraction of the sky hidden by cloud, measured in eighths or tenths","definitionCN":"天空被云遮蔽的比例，以八分制或十分制度量","example":"Cloud cover reached seven eighths by noon.","exampleCN":"到正午，云量达到八分之七。","why":"Aviation and climate science need a number, so the mass becomes a fraction.","whyCN":"航空与气候科学需要一个数字，于是云块变成了比例。"},{"no":"04","title":"A shadow of trouble or suspicion","titleCN":"隐患或疑云的阴影","definition":"a threat or suspicion that darkens a situation without yet breaking into the open","definitionCN":"使局势阴沉、但尚未公开爆发的威胁或怀疑","example":"A cloud hung over the negotiations from the first day.","exampleCN":"从第一天起，谈判上空就笼着一层阴云。","why":"A cloud hides the sun without stopping the day, which is exactly how a looming threat behaves.","whyCN":"云遮住太阳却不让白昼停止，这正是逼近的威胁的行为方式。"},{"no":"05","title":"A mass of smoke or dust","titleCN":"一团烟或尘","definition":"a dense floating mass of smoke, dust, steam or insects that resembles a cloud","definitionCN":"烟、尘、蒸汽或昆虫形成的、类似云的密集悬浮团","example":"A cloud of dust followed the cart down the road.","exampleCN":"一团尘土跟着马车沿路而去。","why":"The shape and floating behaviour are shared, so the word transfers to anything suspended.","whyCN":"形状与悬浮行为相同，因此这个词转用于任何悬浮之物。"},{"no":"06","title":"Remote computing and storage","titleCN":"云端计算与存储","definition":"networked computing resources accessed over the internet, imagined as a remote floating store","definitionCN":"通过互联网访问的网络计算资源，被想象成远处漂浮的仓库","example":"The archive moved to the cloud and the office emptied.","exampleCN":"档案迁到云端，办公室随之空了。","why":"The metaphor hides the servers the way a cloud hides the sky, which is why the name was chosen.","whyCN":"这个比喻像云遮住天空一样遮住服务器，也正是选择这个名称的原因。"},{"no":"07","title":"To make an issue unclear","titleCN":"使问题变得模糊不清","definition":"to obscure or confuse a matter so that its outline cannot be judged","definitionCN":"把某事弄得晦暗混乱，以致无法判断其轮廓","example":"New statistics clouded the argument instead of settling it.","exampleCN":"新统计没有解决问题，反而使争论更模糊。","why":"The verb turns the noun into an action: cloud spreads until nothing is legible.","whyCN":"动词把名词变成动作：云铺开，直到什么都看不清。"},{"no":"08","title":"To darken with emotion","titleCN":"因情绪而阴沉","definition":"to become dark or gloomy in expression, as a face clouded by anger or worry","definitionCN":"表情变暗或阴沉，如脸因愤怒或忧虑而沉下来","example":"His face clouded when the name was read out.","exampleCN":"念到那个名字时，他的脸沉了下来。","why":"A face behaves like a sky: something passes over it and the light goes out.","whyCN":"脸的行为像天空：有东西掠过，光就暗了。"}],"etymology":{"intro":{"en":"Cloud goes back to Old English clūd, which first meant a mass of rock or a hill, and only in the thirteenth century came to mean a cloud in the sky. The older weather word weolcan was displaced. The deeper origin of clūd is uncertain.","cn":"cloud 可溯至古英语 clūd，最初指岩块或土丘，直到 13 世纪才指天空中的云，原来的天气词 weolcan 被取代。clūd 更深来源不确定。"},"items":[{"era":"OLD ENGLISH CLUD","en":"Clūd meant a mass of rock or a mound; the sense 'cloud' is not recorded before the thirteenth century.","cn":"clūd 指岩块或土丘；「云」这一义项在 13 世纪之前没有记录。"},{"era":"SENSE TRANSFER","en":"The transfer from 'rock mass' to 'cloud' is usually explained by the shared shape of a rounded, solid-looking mass.","cn":"从「岩块」到「云」的转移，通常用「圆整、看似有实体的一团」这一共同形状来解释。"},{"era":"WEOLCAN DISPLACED","en":"Old English had weolcan for a cloud; clūd replaced it in Middle English, and weolcan left no everyday descendant.","cn":"古英语本有 weolcan 指云；中古英语中 clūd 取代了它，weolcan 没有留下日常后代。"},{"era":"RELATED ENGLISH WORDS","en":"The same stock gives clod 'lump of earth' and clot 'lump of coagulated liquid', which supports the 'mass' origin.","cn":"同一词干给出 clod「土块」与 clot「凝结的一团」，这支持「团块」这一来源。"},{"era":"METAPHORICAL EXTENSION","en":"From the fourteenth century cloud was used for smoke, dust and figurative shadows, and in the twentieth century for networked computing.","cn":"14 世纪起 cloud 被用于烟、尘与比喻性的阴影，20 世纪又用于网络计算。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-English history of clūd is unsettled, and no reliable Latin cognate is established, so latinEntries is left empty.","cn":"来源不确定（更深词源）：clūd 在英语之前的历史无定论，也没有可靠的拉丁同族被确认，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one holds forms built on cloud that are easily confused with it; group two holds suspended obscurers of the air.","cn":"第一组是由本词加后缀构成、易与之混淆的形式；第二组是悬浮在空中、遮蔽视线的现象。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cloudy","ipa":"/ˈklaʊdi/","tag":"same root, adjective","definition":"Cloud plus -y: covered by cloud, or figuratively unclear; it describes a state, not a body.","definitionCN":"由 cloud 加 -y：被云覆盖的，或比喻不清楚；描述状态而非实体。"},{"word":"cloudless","ipa":"/ˈklaʊdləs/","tag":"same root, negative","definition":"Cloud plus -less: without cloud, used of a perfectly clear sky.","definitionCN":"由 cloud 加 -less：没有云的，用于完全晴朗的天空。"},{"word":"cloud cover","ipa":"/klaʊd ˈkʌvə/","tag":"technical compound","definition":"The measured fraction of sky hidden by cloud, not a single cloud.","definitionCN":"天空被云遮蔽的实测比例，而非单独一朵云。"}]},{"heading":"NEAR MEANING","entries":[{"word":"haze","ipa":"/heɪz/","tag":"dry obscuration","definition":"A suspension of fine dry particles that reduces visibility without forming a defined cloud.","definitionCN":"细微干燥颗粒的悬浮，降低能见度却不形成明确的云。"},{"word":"mist","ipa":"/mɪst/","tag":"light and shallow","definition":"Fine droplets reducing visibility at the surface, thinner and shallower than fog.","definitionCN":"使地面能见度下降的细微水滴，比雾更薄更浅。"},{"word":"fog","ipa":"/fɒɡ/","tag":"surface cloud","definition":"A cloud touching the ground that reduces visibility below one kilometre.","definitionCN":"触及地面、使能见度降到一公里以下的云。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English 'rock mass', the real related words and the real technical uses.","cn":"正常联想：真实的古英语「岩块」义、真实的同族词与真实的技术用法。"},"normal":[{"en":"Clūd first meant a rock mass; the sky sense came in the thirteenth century.","cn":"clūd 最初指岩块；天空义到 13 世纪才出现。"},{"en":"Clod and clot share the stock, which is why 'lump' is the core idea.","cn":"clod 与 clot 共享词干，因此「一团」是核心意思。"},{"en":"Fixed phrases: cloud cover, a cloud of smoke, under a cloud.","cn":"固定搭配：云量、一团烟、受怀疑。"},{"en":"The verb sense spreads: cloud the issue, cloud the glass.","cn":"动词义就是铺开：使问题模糊、使玻璃蒙上雾。"},{"en":"Cloud computing borrows the hiding image on purpose.","cn":"云计算故意借用了「遮蔽」这一意象。"}],"abstract":[{"en":"Picture a white lump that has no weight and no edge you can touch.","cn":"想象一团白色物体，没有重量，也没有能摸到的边。"},{"en":"Picture a shadow that arrives without a wall to cast it.","cn":"想象一片没有墙来投下它的阴影。"},{"en":"Picture a face where the light goes out in one second.","cn":"想象一张脸，光在一秒钟内熄灭。"}]},"examples":[{"en":"Cloud built along the ridge by early afternoon.","cn":"到午后早些时候，云已沿山脊聚起。"},{"en":"A cloud of ash closed the airport for a week.","cn":"一团火山灰使机场关闭了一周。"},{"en":"The treasurer clouded the accounts with vague categories.","cn":"财务主管用含糊的分类把账目弄得模糊不清。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"音近「克劳德」——天上飘着的一团白 → 云","word":"cloud"},"root":"古英语 clūd 原指「岩块、土丘」，13 世纪起指天空的云，取代旧词 weolcan；与 clod「土块」、clot「凝结的一团」同出一系，更深来源不确定，无可靠拉丁同族。","sensesIntro":{"en":"Eight senses all describe a floating mass that hides what is behind it: water in the sky, one visible cloud, measured cover, a shadow of trouble, smoke, remote data, a confused issue and a darkened face.","cn":"八个义项都在描述「遮住背后之物的悬浮团块」：天上的水、可见的一朵、实测的覆盖率、隐患的阴影、烟尘、远端数据、混乱的问题与阴沉的脸。"},"semanticMap":{"core":{"en":"CORE IMAGE: a floating lump with no fixed edge that nevertheless hides the light.","cn":"核心意象：一团没有固定边缘却仍能遮光的悬浮物。"},"chain":["MOIST AIR RISES","COOLS","CONDENSES","VISIBLE MASS","SPREADS","HIDES"],"branches":[{"senses":"01 · 02","en":"THE MASS: one physical body, seen either as a phenomenon or as a countable shape.","cn":"团块：同一个物理体，既可视为现象，也可视为可数的形状。"},{"senses":"03","en":"MEASURE: science turns the mass into a fraction of the sky.","cn":"量度：科学把云块变成天空的一个比例。"},{"senses":"04 · 08","en":"SHADOW: a threat and a mood both darken without blocking the day.","cn":"阴影：威胁与情绪都使天色变暗，却不阻断白昼。"},{"senses":"05","en":"ANY SUSPENSION: smoke and dust share shape and floating behaviour.","cn":"任何悬浮物：烟与尘共享形状与漂浮行为。"},{"senses":"06 · 07","en":"HIDING: remote data and confused issues are both made invisible by a cloud.","cn":"遮蔽：远端数据与混乱的问题都被一层云弄得看不见。"}]},"affixes":{"intro":{"en":"Cloud is a native English noun with an English derivational family; its compounds are transparent.","cn":"cloud 是英语本族名词，其派生词族属英语构词；复合词意义透明。"},"latinIntro":{"en":"No reliable Latin cognate is established for this word, so latinEntries is empty; the forms below are English.","cn":"该词没有可靠的拉丁同族被确认，因此 latinEntries 留空；以下形式均为英语构词。"},"items":[{"word":"cloud","structure":"cloud (Old English clūd, noun and verb)","meaning":"a floating mass; to obscure","meaningCN":"悬浮团块；使模糊","example":"Mist clouded the windscreen.","exampleCN":"雾气使挡风玻璃蒙上水汽。"},{"word":"-y","structure":"-y (adjective suffix)","meaning":"covered with; characterized by","meaningCN":"被……覆盖的；具有……特征的","example":"A cloudy sky kept the day cool.","exampleCN":"多云的天空使白天凉爽。"},{"word":"-less","structure":"-less (privative adjective suffix)","meaning":"without","meaningCN":"没有……的","example":"The cloudless night froze hard.","exampleCN":"无云的夜里霜冻很重。"},{"word":"-iness","structure":"-iness (noun suffix from -y adjectives)","meaning":"the state of being","meaningCN":"……的状态","example":"Cloudiness increased through the day.","exampleCN":"云量一天里不断增加。"},{"word":"cloud-","structure":"cloud (combining first element)","meaning":"of cloud","meaningCN":"云的","example":"Cloud streets lined the trade-wind sky.","exampleCN":"云街排列在信风区的天空。"},{"word":"-burst","structure":"-burst (combining noun, 'sudden break')","meaning":"a sudden heavy downpour","meaningCN":"突发的强降雨","example":"A cloudburst washed out the track.","exampleCN":"一场骤雨冲毁了小路。"},{"word":"-scape","structure":"-scape (combining noun, 'view')","meaning":"a view dominated by clouds","meaningCN":"以云为主的景致","example":"The cloudscape turned gold at sunset.","exampleCN":"日落时云景转成金色。"},{"word":"-cover","structure":"-cover (combining noun)","meaning":"the fraction of sky hidden","meaningCN":"天空被遮蔽的比例","example":"Cloud cover stayed below three eighths.","exampleCN":"云量保持在八分之三以下。"},{"word":"-seeded","structure":"-seeded (technical combining adjective)","meaning":"treated to induce rain","meaningCN":"经人工催化以降雨的","example":"Cloud-seeded valleys gained little water.","exampleCN":"人工催雨的谷地所得水量很少。"}],"latinEntries":[]}},{"word":"cloudy","ipa_uk":"/ˈklaʊdi/","ipa_us":"/ˈklaʊdi/","definition_zh":"多云的；阴天的；浑浊的；模糊不清的；阴郁的；乳白的","definition_en":"covered with cloud, or unclear because something is suspended or obscured","core_image":"整片天空被灰白层云糊住，太阳只剩一团模糊的亮斑","scene":"傍晚之前天一直灰着，直到风向变了才裂开几道缝。The sky stayed cloudy until the wind shifted at dusk.","sceneCN":"这里指「天空被云遮蔽的」（第 1 个义项：云量多、日光被挡的状态）；句意为天空一直多云，直到傍晚风向改变才裂开几道缝。图中可辨识物件：灰白的层云、只剩亮斑的太阳、被压平的天际线、渐起的风。","pos":[{"tag":"adj.","zh":"多云的；阴天的；浑浊的；模糊的；阴郁的；乳白的"}],"collocations":[{"phrase":"partly cloudy","zh":"局部多云"},{"phrase":"cloudy water","zh":"浑浊的水"},{"phrase":"a cloudy memory","zh":"模糊的记忆"},{"phrase":"cloudy skies","zh":"阴沉的天空"},{"phrase":"cloudy diamond","zh":"乳白钻石"},{"phrase":"cloudy with showers","zh":"多云有阵雨"}],"forms":[{"label":"比较级","form":"cloudier"},{"label":"最高级","form":"cloudiest"},{"label":"名词（多云；浑浊）","form":"cloudiness"},{"label":"副词（模糊地）","form":"cloudily"},{"label":"原名词（云）","form":"cloud"}],"derivatives":[{"word":"cloudiness","pos":"n.","zh":"多云；浑浊；模糊"},{"word":"cloudily","pos":"adv.","zh":"模糊地；浑浊地"},{"word":"cloud","pos":"n./v.","zh":"云；使模糊"},{"word":"cloudless","pos":"adj.","zh":"无云的"},{"word":"clouded","pos":"adj.","zh":"阴沉的；浑浊的"}],"senses":[{"no":"01","title":"Covered with cloud","titleCN":"天空被云覆盖","definition":"having much of the sky covered by cloud, so that sunlight is weak or diffuse","definitionCN":"天空大部分被云覆盖，阳光因而微弱或弥散","example":"The sky stayed cloudy until the wind shifted at dusk.","exampleCN":"天空一直多云，直到傍晚风向改变。","why":"Cloud plus -y: the suffix turns a body into a condition of the whole sky.","whyCN":"本词加形容词后缀：后缀把一团实体变成整个天空的状态。"},{"no":"02","title":"Grey and overcast weather","titleCN":"灰暗阴沉的天气","definition":"describing weather that is dull grey and without direct sun","definitionCN":"形容天气灰暗、没有直射阳光","example":"A cloudy morning turned into a bright afternoon.","exampleCN":"阴沉的早晨变成了明亮的下午。","why":"The word describes the light, not only the cloud: what matters is the absence of direct sun.","whyCN":"这个词描述的是光，而不只是云：关键在于没有直射阳光。"},{"no":"03","title":"Turbid with suspended particles","titleCN":"含悬浮物而浑浊","definition":"describing a liquid that is not clear because fine particles are suspended in it","definitionCN":"因细小颗粒悬浮其中而不清澈的液体","example":"The pond turned cloudy after the rain.","exampleCN":"雨后池塘变得浑浊。","why":"A liquid with suspended matter looks like a sky with cloud, so the same adjective serves.","whyCN":"含悬浮物的液体看起来像有云的天空，因此同一个形容词两处通用。"},{"no":"04","title":"Unclear in memory or thought","titleCN":"记忆或思路模糊不清","definition":"vague, imprecise or hard to recall, as a cloudy recollection","definitionCN":"含混、不精确或难以回忆的，如模糊的记忆","example":"Her recollection of that week remained cloudy.","exampleCN":"她对那一周的记忆仍然模糊。","why":"Obscured detail is like obscured light: the outline cannot be resolved.","whyCN":"被遮蔽的细节就像被遮蔽的光：轮廓无法分辨。"},{"no":"05","title":"Gloomy in expression or mood","titleCN":"表情或情绪阴沉","definition":"looking sad, worried or resentful, as a cloudy face","definitionCN":"显得悲伤、忧虑或恼恨的，如阴沉的脸","example":"He looked cloudy for the rest of the meeting.","exampleCN":"会议余下的时间里他一直面色阴沉。","why":"A face darkens like weather, which is why the weather adjective fits it.","whyCN":"脸像天气一样变暗，因此天气形容词适用于它。"},{"no":"06","title":"Milky or clouded in a gem","titleCN":"宝石呈乳白或雾状","definition":"describing a stone or glass that is milky rather than transparent","definitionCN":"形容宝石或玻璃呈乳白色而不透明","example":"The cloudy stone hid a faint pattern inside.","exampleCN":"这块乳白石里头藏着一道淡淡的纹路。","why":"Internal scatterers make a solid look like a small weather system.","whyCN":"内部散射物使固体看起来像一个小小的天气系统。"},{"no":"07","title":"Partly cloudy in a forecast","titleCN":"预报中的局部多云","definition":"the forecast term for a sky with some cloud but also clear intervals","definitionCN":"预报术语，指天空有云但仍有晴空间隙","example":"Tomorrow will be partly cloudy with a light breeze.","exampleCN":"明天局部多云，微风。","why":"Forecasts need grades of cloud, and partly marks the middle of the scale.","whyCN":"预报需要对云量分级，而这一术语正标记量级的中间档。"},{"no":"08","title":"Vague or suspect in origin","titleCN":"来历含糊可疑","definition":"not clearly explained or of doubtful origin, as a cloudy title","definitionCN":"解释不清或来历可疑的，如含糊的名目","example":"The land was held under a cloudy title.","exampleCN":"这块地以一个含糊的名目被持有。","why":"A claim that cannot be seen through is cloudy in the same sense as water or memory.","whyCN":"看不透的主张，与水或记忆一样，都是含混的。"}],"etymology":{"intro":{"en":"Cloudy is cloud plus the native adjective suffix -y, from Old English -ig. The base clūd first meant a mass of rock and only later a cloud, so the adjective inherited an already metaphorical noun.","cn":"cloudy 由 cloud 加本族形容词后缀 -y（古英语 -ig）构成。词基 clūd 最初指岩块，后来才指云，因此这个形容词继承了一个本已带比喻色彩的名词。"},"items":[{"era":"OLD ENGLISH -IG","en":"The suffix -ig formed adjectives meaning 'having the quality of', and survives as modern -y in cloudy, rainy and windy.","cn":"后缀 -ig 构成表示「具有……性质」的形容词，并在 cloudy、rainy、windy 中保留为现代 -y。"},{"era":"CLOUD SENSE ARRIVES","en":"Once cloud meant a sky cloud in the thirteenth century, the adjective could describe a covered sky.","cn":"13 世纪 cloud 开始指天空之云之后，这个形容词才能描述被覆盖的天空。"},{"era":"WATER AND STONE EXTENSIONS","en":"The turbid-liquid and milky-stone senses follow the same shape: suspended matter scattering light.","cn":"浑浊液体与乳白宝石义遵循同一形状：悬浮物散射光线。"},{"era":"FIGURATIVE EXTENSION","en":"From the sixteenth century cloudy also described unclear thought and gloomy looks.","cn":"从 16 世纪起，cloudy 也用于描述不清的思路与阴沉的神情。"},{"era":"FORECAST CONVENTION","en":"Modern weather services grade the term, giving partly cloudy, mostly cloudy and overcast.","cn":"现代气象服务对该词分级，给出局部多云、大部多云与阴。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (base-word origin only): the deeper history of clūd is unsettled, though the derivation cloud plus -y is certain.","cn":"来源不确定（仅词基来源）：clūd 的更深历史无定论，但 cloud 加 -y 的派生关系是确定的。"}]},"similar":{"note":{"en":"Group one holds forms of the same base that differ in meaning; group two holds adjectives for air that cannot be seen through.","cn":"第一组是同一词基的不同形式，含义有别；第二组是表示空气看不透的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cloud","ipa":"/klaʊd/","tag":"base noun","definition":"The body itself, countable; cloudy describes the state it produces.","definitionCN":"实体本身，可数；cloudy 描述它造成的状态。"},{"word":"cloudless","ipa":"/ˈklaʊdləs/","tag":"opposite","definition":"Without cloud; the direct negative of cloudy.","definitionCN":"没有云的；cloudy 的直接反义。"},{"word":"clouded","ipa":"/ˈklaʊdɪd/","tag":"participial adjective","definition":"Made unclear or darkened, often by a specific cause, as clouded glass or a clouded mind.","definitionCN":"被弄模糊或变暗，常带具体成因，如蒙上雾的玻璃或混乱的头脑。"}]},{"heading":"NEAR MEANING","entries":[{"word":"overcast","ipa":"/ˌəʊvəˈkɑːst/","tag":"fully covered","definition":"Completely covered by cloud; stronger than cloudy, which allows breaks.","definitionCN":"完全被云覆盖；比 cloudy 更强，后者允许云隙。"},{"word":"murky","ipa":"/ˈmɜːki/","tag":"dark and dirty","definition":"Dark and dirty, used of water or air; it adds dimness that cloudy does not.","definitionCN":"又暗又脏，用于水或空气；带有 cloudy 所无的昏暗感。"},{"word":"hazy","ipa":"/ˈheɪzi/","tag":"dry obscuration","definition":"Obscured by fine dry particles rather than by cloud or droplets.","definitionCN":"被细微干燥颗粒而非云或水滴遮蔽。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English suffix, the real sense extensions and the real forecast grades.","cn":"正常联想：真实的古英语后缀、真实的义项扩展与真实的预报分级。"},"normal":[{"en":"Cloud plus the native -y, as in rainy, windy and sunny.","cn":"cloud 加本族 -y，正如 rainy、windy、sunny。"},{"en":"One adjective covers sky, water, stone, memory and mood.","cn":"一个形容词同时覆盖天空、水、石头、记忆与情绪。"},{"en":"Forecast grades: partly cloudy, mostly cloudy, overcast.","cn":"预报分级：局部多云、大部多云、阴。"},{"en":"Overcast is stronger; cloudy allows breaks of blue.","cn":"overcast 更强；cloudy 允许露出蓝天。"},{"en":"The medical and legal senses keep the idea of an unclear title.","cn":"医学与法律用法保留「名目不清」的意思。"}],"abstract":[{"en":"Picture a sky with the sun reduced to a pale coin.","cn":"想象太阳被压成一枚淡色硬币的天空。"},{"en":"Picture a glass of water you cannot see through.","cn":"想象一杯看不透的水。"},{"en":"Picture a memory with its edges rubbed away.","cn":"想象一段边缘被磨掉的记忆。"}]},"examples":[{"en":"It was cloudy at dawn but cleared by ten.","cn":"黎明时多云，到十点就放晴了。"},{"en":"The solution turned cloudy when the second reagent was added.","cn":"加入第二种试剂后，溶液变浑浊了。"},{"en":"His account of the accident remained cloudy in places.","cn":"他对事故的叙述有些地方仍然含糊。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「cloud（云）+ y（多的）」——云多的 → 多云的、浑浊的","word":"cloudy"},"root":"由 cloud（古英语 clūd，原指岩块，13 世纪起指云）+ 本族后缀 -y（古英语 -ig）构成；更深来源不确定，无可靠拉丁同族。","sensesIntro":{"en":"Eight senses all describe light that cannot get through: cloud in the sky, grey weather, turbid water, vague memory, gloomy mood, milky stone, graded forecast cloud and an unclear claim.","cn":"八个义项都在描述「光透不过去」：天上的云、灰暗天气、浑浊的水、模糊的记忆、阴郁的情绪、乳白的石头、分级的预报云量与含糊的主张。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pale veil that lets light through but takes away every sharp edge.","cn":"核心意象：一层让光透过来、却抹掉所有锐利边缘的灰白帷幕。"},"chain":["CLOUD FORMS","SUN DIFFUSED","EDGES SOFTENED","DETAIL LOST","MEANING BLURRED","STATE NAMED"],"branches":[{"senses":"01 · 02 · 07","en":"SKY: the physical cover, its grey light and its forecast grades.","cn":"天空：物理覆盖、灰暗光线与预报分级。"},{"senses":"03 · 06","en":"MATTER: suspended particles in water or stone scatter light the same way.","cn":"物质：水或石头中的悬浮颗粒以同样方式散射光。"},{"senses":"04","en":"MEMORY: detail that cannot be resolved is literally unclear.","cn":"记忆：无法分辨的细节，字面上就是不清楚。"},{"senses":"05","en":"MOOD: a face behaves like a sky with something passing over it.","cn":"情绪：脸像天空，有东西从上面掠过。"},{"senses":"08","en":"CLAIM: a title no one can see through is cloudy in the same sense.","cn":"主张：无人能看透的名目，在同一意义上也是含混的。"}]},"affixes":{"intro":{"en":"Cloudy is a native English adjective formed with the productive suffix -y; its family is small and transparent.","cn":"cloudy 是用能产后缀 -y 构成的英语本族形容词；其词族小而透明。"},"latinIntro":{"en":"No Latin element builds this word; the base noun has no reliable Latin cognate, so latinEntries is empty.","cn":"本词不含拉丁构词成分；词基名词没有可靠的拉丁同族，因此 latinEntries 留空。"},"items":[{"word":"cloud","structure":"cloud (Old English clūd, base noun)","meaning":"a mass of condensed water","meaningCN":"凝结水形成的团块","example":"Cloud filled the valley by noon.","exampleCN":"到正午云已填满山谷。"},{"word":"-y","structure":"-y (native adjective suffix, Old English -ig)","meaning":"having the quality of; full of","meaningCN":"具有……性质；充满……","example":"A cloudy sky kept the heat in.","exampleCN":"多云的天空把热量留住了。"},{"word":"-iness","structure":"-iness (noun suffix from -y adjectives)","meaning":"the state of being","meaningCN":"……的状态","example":"Cloudiness reduced the solar gain.","exampleCN":"云量减少了太阳得热。"},{"word":"-ily","structure":"-ily (adverb suffix from -y adjectives)","meaning":"in that manner","meaningCN":"以那种方式","example":"The rules were cloudily worded.","exampleCN":"规则措辞含糊。"},{"word":"partly","structure":"part + -ly (degree modifier)","meaning":"to some extent","meaningCN":"部分地","example":"Partly cloudy skies are forecast.","exampleCN":"预报局部多云。"},{"word":"mostly","structure":"most + -ly (degree modifier)","meaning":"for the greater part","meaningCN":"大部分地","example":"Mostly cloudy conditions persisted.","exampleCN":"大部多云的状态持续。"},{"word":"-less","structure":"-less (privative suffix)","meaning":"without cloud","meaningCN":"没有云的","example":"A cloudless noon followed.","exampleCN":"随后是一个无云的正午。"},{"word":"-ed","structure":"-ed (participial suffix)","meaning":"made unclear","meaningCN":"被弄模糊的","example":"Clouded glass hid the view.","exampleCN":"蒙上雾的玻璃挡住了视线。"},{"word":"-burst","structure":"-burst (combining noun, 'sudden break')","meaning":"a sudden downpour from cloud","meaningCN":"云中突然倾落的雨","example":"A cloudburst flooded the lane.","exampleCN":"骤雨淹了小巷。"}],"latinEntries":[]}}]);
